INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-salmon---the-big-catch-usa', 'Genesis', 'King Salmon - The Big Catch (USA)', '1993', 'Sports', 'Sega', '2', 'Simulation', 'Sports simulation focusing on lure selection, casting, and reeling mechanics.', 'Catch the largest King Salmon to win seasonal tournaments.', 'A realistic sport fishing simulator for Sega Genesis.', 'Experience professional fishing in King Salmon: The Big Catch. Master lure depth and tension to land trophy-sized salmon in this classic Sega Genesis sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-salmon-japan', 'Genesis', 'King Salmon (Japan)', '1993', 'Sports', 'Sega', '2', 'Simulation', 'Sports simulation focusing on lure selection, casting, and reeling mechanics.', 'Catch the largest King Salmon to win seasonal tournaments.', 'A realistic sport fishing simulator for Sega Genesis.', 'Experience professional fishing in King Salmon. Master lure depth and tension to land trophy-sized salmon in this classic Sega Genesis sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kings-bounty---the-conquerors-quest-usa-europe', 'Genesis', 'King''s Bounty - The Conqueror''s Quest (USA, Europe)', '1990', 'Strategy', 'Rare', '1', 'Turn-Based', 'Turn-based strategy and tactical combat with RPG exploration elements.', 'Recruit an army and find the 25 pieces of a lost map to recover the Scepter of Order.', 'A precursor to Heroes of Might and Magic on Sega Genesis.', 'Command a legendary army in King''s Bounty: The Conqueror''s Quest. Explore vast lands, manage resources, and engage in tactical turn-based combat to save the kingdom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-in-sonic-the-hedgehog', 'Genesis', 'Kirby in Sonic the Hedgehog', '1991', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming using Kirby''s physics within Sonic''s world.', 'Complete classic Sonic levels as Kirby.', 'A unique rom-hack crossing Kirby into the world of Sonic 1.', 'Play as the pink puffball in Kirby in Sonic the Hedgehog. This creative mod blends Kirby''s charm with Sonic''s iconic levels for a fresh retro platforming experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-in-sonic-the-hedgehog-2', 'Genesis', 'Kirby in Sonic the Hedgehog 2', '1992', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming using Kirby''s physics within Sonic 2''s stages.', 'Navigate through Chemical Plant and beyond to defeat Eggman as Kirby.', 'Kirby enters the world of Sonic the Hedgehog 2.', 'Double the speed and double the fun with Kirby in Sonic the Hedgehog 2. Experience the classic 16-bit sequel with Kirby’s unique movement mechanics and style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kishi-densetsu-japan', 'Genesis', 'Kishi Densetsu (Japan)', '1991', 'Action', 'NCS', '1', 'Side-Scrolling', 'Tactical role-playing game with menu-based combat and exploration.', 'Journey through a fantasy world to defeat ancient evils.', 'A Japanese exclusive tactical RPG for the Mega Drive.', 'Kishi Densetsu (Legend of the Knight) offers deep strategy and RPG storytelling. Explore a rich fantasy world and master tactical combat in this Japanese Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klax-japan', 'Genesis', 'Klax (Japan)', '1990', 'Puzzle', 'Tengen', '2', 'Arcade', 'Puzzle action requiring players to catch and stack colored tiles.', 'Arrange falling tiles by color to clear rows and prevent the stack from reaching the top.', 'A fast-paced, addictive puzzle game for the Sega Genesis.', 'It''s the nineties and there is time for Klax! Master this challenging arcade port that combines timing and color-matching strategy for endless puzzle fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klax-usa', 'Genesis', 'Klax (USA)', '1990', 'Puzzle', 'Tengen', '2', 'Arcade', 'Puzzle action requiring players to catch and stack colored tiles.', 'Arrange falling tiles by color to clear rows and prevent the stack from reaching the top.', 'A fast-paced, addictive puzzle game for the Sega Genesis.', 'It''s the nineties and there is time for Klax! Master this challenging arcade port that combines timing and color-matching strategy for endless puzzle fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knuckles-and-knuckles-2-v1', 'Genesis', 'Knuckles and Knuckles 2 V1', '2022', 'Action', 'Fan Hack', '1', 'Platformer', 'Platforming action featuring multiple Knuckles characters.', 'Use Knuckles'' gliding and climbing abilities to finish the game.', 'A humorous rom-hack featuring an abundance of Knuckles.', 'Knuckles and Knuckles 2 V1 takes the meme to the next level. Enjoy enhanced platforming with everyone''s favorite echidna in this unique community modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knuckles-goes-to-gaiden-land', 'Genesis', 'Knuckles Goes To Gaiden Land', '2021', 'Action', 'Fan Hack', '1', 'Platformer', 'Side-scrolling action platformer modified for Knuckles.', 'Navigate through custom or modified stages to reach the end.', 'A fan-made adventure starring Knuckles the Echidna.', 'Join Knuckles in Gaiden Land for a unique platforming challenge. Utilize his signature moves to conquer new environments and classic obstacles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knuckles-in-sonic-1---super-knuckles-mode-2023-update', 'Genesis', 'Knuckles in Sonic 1 - Super Knuckles Mode (2023 Update)', '2023', 'Action', 'Fan Hack', '1', 'Platformer', '2D platforming with Super Knuckles'' enhanced speed and jumping.', 'Collect 50 rings and transform into Super Knuckles to beat the game.', 'The definitive Super Knuckles experience in Sonic 1.', 'Revisit the origins of Sonic 1 with a twist. Knuckles in Sonic 1 (2023 Update) brings modern polish and Super Mode abilities to the classic 16-bit stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knuckles-knuckles-&-knuckles', 'Genesis', 'Knuckles, Knuckles & Knuckles', '2022', 'Action', 'Fan Hack', '1', 'Platformer', 'Multi-character platforming with Knuckles clones.', 'Navigate levels using the unique physics of Knuckles.', 'A chaotic Knuckles-themed modification of the Sonic engine.', 'Experience the ultimate echidna party in Knuckles, Knuckles & Knuckles. A fun and frantic take on the Sega Genesis platforming formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knuckles-emerald-hunt', 'Genesis', 'Knuckles'' Emerald Hunt', '2021', 'Action', 'Fan Hack', '1', 'Exploration', 'Exploration-based platforming focusing on item collection.', 'Search for hidden Chaos Emeralds across various levels.', 'A treasure-hunting game starring Knuckles the Echidna.', 'Put your tracking skills to the test in Knuckles'' Emerald Hunt. Explore vertical stages and use your radar to find the lost gems in this fan-favorite mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koutetsu-teikoku-japan', 'Genesis', 'Koutetsu Teikoku (Japan)', '1992', 'Strategy', 'Hot-B', '1', 'Turn-Based', 'Side-scrolling shoot ''em up with a distinct steampunk aesthetic.', 'Pilot a zeppelin and destroy enemy fleets to save the empire.', 'A gorgeous steampunk shmup known as Steel Empire.', 'Koutetsu Teikoku (Steel Empire) is a visual masterpiece on the Mega Drive. Fight through waves of industrial enemies in this highly acclaimed 16-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('krustys-super-fun-house-usa-europe', 'Genesis', 'Krusty''s Super Fun House (USA, Europe)', '1992', 'Platformer', 'Audiogenic', '2', 'Action', 'Puzzle-platformer involving guiding mice through traps.', 'Lead a specific number of mice to the exit in each level to progress.', 'Krusty the Clown''s unique puzzle adventure.', 'Help Krusty manage a pest problem in Krusty''s Super Fun House. Solve intricate environmental puzzles in this classic Simpsons-themed platformer for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('krustys-super-fun-house-usa-europe-v11', 'Genesis', 'Krusty''s Super Fun House (USA, Europe) (v1.1)', '1992', 'Platformer', 'Audiogenic', '2', 'Action', 'Puzzle-platformer involving guiding mice through traps.', 'Lead a specific number of mice to the exit in each level to progress.', 'Krusty the Clown''s unique puzzle adventure (v1.1).', 'Help Krusty manage a pest problem in Krusty''s Super Fun House. Solve intricate environmental puzzles in this refined version of the Simpsons classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kujaku-ou-2---geneijou-japan', 'Genesis', 'Kujaku Ou 2 - Geneijou (Japan)', '1990', 'Action', 'Taito', '1', 'Arcade', 'Side-scrolling action with horror and mythological themes.', 'Battle demons and supernatural bosses to progress through the story.', 'A dark fantasy action game known as Mystic Defender.', 'Kujaku Ou 2 - Geneijou offers intense action and atmospheric visuals. Unleash powerful magic against terrifying monsters in this Japanese Mega Drive classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kunio-no-nekketsu-school-fighters-beta-v01-brazil-unl', 'Genesis', 'Kunio no Nekketsu School Fighters (beta v.01) (Brazil) (Unl)', '1994', 'Fighting', 'Technos Japan', '2', 'Competitive', '2D side-scrolling beat ''em up featuring high school brawlers.', 'Defeat rival gangs in street combat to become the top school.', 'An unlicensed Brazilian port of the Nekketsu series.', 'Experience street fighting at its finest in Kunio no Nekketsu School Fighters. A rare and energetic beat ''em up for the Sega Genesis enthusiast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kuuga---operation-code-vapor-trail-japan', 'Genesis', 'Kuuga - Operation Code ''Vapor Trail'' (Japan)', '1991', 'Shooter', 'Sega AM2', '2', 'Arcade', 'Vertical-scrolling shoot ''em up with selectable aircraft.', 'Blast through enemy defenses and massive bosses across various biomes.', 'A high-octane arcade port shmup (Vapor Trail).', 'Take to the skies in Kuuga - Operation Code ''Vapor Trail''. Experience intense bullet-hell action and a rocking soundtrack in this premier Mega Drive shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kyuukai-douchuuki-japan', 'Genesis', 'Kyuukai Douchuuki (Japan)', '1991', 'Sports', 'Sega', '2', 'Simulation', 'Arcade-style baseball featuring various mini-games.', 'Win baseball games or complete specific skill challenges.', 'A quirky Japanese baseball title with a unique art style.', 'Kyuukai Douchuuki brings a fun, arcade twist to the sport of baseball. Enjoy fast-paced pitches and charming animations on the Sega Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kyuukyoku-tiger-japan', 'Genesis', 'Kyuukyoku Tiger (Japan)', '1989', 'Shooter', 'Toaplan', '2', 'Arcade', 'Vertical-scrolling shoot ''em up featuring tanks and aircraft.', 'Eliminate enemy forces and survive intense projectile patterns.', 'The definitive home port of the arcade hit Twin Cobra.', 'Kyuukyoku Tiger (Twin Cobra) is a masterclass in shmup design. Pilot your attack helicopter through waves of enemies in this legendary Toaplan shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('la-russa-baseball-95-usa-australia', 'Genesis', 'La Russa Baseball 95 (USA, Australia)', '1994', 'Sports', 'Sega', '2', 'Simulation', 'Realistic baseball simulation with licensed players and stats.', 'Win the World Series by managing rosters and playing games.', 'A professional baseball sim endorsed by Tony La Russa.', 'Step up to the plate with La Russa Baseball 95. Featuring deep strategy and realistic gameplay, it''s a must-play for fans of 16-bit sports simulations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lakers-versus-celtics-and-the-nba-playoffs-usa', 'Genesis', 'Lakers Versus Celtics and the NBA Playoffs (USA)', '1990', 'Sports', 'Electronic Arts', '4', 'Simulation', 'Professional basketball simulation with playoff-style progression.', 'Win the NBA Championship by defeating rival teams in the playoffs.', 'The game that started the EA Sports NBA series.', 'Relive the legendary rivalry in Lakers Versus Celtics and the NBA Playoffs. Experience the foundations of modern basketball gaming on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('landstalker---die-schatze-von-konig-nolo-germany', 'Genesis', 'Landstalker - Die Schatze von Konig Nolo (Germany)', '1992', 'Action-Adventure', 'Climax Entertainment', '1', 'Isometric', 'Action-adventure RPG with isometric platforming and puzzles.', 'Find the treasure of King Nole while exploring a vast island.', 'The German version of the isometric classic Landstalker.', 'Embark on an epic quest in Landstalker. Solve complex 3D puzzles and explore a vibrant world in this highly-regarded German localized edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('landstalker---koutei-no-zaihou-japan', 'Genesis', 'Landstalker - Koutei no Zaihou (Japan)', '1992', 'Action-Adventure', 'Climax Entertainment', '1', 'Isometric', 'Action-adventure RPG with isometric platforming and puzzles.', 'Find the treasure of King Nole while exploring a vast island.', 'The original Japanese version of the classic Landstalker.', 'Discover the origins of Nigel’s adventure in Landstalker (Koutei no Zaihou). A pioneer of isometric gameplay on the Sega Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('landstalker---le-tresor-du-roi-nole-france', 'Genesis', 'Landstalker - Le Tresor du Roi Nole (France)', '1992', 'Action-Adventure', 'Climax Entertainment', '1', 'Isometric', 'Action-adventure RPG with isometric platforming and puzzles.', 'Find the treasure of King Nole while exploring a vast island.', 'The French version of the isometric classic Landstalker.', 'Vivez une aventure épique dans Landstalker. Explorez l''île, résolvez des énigmes et trouvez le trésor du Roi Nole dans cette version française.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('landstalker---the-treasures-of-king-nole-europe', 'Genesis', 'Landstalker - The Treasures of King Nole (Europe)', '1992', 'Action-Adventure', 'Climax Entertainment', '1', 'Isometric', 'Action-adventure RPG with isometric platforming and puzzles.', 'Find the treasure of King Nole while exploring a vast island.', 'The European English version of Landstalker.', 'Set out on a massive journey in Landstalker. Navigate tricky isometric platforms and defeat challenging bosses in this European 16-bit RPG classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('landstalker-usa', 'Genesis', 'Landstalker (USA)', '1993', 'Action-Adventure', 'Climax Entertainment', '1', 'Isometric', 'Action-adventure RPG with isometric platforming and puzzles.', 'Find the treasure of King Nole while exploring a vast island.', 'The North American release of the isometric masterpiece.', 'Landstalker is a landmark title for the Sega Genesis. Experience deep RPG mechanics, witty dialogue, and challenging environmental puzzles in this timeless adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('landstalker-usa-beta', 'Genesis', 'Landstalker (USA) (Beta)', '1992', 'Action-Adventure', 'Climax Entertainment', '1', 'Isometric', 'Action-adventure RPG with isometric platforming and puzzles.', 'Find the treasure of King Nole while exploring a vast island.', 'A pre-release beta version of Landstalker.', 'Explore the development history of a classic with the Landstalker Beta. See early designs and mechanics of this beloved isometric adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('langrisser-japan', 'Genesis', 'Langrisser (Japan)', '1991', 'Strategy', 'Masaya', '1', 'Tactical RPG', 'Tactical turn-based RPG with unit management and branching paths.', 'Lead your army to victory and choose your moral path through battle.', 'The first entry in the legendary Langrisser strategy series.', 'Langrisser (Warsong) defines 16-bit tactical RPGs. Manage huge armies and experience a branching narrative in this Japanese Mega Drive essential.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('langrisser-ii-japan', 'Genesis', 'Langrisser II (Japan)', '1994', 'Strategy', 'Masaya', '1', 'Tactical RPG', 'Tactical turn-based strategy with large-scale army management.', 'Command troops and heroes to defeat the Rayguard Empire.', 'The acclaimed sequel to the Langrisser strategy series.', 'Langrisser II is a tactical masterpiece on the Mega Drive. Lead massive armies, utilize terrain advantages, and experience a deep branching narrative in this strategy classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('langrisser-ii-japan-v11', 'Genesis', 'Langrisser II (Japan) (v1.1)', '1994', 'Strategy', 'Masaya', '1', 'Tactical RPG', 'Tactical turn-based strategy with large-scale army management.', 'Command troops and heroes to defeat the Rayguard Empire.', 'The acclaimed sequel to the Langrisser strategy series (v1.1).', 'Langrisser II is a tactical masterpiece on the Mega Drive. Lead massive armies, utilize terrain advantages, and experience a deep branching narrative in this strategy classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('langrisser-ii-japan-v12', 'Genesis', 'Langrisser II (Japan) (v1.2)', '1994', 'Strategy', 'Masaya', '1', 'Tactical RPG', 'Tactical turn-based strategy with large-scale army management.', 'Command troops and heroes to defeat the Rayguard Empire.', 'The acclaimed sequel to the Langrisser strategy series (v1.2).', 'Langrisser II is a tactical masterpiece on the Mega Drive. Lead massive armies, utilize terrain advantages, and experience a deep branching narrative in this strategy classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('langrisser-ii-japan-v12-en-by-mijet-v20081106', 'Genesis', 'Langrisser II (Japan) (v1.2) [En by MIJET v20081106]', '1994', 'Strategy', 'Masaya', '1', 'Tactical RPG', 'Tactical turn-based strategy with large-scale army management.', 'Command troops and heroes to defeat the Rayguard Empire.', 'English fan translation of the strategy classic Langrisser II.', 'Experience Langrisser II fully translated into English. Command your legions and master the 16-bit tactical combat that defined the strategy genre on the Sega Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('last-action-hero-usa-europe', 'Genesis', 'Last Action Hero (USA, Europe)', '1993', 'Action', 'Bits Studios', '1', 'Side-Scrolling', 'Side-scrolling beat ''em up and platformer based on the movie.', 'Fight through movie-set levels to defeat Benedict and the Ripper.', 'The official video game tie-in for Last Action Hero.', 'Step into the boots of Jack Slater in Last Action Hero. Punch and kick your way through cinematic stages in this action-packed Sega Genesis movie adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('last-battle-usa-europe', 'Genesis', 'Last Battle (USA, Europe)', '1989', 'Action', 'Sega', '1', 'Beat ''em Up', 'Post-apocalyptic side-scrolling martial arts action.', 'Defeat the three generals and the ultimate boss, Garone.', 'A gritty martial arts brawler set in a desolate world.', 'Last Battle brings intense martial arts action to the Sega Genesis. Navigate a dangerous wasteland and unleash powerful strikes to save your loved ones in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lawnmower-man-the-usa-europe', 'Genesis', 'Lawnmower Man, The (USA, Europe)', '1994', 'Action', 'Roadrunner Software', '1', 'Sci-Fi', 'Multi-genre action including platforming and 3D wireframe levels.', 'Prevent Jobe from taking over the global computer network.', 'A unique adaptation of the sci-fi film The Lawnmower Man.', 'Enter the virtual world of The Lawnmower Man. Experience a mix of traditional platforming and early 3D flight sequences in this ambitious 16-bit Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-galahad-the-usa-europe', 'Genesis', 'Legend of Galahad, The (USA, Europe)', '1993', 'Action-Adventure', 'Probe Software', '1', 'Isometric', 'Side-scrolling action platformer with exploration elements.', 'Navigate through fantasy levels to recover a legendary sword.', 'A high-fantasy action adventure for the Sega Genesis.', 'Join Galahad on a quest for glory in The Legend of Galahad. Face mythical creatures and master challenging platforming segments in this visually impressive Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legende-de-thor-la-france', 'Genesis', 'Legende de Thor, La (France)', '1993', 'Action-Adventure', 'Probe Software', '1', 'Isometric', 'Top-down action-adventure with real-time combat and puzzle-solving.', 'Use elemental spirits to stop the resurrection of an ancient evil.', 'The French version of the hit RPG Beyond Oasis.', 'La Légende de Thor (Beyond Oasis) is a stunning action RPG. Summon powerful spirits and engage in fluid combat to save the land of Oasis in this French localized edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-batman-unl', 'Genesis', 'Lego Batman (Unl)', '2018', 'Platformer', 'Unlicensed', '1', 'Action', 'Action-platformer featuring brick-based characters and environments.', 'Defeat Gotham''s villains using Batman''s gadgets.', 'An unlicensed 16-bit take on the Lego Batman franchise.', 'Explore a unique interpretation of Lego Batman on the Genesis. Fight crime and navigate blocky levels in this rare and unofficial 16-bit superhero adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-pirates-of-the-caribbean-unl', 'Genesis', 'Lego Pirates of the Caribbean (Unl)', '2017', 'Platformer', 'Unlicensed', '1', 'Action', 'Side-scrolling action featuring Lego-style pirates.', 'Navigate through levels inspired by the film series.', 'An unlicensed pirate-themed platformer for Sega.', 'Embark on a brick-built high seas adventure in Lego Pirates of the Caribbean. A rare, unofficial title that brings swashbuckling action to the 16-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-europe', 'Genesis', 'Lemmings (Europe)', '1991', 'Puzzle', 'DMA Design', '2', 'Strategy', 'Puzzle strategy where you guide creatures through hazards.', 'Guide a specific percentage of Lemmings safely to the exit.', 'The legendary puzzle game ported to the Mega Drive.', 'Test your logic and timing in Lemmings. Assign roles to your tiny followers to bridge gaps and dig tunnels in this addictive and challenging puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-japan', 'Genesis', 'Lemmings (Japan)', '1991', 'Puzzle', 'DMA Design', '2', 'Strategy', 'Puzzle strategy where you guide creatures through hazards.', 'Guide a specific percentage of Lemmings safely to the exit.', 'The Japanese version of the iconic puzzle game Lemmings.', 'Experience the puzzle phenomenon Lemmings on the Mega Drive. Solve increasingly complex environmental riddles to save your green-haired friends from disaster.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-usa', 'Genesis', 'Lemmings (USA)', '1991', 'Puzzle', 'DMA Design', '2', 'Strategy', 'Puzzle strategy where you guide creatures through hazards.', 'Guide a specific percentage of Lemmings safely to the exit.', 'The classic puzzle game Lemmings for the Sega Genesis.', 'Lemmings brings the ultimate test of wit to your console. Master the different skills and navigate treacherous terrain in this beloved 16-bit logic game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-2---the-tribes-europe', 'Genesis', 'Lemmings 2 - The Tribes (Europe)', '1993', 'Puzzle', 'DMA Design', '2', 'Strategy', 'Puzzle strategy featuring diverse tribes with unique skills.', 'Help various Lemming tribes reclaim their fragments of the talisman.', 'The ambitious sequel to the original Lemmings.', 'Lemmings 2: The Tribes expands the puzzle gameplay with new skills and themes. Lead multiple tribes through hundreds of levels in this deep and creative sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-2---the-tribes-usa', 'Genesis', 'Lemmings 2 - The Tribes (USA)', '1993', 'Puzzle', 'DMA Design', '2', 'Strategy', 'Puzzle strategy featuring diverse tribes with unique skills.', 'Help various Lemming tribes reclaim their fragments of the talisman.', 'The North American release of Lemmings 2: The Tribes.', 'Lemmings 2: The Tribes expands the puzzle gameplay with new skills and themes. Lead multiple tribes through hundreds of levels in this deep and creative sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lethal-enforcers-europe', 'Genesis', 'Lethal Enforcers (Europe)', '1992', 'Shooter', 'Konami', '2', 'Light Gun', 'Light-gun shooter focusing on speed and accuracy.', 'Take down criminals and progress through various urban scenarios.', 'The home version of the arcade hit Lethal Enforcers.', 'Step into the shoes of a lawman in Lethal Enforcers. Experience high-stakes shooting action that supports the Menacer or Justifier light guns on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lethal-enforcers-japan', 'Genesis', 'Lethal Enforcers (Japan)', '1992', 'Shooter', 'Konami', '2', 'Light Gun', 'Light-gun shooter focusing on speed and accuracy.', 'Take down criminals and progress through various urban scenarios.', 'The Japanese version of the arcade shooter Lethal Enforcers.', 'Lethal Enforcers brings authentic arcade shooting to the Mega Drive. Engage in fast-paced gunplay and test your reflexes against the city''s most dangerous criminals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lethal-enforcers-usa', 'Genesis', 'Lethal Enforcers (USA)', '1992', 'Shooter', 'Konami', '2', 'Light Gun', 'Light-gun shooter focusing on speed and accuracy.', 'Take down criminals and progress through various urban scenarios.', 'The definitive North American light-gun shooter for Genesis.', 'Experience the thrill of the arcade at home with Lethal Enforcers. Use your reflexes to protect the city in this iconic 16-bit rail shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lethal-enforcers-ii---gun-fighters-europe', 'Genesis', 'Lethal Enforcers II - Gun Fighters (Europe)', '1994', 'Shooter', 'Konami', '2', 'Light Gun', 'Light-gun shooter set in the Old West.', 'Clean up the frontier by defeating outlaws and bandits.', 'The Western-themed sequel to Lethal Enforcers.', 'Saddle up for Lethal Enforcers II: Gun Fighters. Master the quick-draw and clear out the lawless frontier in this intense Western light-gun adventure for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lethal-enforcers-ii---gun-fighters-usa', 'Genesis', 'Lethal Enforcers II - Gun Fighters (USA)', '1994', 'Shooter', 'Konami', '2', 'Light Gun', 'Light-gun shooter set in the Old West.', 'Clean up the frontier by defeating outlaws and bandits.', 'The North American Western sequel to Lethal Enforcers.', 'Saddle up for Lethal Enforcers II: Gun Fighters. Master the quick-draw and clear out the lawless frontier in this intense Western light-gun adventure for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lhx-attack-chopper-japan', 'Genesis', 'LHX Attack Chopper (Japan)', '1990', 'Simulation', 'Electronic Arts', '1', 'Combat Flight', '3D helicopter combat simulation with multiple mission types.', 'Complete various military objectives using advanced attack choppers.', 'A sophisticated 3D flight sim for the Mega Drive.', 'Take command of the LHX Attack Chopper. Experience early 3D graphics and complex flight missions in this technical showcase for the 16-bit Sega console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lhx-attack-chopper-usa-europe', 'Genesis', 'LHX Attack Chopper (USA, Europe)', '1990', 'Simulation', 'Electronic Arts', '1', 'Combat Flight', '3D helicopter combat simulation with multiple mission types.', 'Complete various military objectives using advanced attack choppers.', 'A sophisticated 3D flight sim for the Sega Genesis.', 'Take command of the LHX Attack Chopper. Experience early 3D graphics and complex flight missions in this technical showcase for the 16-bit Sega console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('liberty-or-death-usa', 'Genesis', 'Liberty or Death (USA)', '1993', 'Strategy', 'Koei', '1', 'Grand Strategy', 'Turn-based historical strategy set during the American Revolution.', 'Lead either the American or British forces to victory.', 'Part of Koei''s legendary historical simulation series.', 'Liberty or Death offers deep strategic gameplay set during the American Revolutionary War. Manage resources, politics, and military tactics in this complex Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('light-crusader-europe-enfrdees', 'Genesis', 'Light Crusader (Europe) (En,Fr,De,Es)', '1995', 'Action-Adventure', 'Treasure', '1', 'Isometric', 'Isometric action-adventure with heavy puzzle-solving elements.', 'Explore a massive dungeon to rescue a kidnapped princess.', 'A unique isometric RPG from the creators of Landstalker.', 'Light Crusader combines action, RPG elements, and physics-based puzzles. Explore the depths of the dungeon in this multi-language European release for Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('light-crusader-japan', 'Genesis', 'Light Crusader (Japan)', '1995', 'Action-Adventure', 'Treasure', '1', 'Isometric', 'Isometric action-adventure with heavy puzzle-solving elements.', 'Explore a massive dungeon to rescue a kidnapped princess.', 'The Japanese version of the isometric classic Light Crusader.', 'Light Crusader (Japan) offers a unique blend of Western-style RPG mechanics and Japanese design. Solve intricate puzzles and battle monsters in this isometric adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('light-crusader-korea-enkr', 'Genesis', 'Light Crusader (Korea) (En,Kr)', '1995', 'Action-Adventure', 'Treasure', '1', 'Isometric', 'Isometric action-adventure with heavy puzzle-solving elements.', 'Explore a massive dungeon to rescue a kidnapped princess.', 'The Korean localized version of Light Crusader.', 'Experience the isometric puzzle-solving and combat of Light Crusader. A rare localization that brings Sir David''s adventure to a broader audience on the Sega console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('light-crusader-usa', 'Genesis', 'Light Crusader (USA)', '1995', 'Action-Adventure', 'Treasure', '1', 'Isometric', 'Isometric action-adventure with heavy puzzle-solving elements.', 'Explore a massive dungeon to rescue a kidnapped princess.', 'The North American release of the puzzle-heavy RPG Light Crusader.', 'Light Crusader stands out with its isometric perspective and complex physics puzzles. Embark on a quest to save the kingdom in this deep Sega Genesis adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lightening-force---quest-for-the-darkstar-usa', 'Genesis', 'Lightening Force - Quest for the Darkstar (USA)', '1992', 'Shooter', 'Technosoft', '2', 'Horizontal', 'Horizontal-scrolling shoot ''em up with a unique weapon system.', 'Defeat the alien fleet and destroy the Darkstar.', 'One of the most visually stunning shmups on the Genesis.', 'Lightening Force (Thunder Force IV) is a pinnacle of the shmup genre. Experience blistering speed, massive bosses, and an incredible heavy metal soundtrack on your Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lion-king-3-unl', 'Genesis', 'Lion King 3 (Unl)', '2019', 'Platformer', 'Unlicensed', '1', 'Action', 'Side-scrolling platformer based on the Lion King characters.', 'Navigate through levels to reclaim the Pride Lands.', 'An unlicensed third installment in the Lion King series.', 'Lion King 3 offers a unique, unofficial continuation of Simba''s journey. Explore new levels and face familiar enemies in this rare 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lion-king-ii-the-unl', 'Genesis', 'Lion King II, The (Unl)', '2019', 'Platformer', 'Unlicensed', '1', 'Action', 'Side-scrolling platformer based on the Lion King 2 film.', 'Play through the events of the sequel film as Simba or Kiara.', 'An unlicensed 16-bit adaptation of The Lion King II.', 'Experience the story of the Lion King II in this unofficial Sega title. Run, jump, and roar through the savanna in this fan-made 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lion-king-the-world', 'Genesis', 'Lion King, The (World)', '1994', 'Platformer', 'Westwood Studios', '2', 'Action', 'Side-scrolling action platformer with incredible animation.', 'Grow from a cub to a king and defeat Scar.', 'The official Disney masterpiece for the Sega Genesis.', 'The Lion King brings the magic of the movie to life with hand-drawn animations. Survive the Stampede and reclaim your throne in this challenging and beautiful platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lobo-usa-proto', 'Genesis', 'Lobo (USA) (Proto)', '1996', 'Action', 'Ocean Software', '1', 'Beat ''em Up', '2D fighting game featuring characters from the DC Comics universe.', 'Defeat a series of opponents to prove Lobo is the baddest bounty hunter.', 'An unreleased prototype fighting game starring Lobo.', 'Play the legendary unreleased Lobo game for Sega Genesis. Experience raw 16-bit fighting action as the Main Man himself in this rare DC Comics prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('long-china-unl', 'Genesis', 'Long (China) (Unl)', '1993', 'Action', 'Unlicensed', '2', 'Side-Scrolling', 'Side-scrolling action platformer with traditional Chinese themes.', 'Navigate through mythical stages to defeat ancient enemies.', 'An unlicensed Chinese platformer for the Mega Drive.', 'Long offers a unique look into the world of unlicensed 16-bit gaming. Explore vibrant levels and battle mythical creatures in this rare Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lord-monarch---tokoton-sentou-densetsu-japan', 'Genesis', 'Lord Monarch - Tokoton Sentou Densetsu (Japan)', '1993', 'Strategy', 'SystemSoft', '1', 'Turn-Based', 'Real-time strategy and simulation with a focus on territory control.', 'Expand your kingdom and eliminate rival factions on the map.', 'A spin-off of the popular Dragon Slayer series.', 'Lord Monarch - Tokoton Sentou Densetsu brings fast-paced strategy to the Mega Drive. Manage your units and conquer the land in this deep Japanese strategy classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-vikings-the-europe', 'Genesis', 'Lost Vikings, The (Europe)', '1992', 'Puzzle-Platformer', 'Silicon & Synapse', '2', 'Cooperative', 'Puzzle-platformer requiring the coordination of three different characters.', 'Use the unique skills of each Viking to reach the exit of every level.', 'A clever and humorous puzzle adventure by Blizzard.', 'Guide Erik, Olaf, and Baleog through time in The Lost Vikings. Solve intricate environmental puzzles in this classic Sega Genesis strategy-platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-vikings-the-europe-beta', 'Genesis', 'Lost Vikings, The (Europe) (Beta)', '1992', 'Puzzle-Platformer', 'Silicon & Synapse', '2', 'Cooperative', 'Puzzle-platformer requiring the coordination of three different characters.', 'Use the unique skills of each Viking to reach the exit of every level.', 'A beta version of the classic puzzle game The Lost Vikings.', 'Explore the development of a classic with The Lost Vikings Beta. Experience the core puzzle-solving mechanics and early level designs on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-vikings-the-usa', 'Genesis', 'Lost Vikings, The (USA)', '1992', 'Puzzle-Platformer', 'Silicon & Synapse', '2', 'Cooperative', 'Puzzle-platformer requiring the coordination of three different characters.', 'Use the unique skills of each Viking to reach the exit of every level.', 'The North American release of the hit puzzle game.', 'Master the art of teamwork in The Lost Vikings. Each character is essential to solving the hazards of this beloved 16-bit puzzle-platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lotus-ii-usa-europe', 'Genesis', 'Lotus II (USA, Europe)', '1992', 'Racing', 'Gremlin Interactive', '2', 'Arcade', 'High-speed arcade racing with multiple environments and weather.', 'Finish each race within the time limit to qualify for the next.', 'The sequel to the acclaimed Lotus racing series.', 'Lotus II (Lotus Turbo Challenge 2) delivers incredible 16-bit speed. Race against the clock through rain, snow, and fog in this premier Sega Genesis racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lotus-ii-usa-beta', 'Genesis', 'Lotus II (USA) (Beta)', '1992', 'Racing', 'Gremlin Interactive', '2', 'Arcade', 'High-speed arcade racing with multiple environments and weather.', 'Finish each race within the time limit to qualify for the next.', 'A beta version of the high-speed racer Lotus II.', 'Get a glimpse of the racing masterpiece in development with the Lotus II Beta. High-speed 16-bit action featuring the iconic Lotus sports cars.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lotus-turbo-challenge-usa-europe', 'Genesis', 'Lotus Turbo Challenge (USA, Europe)', '1991', 'Racing', 'Gremlin Interactive', '2', 'Arcade', 'Head-to-head arcade racing with car upgrades and diverse tracks.', 'Outpace opponents to become the ultimate racing champion.', 'The first entry in the iconic Lotus racing trilogy.', 'Experience the thrill of the track in Lotus Turbo Challenge. Featuring split-screen multiplayer and intense arcade physics, it''s a Sega Genesis racing staple.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luigi-in-sonic-1', 'Genesis', 'Luigi in Sonic 1', '1991', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming using Luigi''s physics in the Sonic 1 world.', 'Navigate Sonic''s iconic zones using Luigi''s jump mechanics.', 'A fun rom-hack swapping Sonic for Mario''s brother.', 'What if Luigi was in Green Hill Zone? Experience Luigi in Sonic 1, a creative community modification that brings a Mario twist to the classic Sega engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-94-usa-europe', 'Genesis', 'Madden NFL ''94 (USA, Europe)', '1993', 'Sports', 'Electronic Arts', '2', 'Simulation', 'Professional football simulation with updated rosters and plays.', 'Win the Super Bowl by mastering the gridiron strategy.', 'The first Madden game to feature the official NFL license.', 'Madden NFL ''94 changed the game for sports sims. Experience 16-bit football at its finest with real teams and deep tactical playbooks on Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-95-usa-europe', 'Genesis', 'Madden NFL 95 (USA, Europe)', '1994', 'Sports', 'Electronic Arts', '2', 'Simulation', 'Professional football simulation with high-angle camera views.', 'Lead your favorite NFL team to victory in the playoffs.', 'A refined entry in the legendary football series.', 'Madden NFL 95 brings smoother animations and improved passing mechanics to the Sega Genesis. The gold standard of 16-bit American football gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-96-usa-europe', 'Genesis', 'Madden NFL 96 (USA, Europe)', '1995', 'Sports', 'Electronic Arts', '2', 'Simulation', 'Professional football simulation with create-a-player features.', 'Build a dynasty and win the NFL championship.', 'The first Madden to include custom player creation.', 'Take control of the field in Madden NFL 96. With enhanced AI and new management features, it remains a favorite for retro sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-97-usa-europe', 'Genesis', 'Madden NFL 97 (USA, Europe)', '1996', 'Sports', 'Electronic Arts', '2', 'Simulation', 'Professional football simulation with motion-captured graphics.', 'Execute perfect plays to dominate the NFL season.', 'A visually updated entry in the Madden franchise.', 'Madden NFL 97 pushes the Genesis to its limits with updated visuals and deep gameplay. Experience the peak of 16-bit professional football strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-98-usa', 'Genesis', 'Madden NFL 98 (USA)', '1997', 'Sports', 'Electronic Arts', '2', 'Simulation', 'Professional football simulation with the latest ''98 rosters.', 'Complete the ultimate season and win the championship trophy.', 'The final Madden installment released for the Sega Genesis.', 'Celebrate the end of an era with Madden NFL 98. Featuring the most up-to-date rosters for the console, it’s the definitive 16-bit football experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seganet-kiss-shot-japan', 'Genesis', '[SegaNet] Kiss Shot (Japan)', '1992', 'Sports', 'Sega', '2', 'Arcade', 'Top-down billiards and pool simulation.', 'Clear the table or win specific match formats against opponents.', 'A SegaNet-enabled pool game for the Japanese Mega Drive.', 'Kiss Shot offers precision billiards gameplay. Test your angles and power in this realistic and polished pool simulator for the Japanese Sega system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('007-shitou---the-duel-japan', 'Genesis', '007 Shitou - The Duel (Japan)', '1991', 'Fighting', 'Sega', '2', 'Competitive', 'Side-scrolling action platformer based on the Bond franchise.', 'Infiltrate enemy bases and complete high-stakes missions.', 'The Japanese version of the James Bond game The Duel.', 'Step into the world of espionage in 007 Shitou - The Duel. Battle through dangerous locales as the world''s most famous secret agent on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('16-zhang-majiang-china-unl', 'Genesis', '16 Zhang Majiang (China) (Unl)', '1990', 'Board Game', 'Unlicensed', '4', 'Tabletop', 'Traditional Chinese Mahjong simulation.', 'Use strategy and luck to win tiles and defeat opponents.', 'An unlicensed Mahjong game for the Chinese market.', '16 Zhang Majiang provides a classic tabletop experience on the Sega Genesis. Master the ancient game of Mahjong in this rare unlicensed digital version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2020-toshi-super-baseball-japan', 'Genesis', '2020 Toshi Super Baseball (Japan)', '1991', 'Sports', 'Sega', '2', 'Arcade', 'Futuristic baseball simulation with power-ups and robots.', 'Win games in a high-tech version of the American pastime.', 'An arcade-style sports game set in the near future.', '2020 Toshi Super Baseball reimagines the sport with armor and robots. Experience explosive hits and futuristic catches in this SNK classic ported to Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-ninjas-kick-back-usa', 'Genesis', '3 Ninjas Kick Back (USA)', '1994', 'Action', 'Razorsoft', '1', 'Side-Scrolling', 'Side-scrolling beat ''em up based on the martial arts movie.', 'Fight through various levels to rescue the kidnapped Sensei.', 'A movie tie-in featuring acrobatic martial arts action.', 'Join the three brothers in 3 Ninjas Kick Back. Use unique weapons and ninja skills to defeat enemies in this action-packed Sega Genesis adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('30-day-project-revisited', 'Genesis', '30 Day Project Revisited', '2020', 'Action', 'Homebrew', '1', 'Experimental', 'Homebrew or independent development project.', 'Complete the various tasks or stages defined by the project.', 'A modern community project for the Sega Genesis.', '30 Day Project Revisited showcases the creativity of the homebrew scene. Experience unique mechanics and indie design on classic 16-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('6-pak-usa', 'Genesis', '6-Pak (USA)', '1996', 'Compilation', 'Sega', '2', 'Arcade', 'A collection of six classic Sega Genesis titles on one cartridge.', 'Enjoy a variety of genres including platforming and fighting.', 'The ultimate Sega Genesis compilation cartridge.', '6-Pak is the perfect starter for any collection. Featuring Sonic 1, Golden Axe, Streets of Rage, and more, it offers the best of 16-bit gaming in one place.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('688-attack-sub-usa-europe', 'Genesis', '688 Attack Sub (USA, Europe)', '1990', 'Simulation', 'Sonobuoy', '1', 'Naval Combat', 'Submarine combat simulation with tactical depth.', 'Navigate the depths and complete covert naval missions.', 'A sophisticated naval strategy sim for the Genesis.', 'Dive into the deep with 688 Attack Sub. Manage your crew and sonar to win the silent war in this realistic submarine combat simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('a-bugs-life-unl', 'Genesis', 'A Bug''s Life (Unl)', '1999', 'Platformer', 'Unlicensed', '1', 'Action', 'Side-scrolling platformer based on the Pixar film.', 'Navigate the ant colony and defeat the grasshopper gang.', 'An unlicensed 16-bit adaptation of A Bug''s Life.', 'Experience the world of Flik in this unofficial Sega title. A rare and interesting interpretation of the classic animated film on 16-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('a-ressha-de-ikou-md-japan', 'Genesis', 'A Ressha de Ikou MD (Japan)', '1992', 'Simulation', 'ArtDink', '1', 'Management', 'Train and city management simulation.', 'Build a successful railway network and develop the surrounding city.', 'Part of the legendary A-Train management series.', 'A Ressha de Ikou MD (A-Train) offers deep economic strategy. Design tracks and manage logistics to build a thriving metropolis on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aa-harimanada-japan', 'Genesis', 'Aa Harimanada (Japan)', '1993', 'Sports', 'Sega', '2', 'Arcade', '1-on-1 sumo wrestling simulation and combat.', 'Defeat rival sumo wrestlers through strength and technique.', 'Based on the popular sumo-themed manga and anime.', 'Experience the power of the dohyo in Aa Harimanada. Master the art of sumo wrestling with unique characters and intense 16-bit grappling action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aaahh!!!-real-monsters-usa-europe', 'Genesis', 'AAAHH!!! Real Monsters (USA, Europe)', '1995', 'Platformer', 'Realtime Associates', '2', 'Action', 'Side-scrolling platformer with a focus on "scaring" mechanics.', 'Collect trash and scare humans to progress through levels.', 'Based on the popular Nickelodeon animated series.', 'Join Ickis, Krumm, and Oblina in AAAHH!!! Real Monsters. Use their unique abilities to pass your scaring exams in this atmospheric 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('action-52-usa-alt-unl', 'Genesis', 'Action 52 (USA) (Alt) (Unl)', '1991', 'Compilation', 'Active Enterprises', '2', 'Mini-Games', 'A massive collection of 52 low-budget indie/unlicensed games.', 'Explore a wide variety of experimental and short games.', 'The infamous multi-game compilation for Sega Genesis.', 'Action 52 is a legendary piece of gaming history. Explore 52 unique (and often bizarre) games on a single cartridge in this unlicensed Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('action-52-usa-unl', 'Genesis', 'Action 52 (USA) (Unl)', '1991', 'Compilation', 'Active Enterprises', '2', 'Mini-Games', 'A massive collection of 52 low-budget indie/unlicensed games.', 'Explore a wide variety of experimental and short games.', 'The infamous multi-game compilation for Sega Genesis.', 'Action 52 is a legendary piece of gaming history. Explore 52 unique (and often bizarre) games on a single cartridge in this unlicensed Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('addams-family-values-europe-enfrde', 'Genesis', 'Addams Family Values (Europe) (En,Fr,De)', '1994', 'Action', 'Ocean Software', '1', 'Platformer', 'Isometric action-adventure with a focus on exploration.', 'Navigate the Addams estate to find and rescue family members.', 'A creepy and kooky adventure based on the 1993 film.', 'Addams Family Values brings dark humor and puzzle-solving to the Genesis. Explore huge environments and interact with the famous family in this isometric RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('addams-family-the-usa-europe', 'Genesis', 'Addams Family, The (USA, Europe)', '1992', 'Platformer', 'Ocean Software', '1', 'Action', 'Side-scrolling platformer featuring the Addams Family.', 'Rescue the Addams family members from a haunted mansion.', 'A classic platformer starring Gomez Addams.', 'Explore a mansion filled with secrets in The Addams Family. Use Gomez''s skills to navigate dangerous levels in this charmingly gothic 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('addams-family-the-usa-beta', 'Genesis', 'Addams Family, The (USA) (Beta)', '1992', 'Platformer', 'Ocean Software', '1', 'Action', 'Side-scrolling platformer featuring the Addams Family.', 'Rescue the Addams family members from a haunted mansion.', 'A beta version of the Addams Family platformer.', 'See the early stages of the kooky mansion with The Addams Family Beta. A fascinating look at the development of this classic Sega Genesis title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advanced-busterhawk-gleylancer-japan', 'Genesis', 'Advanced Busterhawk Gleylancer (Japan)', '1992', 'Shooter', 'NCS', '1', 'Horizontal', 'Horizontal-scrolling shooter with a versatile satellite aiming system.', 'Pilot the Gleylancer fighter to rescue your father from aliens.', 'A premium 16-bit space shooter with cinematic cutscenes.', 'Advanced Busterhawk Gleylancer is a masterpiece of the shmup genre. Master the "Mover" system to aim your fire in any direction and enjoy high-quality anime storytelling on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advanced-busterhawk-gleylancer-japan-en-by-mijet-v20061023', 'Genesis', 'Advanced Busterhawk Gleylancer (Japan) [En by MIJET v20061023]', '1992', 'Shooter', 'NCS', '1', 'Horizontal', 'Horizontal-scrolling shooter with a versatile satellite aiming system.', 'Pilot the Gleylancer fighter to rescue your father from aliens.', 'The fan-translated English version of the elite shmup.', 'Play the legendary Gleylancer in English! Experience one of the most sought-after Sega Mega Drive shooters with fully translated dialogue and intense, customizable space combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advanced-daisenryaku---deutsch-dengeki-sakusen-japan-rev-a', 'Genesis', 'Advanced Daisenryaku - Deutsch Dengeki Sakusen (Japan) (Rev A)', '1991', 'Strategy', 'SystemSoft', '1', 'Turn-Based', 'Hex-based tactical war simulation set during World War II.', 'Command German forces through historical campaigns to conquer Europe.', 'A deep and complex military strategy simulation.', 'Advanced Daisenryaku offers unparalleled tactical depth. Manage hundreds of authentic units and weather conditions in this massive WWII strategy epic for the Sega Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advanced-daisenryaku---deutsch-dengeki-sakusen-japan-rev-a-en-by-nebelwurfer-v095-~advanced-military-commander-incomplete', 'Genesis', 'Advanced Daisenryaku - Deutsch Dengeki Sakusen (Japan) (Rev A) [En by Nebelwurfer v0.95] (~Advanced Military Commander) (Incomplete)', '1991', 'Strategy', 'SystemSoft', '1', 'Turn-Based', 'Hex-based tactical war simulation set during World War II.', 'Command German forces through historical campaigns to conquer Europe.', 'English translation of the deep WWII strategy sim.', 'Command your way to victory with the English version of Advanced Daisenryaku. Engage in massive, turn-based military campaigns featuring historically accurate units and deep tactics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-batman-&-robin-the-europe', 'Genesis', 'Adventures of Batman & Robin, The (Europe)', '1994', 'Action', 'Clockwork Tortoise', '1', 'Run and Gun', 'Run-and-gun action with high-intensity boss battles.', 'Stop Mr. Freeze and other villains from destroying Gotham City.', 'A visually stunning action game based on the animated series.', 'The Adventures of Batman & Robin is a technical marvel on the Genesis. Face relentless waves of enemies and incredible boss fights in this challenging 16-bit action classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-batman-&-robin-the-usa', 'Genesis', 'Adventures of Batman & Robin, The (USA)', '1994', 'Action', 'Clockwork Tortoise', '1', 'Run and Gun', 'Run-and-gun action with high-intensity boss battles.', 'Stop Mr. Freeze and other villains from destroying Gotham City.', 'The North American version of the Batman animated hit.', 'Battle through Gotham in The Adventures of Batman & Robin. Featuring some of the best graphics on the Sega Genesis, this run-and-gun adventure is a must-play for DC fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-mighty-max-the-europe', 'Genesis', 'Adventures of Mighty Max, The (Europe)', '1993', 'Action', 'WJS Design', '1', 'Platformer', 'Isometric action-adventure with combat and puzzle-solving.', 'Navigate through dangerous portals to defeat the Skull Master.', 'An action game based on the popular 90s toy line.', 'Join Mighty Max on a quest through strange dimensions. Explore trap-filled levels and defeat iconic villains in this unique 16-bit isometric adventure for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-mighty-max-the-usa', 'Genesis', 'Adventures of Mighty Max, The (USA)', '1993', 'Action', 'WJS Design', '1', 'Platformer', 'Isometric action-adventure with combat and puzzle-solving.', 'Navigate through dangerous portals to defeat the Skull Master.', 'The North American release of Mighty Max''s adventure.', 'Join Mighty Max on a quest through strange dimensions. Explore trap-filled levels and defeat iconic villains in this unique 16-bit isometric adventure for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-rocky-and-bullwinkle-and-friends-the-usa', 'Genesis', 'Adventures of Rocky and Bullwinkle and Friends, The (USA)', '1993', 'Action', 'Radical Entertainment', '1', 'Platformer', 'Variety-based platformer featuring multiple mini-games.', 'Stop Boris and Natasha from stealing the world''s art treasures.', 'A cartoon-based adventure featuring the famous duo.', 'The Adventures of Rocky and Bullwinkle and Friends brings the classic cartoon to your Genesis. Enjoy a mix of platforming and mini-games starring the beloved moose and squirrel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-blasters-japan', 'Genesis', 'Aero Blasters (Japan)', '1990', 'Shooter', 'Kaneko', '2', 'Horizontal', 'Fast-paced horizontal shoot ''em up with environmental hazards.', 'Fly through urban and alien landscapes to destroy enemy forces.', 'The Japanese version of the cult classic Air Buster.', 'Aero Blasters is a high-speed shmup that tests your reflexes. Blast through tight corridors and massive bosses in this colorful and intense Sega Mega Drive shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-the-acro-bat-europe', 'Genesis', 'Aero the Acro-Bat (Europe)', '1993', 'Platformer', 'Iguana Entertainment', '1', 'Action', 'Side-scrolling platformer featuring acrobatic movement.', 'Stop the evil industrialist Edgar Ektor from destroying the circus.', 'A circus-themed platformer with a unique protagonist.', 'Fly through the air in Aero the Acro-Bat. Use jumps, dives, and circus skills to navigate dangerous levels in this vibrant and charming 16-bit platforming hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-the-acro-bat-usa', 'Genesis', 'Aero the Acro-Bat (USA)', '1993', 'Platformer', 'Iguana Entertainment', '1', 'Action', 'Side-scrolling platformer featuring acrobatic movement.', 'Stop the evil industrialist Edgar Ektor from destroying the circus.', 'The North American debut of the bat with attitude.', 'Fly through the air in Aero the Acro-Bat. Use jumps, dives, and circus skills to navigate dangerous levels in this vibrant and charming 16-bit platforming hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-the-acro-bat-2-europe', 'Genesis', 'Aero the Acro-Bat 2 (Europe)', '1994', 'Platformer', 'Iguana Entertainment', '1', 'Action', 'Refined platforming with new moves like the bell-swing.', 'Follow the trail of Edgar Ektor to stop his new evil plan.', 'The polished sequel to the original circus adventure.', 'Aero the Acro-Bat 2 brings smoother controls and better level design to the Genesis. Explore larger worlds and master new acrobatic tricks in this top-tier 16-bit sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-the-acro-bat-2-usa', 'Genesis', 'Aero the Acro-Bat 2 (USA)', '1994', 'Platformer', 'Iguana Entertainment', '1', 'Action', 'Refined platforming with new moves like the bell-swing.', 'Follow the trail of Edgar Ektor to stop his new evil plan.', 'The North American version of the acclaimed sequel.', 'Aero the Acro-Bat 2 brings smoother controls and better level design to the Genesis. Explore larger worlds and master new acrobatic tricks in this top-tier 16-bit sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aerobiz-usa', 'Genesis', 'Aerobiz (USA)', '1992', 'Strategy', 'Koei', '1', 'Business Simulation', 'Airline management simulation and business strategy.', 'Build a global airline empire and beat three rival companies.', 'A deep business sim from the masters at Koei.', 'Experience the challenge of the aviation industry in Aerobiz. Manage routes, buy planes, and navigate global events to become the world''s leading airline on your Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aerobiz-supersonic-usa', 'Genesis', 'Aerobiz Supersonic (USA)', '1993', 'Strategy', 'Koei', '1', 'Business Simulation', 'Expanded airline management with more eras and planes.', 'Dominate the skies across different historical time periods.', 'The deeper, faster sequel to the original Aerobiz.', 'Aerobiz Supersonic takes airline management to the next level. Spanning from the dawn of jets to the future, it’s the ultimate 16-bit strategy game for aspiring tycoons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('after-burner-ii-japan', 'Genesis', 'After Burner II (Japan)', '1988', 'Shooter', 'Sega', '1', 'Arcade', '3D-style rail shooter with fast-paced dogfighting.', 'Pilot an F-14 Tomcat and destroy waves of enemy jets.', 'The classic Sega arcade hit ported to the Mega Drive.', 'Get ready to enter the Danger Zone with After Burner II. Experience blistering speed and intense dogfights in this definitive home port of the arcade legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('after-burner-ii-usa-europe', 'Genesis', 'After Burner II (USA, Europe)', '1988', 'Shooter', 'Sega', '1', 'Arcade', '3D-style rail shooter with fast-paced dogfighting.', 'Pilot an F-14 Tomcat and destroy waves of enemy jets.', 'The worldwide release of the legendary flight shooter.', 'Get ready to enter the Danger Zone with After Burner II. Experience blistering speed and intense dogfights in this definitive home port of the arcade legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-buster-usa', 'Genesis', 'Air Buster (USA)', '1990', 'Shooter', 'Kaneko', '2', 'Vertical', 'Horizontal-scrolling shooter with various power-ups.', 'Neutralize a rogue satellite and its robotic army.', 'The North American version of Aero Blasters.', 'Air Buster (Air Diver) delivers pure arcade shooting action. Navigate high-speed scrolling levels and engage in massive boss fights in this underrated Sega Genesis shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-diver-japan', 'Genesis', 'Air Diver (Japan)', '1990', 'Shooter', 'Asmik', '1', 'Arcade', 'First-person flight combat simulator.', 'Engage in dogfights with enemy aircraft to protect the airspace.', 'A cockpit-view flight action game for the Mega Drive.', 'Experience the view from the cockpit in Air Diver. Hunt down enemy jets using your radar and missiles in this early 16-bit 3D flight simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-diver-usa', 'Genesis', 'Air Diver (USA)', '1990', 'Shooter', 'Asmik', '1', 'Arcade', 'First-person flight combat simulator.', 'Engage in dogfights with enemy aircraft to protect the airspace.', 'The North American release of the cockpit flight sim.', 'Experience the view from the cockpit in Air Diver. Hunt down enemy jets using your radar and missiles in this early 16-bit 3D flight simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-management---oozora-ni-kakeru-japan', 'Genesis', 'Air Management - Oozora ni Kakeru (Japan)', '1991', 'Simulation', 'Koei', '1', 'Management', 'Airline business simulation with global strategy.', 'Expand your airline network and achieve top market share.', 'The original Japanese release of the Aerobiz series.', 'Air Management (Aerobiz) combines deep strategy with economic simulation. Plan your global expansion and manage your fleet to win the airline wars on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-management-ii---koukuuou-o-mezase-japan', 'Genesis', 'Air Management II - Koukuuou o Mezase (Japan)', '1993', 'Simulation', 'Koei', '1', 'Management', 'Advanced airline business simulation with more options.', 'Outmaneuver rivals and monopolize the international skies.', 'The Japanese sequel known as Aerobiz Supersonic.', 'Air Management II offers more planes, more cities, and more strategy. Build a lasting aviation legacy in this comprehensive 16-bit business simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akira-prototype', 'Genesis', 'Akira (Prototype)', '1994', 'Action', 'SEGA AM2', '1', 'Beat ''em Up', 'Side-scrolling action adventure with cinematic elements.', 'Navigate Neo-Tokyo as Kaneda to find and save Akira.', 'An unreleased prototype based on the legendary anime.', 'Explore a piece of history with the Akira Prototype. Though unfinished, it offers a fascinating look at how this iconic movie was being adapted for the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akumajou-dracula---vampire-killer-japan', 'Genesis', 'Akumajou Dracula - Vampire Killer (Japan)', '1989', 'Action', 'Konami', '1', 'Platformer', 'Side-scrolling action-platformer with whip-based combat.', 'Travel across Europe to stop the resurrection of Dracula.', 'The iconic Castlevania entry for the Sega Mega Drive.', 'Akumajou Dracula - Vampire Killer (Castlevania: Bloodlines) is a dark masterpiece. Experience intense gothic action and incredible 16-bit visuals in this legendary Konami title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aladdin-europe', 'Genesis', 'Aladdin (Europe)', '1993', 'Platformer', 'Virgin Interactive', '1', 'Action', 'Side-scrolling platformer with fluid, hand-drawn animation.', 'Defeat Jafar and win the heart of Princess Jasmine.', 'Disney’s classic movie adaptation for the Genesis.', 'Experience the magic of Disney''s Aladdin. Featuring animation by Disney''s own artists, this platformer is a technical and artistic triumph on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aladdin-japan', 'Genesis', 'Aladdin (Japan)', '1993', 'Platformer', 'Virgin Interactive', '1', 'Action', 'Side-scrolling platformer with fluid, hand-drawn animation.', 'Defeat Jafar and win the heart of Princess Jasmine.', 'The Japanese release of the iconic Aladdin game.', 'Experience the magic of Disney''s Aladdin. Featuring animation by Disney''s own artists, this platformer is a technical and artistic triumph on the Sega Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aladdin-usa', 'Genesis', 'Aladdin (USA)', '1993', 'Platformer', 'Virgin Interactive', '1', 'Action', 'Side-scrolling platformer with fluid, hand-drawn animation.', 'Defeat Jafar and win the heart of Princess Jasmine.', 'The North American version of the Disney classic.', 'Experience the magic of Disney''s Aladdin. Featuring animation by Disney''s own artists, this platformer is a technical and artistic triumph on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aladdin-usa-beta', 'Genesis', 'Aladdin (USA) (Beta)', '1993', 'Platformer', 'Virgin Interactive', '1', 'Action', 'Side-scrolling platformer with fluid, hand-drawn animation.', 'Defeat Jafar and win the heart of Princess Jasmine.', 'A beta version of the Disney classic Aladdin.', 'Take a look behind the scenes with the Aladdin Beta. See early level layouts and animations for one of the most famous games on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aladdin-ii', 'Genesis', 'Aladdin II', '1995', 'Platformer', 'Unlicensed', '1', 'Action', 'Side-scrolling platformer inspired by the movie sequel.', 'Follow Aladdin on a new adventure to protect Agrabah.', 'An unlicensed sequel/hack based on the Disney series.', 'Aladdin II offers a unique, unofficial continuation of the story. Explore new environments and face new challenges in this rare 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-kidd---cheongong-maseong-korea', 'Genesis', 'Alex Kidd - Cheongong Maseong (Korea)', '1989', 'Platformer', 'Sega', '1', 'Action', 'Side-scrolling platforming with "Rock-Paper-Scissors" boss battles.', 'Find Alex''s father, King Thor, on the planet Paperock.', 'The Korean version of the classic Alex Kidd adventure.', 'Experience Alex Kidd - Cheongong Maseong on the Sega Genesis. Navigate challenging levels and win Janken matches to save the royal family in this iconic 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-kidd---tenkuu-majou-japan', 'Genesis', 'Alex Kidd - Tenkuu Majou (Japan)', '1989', 'Platformer', 'Sega', '1', 'Action', 'Side-scrolling platforming with "Rock-Paper-Scissors" boss battles.', 'Find Alex''s father, King Thor, on the planet Paperock.', 'The original Japanese release of the first Genesis Alex Kidd.', 'Alex Kidd - Tenkuu Majou brings the beloved mascot to the 16-bit era. Master the art of Paper-Rock-Scissors and explore the Enchanted Castle in this Mega Drive classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-kidd-in-the-enchanted-castle-europe', 'Genesis', 'Alex Kidd in the Enchanted Castle (Europe)', '1989', 'Platformer', 'Sega', '1', 'Action', 'Side-scrolling platforming with "Rock-Paper-Scissors" boss battles.', 'Find Alex''s father, King Thor, on the planet Paperock.', 'The European release of Alex Kidd''s 16-bit debut.', 'Alex Kidd in the Enchanted Castle features classic Sega platforming. Explore vibrant worlds, collect vehicles, and defeat bosses in this charming 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-kidd-in-the-enchanted-castle-europe-alt', 'Genesis', 'Alex Kidd in the Enchanted Castle (Europe) (Alt)', '1989', 'Platformer', 'Sega', '1', 'Action', 'Side-scrolling platforming with "Rock-Paper-Scissors" boss battles.', 'Find Alex''s father, King Thor, on the planet Paperock.', 'An alternate European version of the Alex Kidd classic.', 'Alex Kidd in the Enchanted Castle features classic Sega platforming. Explore vibrant worlds, collect vehicles, and defeat bosses in this charming 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-kidd-in-the-enchanted-castle-usa', 'Genesis', 'Alex Kidd in the Enchanted Castle (USA)', '1989', 'Platformer', 'Sega', '1', 'Action', 'Side-scrolling platforming with "Rock-Paper-Scissors" boss battles.', 'Find Alex''s father, King Thor, on the planet Paperock.', 'The North American edition of Alex Kidd''s 16-bit quest.', 'Alex Kidd in the Enchanted Castle features classic Sega platforming. Explore vibrant worlds, collect vehicles, and defeat bosses in this charming 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-3-usa-europe', 'Genesis', 'Alien 3 (USA, Europe)', '1992', 'Action', 'Probe Software', '1', 'Platformer', 'Exploration-based action with a heavy focus on time limits.', 'Rescue trapped prisoners and destroy the Alien nest.', 'An intense action game based on the sci-fi movie Alien 3.', 'Survive the terror in Alien 3 for Sega Genesis. Use pulse rifles and motion trackers to hunt Xenomorphs in a race against time across a desolate prison colony.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-3-usa-europe-v11', 'Genesis', 'Alien 3 (USA, Europe) (v1.1)', '1992', 'Action', 'Probe Software', '1', 'Platformer', 'Exploration-based action with a heavy focus on time limits.', 'Rescue trapped prisoners and destroy the Alien nest.', 'Refined version (v1.1) of the cinematic action game Alien 3.', 'Survive the terror in Alien 3 for Sega Genesis. Use pulse rifles and motion trackers to hunt Xenomorphs in a race against time across a desolate prison colony.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-soldier-europe', 'Genesis', 'Alien Soldier (Europe)', '1995', 'Shooter', 'Treasure', '1', 'Run and Gun', 'Boss-rush focused run-and-gun with high-speed movement mechanics.', 'Defeat 25 massive bosses to stop a terrorist alien group.', 'A legendary and hyper-fast action game by Treasure.', 'Alien Soldier is a technical masterpiece on the Sega Genesis. Experience relentless boss battles and fluid 16-bit action in one of the most intense shooters ever made.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-soldier-japan', 'Genesis', 'Alien Soldier (Japan)', '1995', 'Shooter', 'Treasure', '1', 'Run and Gun', 'Boss-rush focused run-and-gun with high-speed movement mechanics.', 'Defeat 25 massive bosses to stop a terrorist alien group.', 'The Japanese release of Treasure''s cult classic Alien Soldier.', 'Alien Soldier is a technical masterpiece on the Mega Drive. Experience relentless boss battles and fluid 16-bit action in one of the most intense shooters ever made.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-storm-world', 'Genesis', 'Alien Storm (World)', '1990', 'Action', 'Sims', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up and shooter with sci-fi themes.', 'Protect Earth from a shape-shifting alien invasion.', 'A classic Sega arcade port featuring three playable heroes.', 'Fight back the invaders in Alien Storm. Choose between a human, a woman, or a robot to save the planet in this high-energy 16-bit arcade brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alisia-dragoon-europe', 'Genesis', 'Alisia Dragoon (Europe)', '1992', 'Action', 'Game Arts', '1', 'Action Platformer', 'Side-scrolling action with auto-targeting magic and dragon familiars.', 'Defeat the awakening god of destruction, Baldour.', 'A unique action-platformer featuring a powerful sorceress.', 'Alisia Dragoon is a visual and mechanical gem on the Genesis. Command four different dragons and unleash lightning magic in this highly acclaimed 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alisia-dragoon-japan', 'Genesis', 'Alisia Dragoon (Japan)', '1992', 'Action', 'Game Arts', '1', 'Action Platformer', 'Side-scrolling action with auto-targeting magic and dragon familiars.', 'Defeat the awakening god of destruction, Baldour.', 'The Japanese version of the cult classic Alisia Dragoon.', 'Alisia Dragoon is a visual and mechanical gem on the Mega Drive. Command four different dragons and unleash lightning magic in this highly acclaimed 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alisia-dragoon-usa', 'Genesis', 'Alisia Dragoon (USA)', '1992', 'Action', 'Game Arts', '1', 'Action Platformer', 'Side-scrolling action with auto-targeting magic and dragon familiars.', 'Defeat the awakening god of destruction, Baldour.', 'The North American release of the sorceress action classic.', 'Alisia Dragoon is a visual and mechanical gem on the Genesis. Command four different dragons and unleash lightning magic in this highly acclaimed 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('altered-beast---alternate-style', 'Genesis', 'Altered Beast - Alternate Style', '1989', 'Action', 'Sega', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with transformation mechanics and modded palettes.', 'Battle through the underworld to save Zeus''s daughter.', 'A modified version of the classic Altered Beast.', 'Rise from your grave in Altered Beast - Alternate Style. Experience the iconic transformation gameplay with a fresh visual twist on the 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('altered-beast-usa-europe', 'Genesis', 'Altered Beast (USA, Europe)', '1989', 'Action', 'Sega', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up where the player transforms into beasts.', 'Battle through the underworld to save Zeus''s daughter Athena.', 'The iconic launch title for the Sega Genesis.', 'Altered Beast is the ultimate 16-bit arcade port. Power up, transform into legendary creatures, and defeat the dark lord Neff in this quintessential Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('altered-beast-with-arcade-voice-samples', 'Genesis', 'Altered Beast with Arcade Voice Samples', '1989', 'Action', 'Sega', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring enhanced sound files.', 'Battle through the underworld to save Zeus''s daughter.', 'A version of Altered Beast with improved arcade-quality audio.', 'Experience Altered Beast like never before with Arcade Voice Samples. Hear the iconic "Power Up!" and "Rise From Your Grave!" in crystal clear quality on your Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-gladiators-usa', 'Genesis', 'American Gladiators (USA)', '1992', 'Sports', 'Grey Matter', '2', 'Arcade', 'Variety action featuring mini-games based on the TV show.', 'Win various physical challenges to become the Grand Champion.', 'An athletic competition game based on the hit 90s show.', 'Test your strength and agility in American Gladiators. Compete in the Joust, Assault, and the Eliminator in this fun 16-bit sports challenge for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ameythist-sonic-2-v1-shc2024-project', 'Genesis', 'Ameythist Sonic 2 V1 (SHC2024 Project)', '2024', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with a custom "Ameythist" aesthetic.', 'Complete Sonic 2 levels with new visuals and physics.', 'A modern community project modifying Sonic the Hedgehog 2.', 'Explore a new side of a classic with Ameythist Sonic 2. This SHC2024 project brings fresh colors and gameplay tweaks to the legendary 16-bit engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('among-the-others', 'Genesis', 'Among the Others', '2023', 'Action', 'Homebrew', '1', 'Experimental', 'Experimental horror/puzzle platforming.', 'Navigate through eerie environments and uncover the mystery.', 'A modern homebrew title with a dark atmosphere.', 'Among the Others brings a unique, moody experience to the Sega Genesis. Solve puzzles and survive a haunting world in this impressive indie 16-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('amy-rose-in-sonic-the-hedgehog', 'Genesis', 'Amy Rose in Sonic the Hedgehog', '2021', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming featuring Amy Rose''s hammer mechanics.', 'Navigate Sonic''s world as Amy to defeat Dr. Eggman.', 'A popular rom-hack putting Amy Rose in the first Sonic game.', 'Play as Amy Rose in Sonic the Hedgehog. Use her Piko Piko Hammer to smash enemies and explore classic stages in this creative character swap for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('amy-rose-in-sonic-the-hedgehog-2', 'Genesis', 'Amy Rose in Sonic the Hedgehog 2', '2021', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming featuring Amy Rose''s hammer mechanics.', 'Navigate Sonic 2''s world as Amy to defeat Dr. Eggman.', 'Amy Rose joins the adventure in Sonic the Hedgehog 2.', 'Take Amy Rose through the high-speed loops of Sonic 2. This mod adds a fresh layer of strategy and charm to the legendary 16-bit sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('amy-roses-island-adventure', 'Genesis', 'Amy Rose''s Island Adventure', '2022', 'Platformer', 'Fan Hack', '1', 'Adventure', 'Exploration platformer starring Amy Rose.', 'Explore a mysterious island and complete challenges.', 'A fan-made adventure starring everyone''s favorite pink hedgehog.', 'Join Amy on a unique journey in Amy Rose''s Island Adventure. Discover secrets and use her unique abilities in this custom-built 16-bit experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('an-apeeling-sonic-hack', 'Genesis', 'An Apeeling Sonic Hack', '2020', 'Platformer', 'Fan Hack', '1', 'Action', 'Physics-based platforming with a humorous "banana" twist.', 'Navigate levels with modified gravity and movements.', 'A quirky and funny modification of the Sonic engine.', 'An Apeeling Sonic Hack brings a sense of humor to retro gaming. Navigate classic stages with unexpected physics in this entertaining community project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('an-ordinary-sonic', 'Genesis', 'An Ordinary Sonic', '2020', 'Platformer', 'Fan Hack', '1', 'Action', 'Subversive platforming with "creepypasta" and horror elements.', 'Progress through the game while the environment changes glitchily.', 'A modern horror-themed modification of Sonic the Hedgehog.', 'Don''t let the name fool you; An Ordinary Sonic is anything but ordinary. Experience a chilling, reality-bending take on the 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('andre-agassi-tennis-europe-v11', 'Genesis', 'Andre Agassi Tennis (Europe) (v1.1)', '1992', 'Sports', 'Taito', '2', 'Tennis Simulation', 'Sports simulation focusing on precision and timing.', 'Win major tournaments to become the top-ranked tennis pro.', 'A realistic tennis game endorsed by Andre Agassi (v1.1).', 'Take to the court in Andre Agassi Tennis. Featuring realistic physics and multiple surfaces, it''s one of the most polished sports titles on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('andre-agassi-tennis-usa', 'Genesis', 'Andre Agassi Tennis (USA)', '1992', 'Sports', 'Taito', '2', 'Tennis Simulation', 'Sports simulation focusing on precision and timing.', 'Win major tournaments to become the top-ranked tennis pro.', 'The North American release of Andre Agassi Tennis.', 'Take to the court in Andre Agassi Tennis. Featuring realistic physics and multiple surfaces, it''s one of the most polished sports titles on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('andre-agassi-tennis-usa-beta', 'Genesis', 'Andre Agassi Tennis (USA) (Beta)', '1992', 'Sports', 'Taito', '2', 'Tennis Simulation', 'Sports simulation focusing on precision and timing.', 'Win major tournaments to become the top-ranked tennis pro.', 'A pre-release beta of the Andre Agassi tennis game.', 'Test the early mechanics of 16-bit pro tennis with the Andre Agassi Beta. A great look at the development of this classic Sega sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('andrew-in-sonic-the-hedgehog-2', 'Genesis', 'Andrew in Sonic the Hedgehog 2', '2021', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with a custom character swap.', 'Navigate Sonic 2''s zones as a custom character named Andrew.', 'A personalized rom-hack of Sonic the Hedgehog 2.', 'Andrew in Sonic the Hedgehog 2 offers a unique way to play the classic sequel. See how this custom character handles the high speeds of 16-bit gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('angry-birds-unl', 'Genesis', 'Angry Birds (Unl)', '2018', 'Platformer', 'Unlicensed', '1', 'Action', 'Physics-based puzzle-catapult action.', 'Launch birds to destroy the pigs'' structures.', 'An unlicensed 16-bit port of the mobile phenomenon.', 'Angry Birds comes to the Sega Genesis! Experience the addictive bird-slinging action on classic hardware in this impressive unlicensed 16-bit port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animaniacs-europe-enfrde', 'Genesis', 'Animaniacs (Europe) (En,Fr,De)', '1994', 'Platformer', 'Konami', '2', 'Action', 'Multi-character platforming with puzzle elements and humor.', 'Complete various zany tasks in different movie-themed levels.', 'Based on the hit Warner Bros. animated series.', 'Join Yakko, Wakko, and Dot in Animaniacs. Use the trio''s teamwork to solve puzzles and cause chaos across the Warner Bros. lot in this fun Sega title.');
