INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('another-shadow-in-sonic-1-ultra-ego-edition', 'Genesis', 'Another Shadow in Sonic 1 Ultra Ego Edition', '2023', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with custom abilities and transformed states.', 'Conquer Sonic 1 stages using Shadow''s Ultra Ego powers.', 'A powerful character mod for the original Sonic 1.', 'Experience ultimate power in Another Shadow in Sonic 1 Ultra Ego Edition. Use Shadow''s unique physics and devastating new abilities to blitz through retro 16-bit stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('another-world-europe', 'Genesis', 'Another World (Europe)', '1991', 'Action-Adventure', 'Delphine Software', '1', 'Cinematic', 'Cinematic action-adventure with platforming and puzzle-solving.', 'Survive a hostile alien world and find a way back home.', 'The revolutionary cinematic classic (Out of This World).', 'Another World is a masterpiece of atmosphere and storytelling. Help Lester survive a mysterious planet in this visually stunning and challenging 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aoki-ookami-to-shiroki-meshika---genchou-hishi-japan', 'Genesis', 'Aoki Ookami to Shiroki Meshika - Genchou Hishi (Japan)', '1993', 'Strategy', 'Koei', '1', 'Grand Strategy', 'Hex-based historical strategy and conquest simulation.', 'Conquer the known world as Genghis Khan or other leaders.', 'A deep historical strategy game from Koei.', 'Aoki Ookami to Shiroki Meshika (Genghis Khan II) offers complex strategy on the Mega Drive. Manage military, diplomacy, and family legacy in this massive conquest sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aq-renkan-awa-china-unl', 'Genesis', 'Aq Renkan Awa (China) (Unl)', '1994', 'Action', 'Unlicensed', '2', 'Arcade', 'Tile-matching puzzle action with a Chinese aesthetic.', 'Match symbols and clear the board to progress.', 'An unlicensed Chinese puzzle game for the Mega Drive.', 'Aq Renkan Awa brings classic tile-matching strategy to the 16-bit era. Challenge your logic and speed in this rare unlicensed Sega puzzle title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aquatic-games-starring-james-pond-and-the-aquabats-the-usa-europe', 'Genesis', 'Aquatic Games Starring James Pond and the Aquabats, The (USA, Europe)', '1992', 'Sports', 'Vectordean', '4', 'Party', 'Olympic-style sports mini-games with a submarine twist.', 'Win gold medals in various aquatic athletic events.', 'A fun sports spin-off starring James Pond.', 'Join the Aquabats in The Aquatic Games. Compete in wacky 16-bit events like the Hop, Skip and Jump or the Shell Dash in this charming James Pond sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcade-classics-usa-europe', 'Genesis', 'Arcade Classics (USA, Europe)', '1996', 'Compilation', 'Sega', '2', 'Arcade', 'A compilation of classic Atari arcade hits.', 'Achieve high scores in Missile Command, Centipede, and Ultrapede.', 'Three legendary Atari arcade ports on one cartridge.', 'Arcade Classics brings the golden age of gaming to your Sega Genesis. Enjoy faithful 16-bit recreations of Atari''s most addictive arcade masterpieces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arch-rivals---the-arcade-game-usa-europe', 'Genesis', 'Arch Rivals - The Arcade Game (USA, Europe)', '1989', 'Sports', 'Midway', '2', 'Arcade', 'Two-on-two street basketball with "no-rules" physical play.', 'Outscore the opponent by any means, including punching.', 'An aggressive and fun arcade basketball port.', 'Arch Rivals is the original combat basketball game. Punch your way to the hoop and experience high-energy, no-holds-barred 16-bit sports action for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcus-odyssey-japan', 'Genesis', 'Arcus Odyssey (Japan)', '1991', 'Action', 'Wolf Team', '2', 'Hack and Slash', 'Isometric action RPG with multiple character classes and magic.', 'Defeat the dark sorcerer Castomira to save the land.', 'A polished isometric action-adventure by Wolf Team.', 'Arcus Odyssey features unique isometric combat and cooperative play. Choose your hero and battle through mythological stages in this highly-regarded 16-bit RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcus-odyssey-usa', 'Genesis', 'Arcus Odyssey (USA)', '1991', 'Action', 'Wolf Team', '2', 'Hack and Slash', 'Isometric action RPG with multiple character classes and magic.', 'Defeat the dark sorcerer Castomira to save the land.', 'The North American release of the isometric hit Arcus Odyssey.', 'Arcus Odyssey features unique isometric combat and cooperative play. Choose your hero and battle through mythological stages in this highly-regarded 16-bit RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ariel-the-little-mermaid-usa-europe', 'Genesis', 'Ariel the Little Mermaid (USA, Europe)', '1992', 'Platformer', 'BlueSky Software', '1', 'Action', 'Side-scrolling underwater action and exploration.', 'Rescue the sea creatures and defeat the sea witch Ursula.', 'An underwater adventure based on Disney''s Little Mermaid.', 'Dive under the sea in Ariel the Little Mermaid. Play as Ariel or King Triton to explore colorful reefs and battle aquatic villains in this 16-bit Disney classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arnold-palmer-tournament-golf-usa-europe', 'Genesis', 'Arnold Palmer Tournament Golf (USA, Europe)', '1990', 'Sports', 'Sega', '4', 'Golf Simulation', 'Realistic golf simulation with 18-hole courses and tournaments.', 'Win the tournament by achieving the lowest stroke count.', 'A professional golf sim endorsed by Arnold Palmer.', 'Arnold Palmer Tournament Golf offers precise 16-bit simulation. Master wind conditions and club selection in one of the most technical golf games on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arrow-flash-japan', 'Genesis', 'Arrow Flash (Japan)', '1990', 'Shooter', 'Renovation', '1', 'Vertical', 'Horizontal-scrolling shoot ''em up with a transforming mech.', 'Pilot the Arrow Flash craft to destroy the Viking fleet.', 'A classic shmup featuring a transforming protagonist.', 'Arrow Flash delivers high-octane 16-bit shooting action. Switch between a fighter jet and a giant robot to save the galaxy in this visually impressive Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arrow-flash-usa-europe', 'Genesis', 'Arrow Flash (USA, Europe)', '1990', 'Shooter', 'Renovation', '1', 'Vertical', 'Horizontal-scrolling shoot ''em up with a transforming mech.', 'Pilot the Arrow Flash craft to destroy the Viking fleet.', 'The Western release of the transforming mech shooter.', 'Arrow Flash delivers high-octane 16-bit shooting action. Switch between a fighter jet and a giant robot to save the galaxy in this visually impressive Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('art-alive-world', 'Genesis', 'Art Alive (World)', '1991', 'Creative', 'Sega', '1', 'Drawing', 'Interactive digital art studio and painting tool.', 'Create, color, and animate your own digital drawings.', 'A creative art suite for the Sega Genesis.', 'Unleash your creativity with Art Alive! Use stamps, brushes, and classic Sega characters to create your own 16-bit masterpieces on your television.');
