INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ashura-in-sonic-1', 'Genesis', 'Ashura in Sonic 1', '2021', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with the legendary "glitch" character Ashura.', 'Complete classic levels with Ashura''s green-and-black palette.', 'A rom-hack bringing the famous glitch-hog to Sonic 1.', 'Revisit Sonic 1 as the fan-favorite glitch, Ashura. This mod celebrates the classic technical error with a playable version of the iconic green hedgehog.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ashura-the-glitchhog-2---the-secret-zones', 'Genesis', 'Ashura The Glitchhog 2 - The Secret Zones', '2022', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming focusing on hidden and secret levels.', 'Discover the mystery behind the Secret Zones as Ashura.', 'A sequel to the Ashura the Glitchhog modification.', 'Explore uncharted territory in Ashura The Glitchhog 2. This mod adds new secret zones and challenges to the classic 16-bit engine for a fresh experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ashura-the-glitchhog-hallowen', 'Genesis', 'Ashura The Glitchhog Hallowen', '2022', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with a spooky Halloween theme.', 'Navigate through spooky levels and defeat festive bosses.', 'A Halloween-themed modification starring Ashura.', 'Get spooky with Ashura The Glitchhog Halloween. This festive rom-hack features re-themed levels and a haunting atmosphere for 16-bit platforming fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('assault-suit-leynos-japan', 'Genesis', 'Assault Suit Leynos (Japan)', '1990', 'Action', 'Masaya', '1', 'Run and Gun', 'Side-scrolling run-and-gun action with a customizable mech.', 'Defeat the robotic invaders and protect the space colony.', 'A legendary mech action game (Target Earth).', 'Assault Suit Leynos is a pioneer of the 16-bit mech genre. Experience intense combat, a deep weapon system, and a gripping sci-fi story on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-and-the-great-rescue-europe-enfrdeesit', 'Genesis', 'Asterix and the Great Rescue (Europe) (En,Fr,De,Es,It)', '1993', 'Platformer', 'Core Design', '1', 'Action', 'Side-scrolling platformer based on the famous French comics.', 'Rescue Obelix and the village from the Roman army.', 'A challenging adventure featuring the brave Gauls.', 'Join Asterix and the Great Rescue. Use magic potions and clever tactics to defeat Caesar’s legions in this colorful and difficult 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-and-the-great-rescue-usa', 'Genesis', 'Asterix and the Great Rescue (USA)', '1993', 'Platformer', 'Core Design', '1', 'Action', 'Side-scrolling platformer based on the famous French comics.', 'Rescue Obelix and the village from the Roman army.', 'The North American release of Asterix and the Great Rescue.', 'Join Asterix and the Great Rescue. Use magic potions and clever tactics to defeat Caesar’s legions in this colorful and difficult 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-and-the-power-of-the-gods-europe-beta', 'Genesis', 'Asterix and the Power of the Gods (Europe) (Beta)', '1995', 'Platformer', 'Core Design', '1', 'Action', 'Exploration-based platformer with large, open levels.', 'Find the shield of Vercingetorix to restore Gaul''s pride.', 'A beta version of the expansive Asterix sequel.', 'Preview the epic journey in Asterix and the Power of the Gods Beta. Experience the massive levels and open exploration of this ambitious 16-bit sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-and-the-power-of-the-gods-europe-enfrdees', 'Genesis', 'Asterix and the Power of the Gods (Europe) (En,Fr,De,Es)', '1995', 'Platformer', 'Core Design', '1', 'Action', 'Exploration-based platformer with large, open levels.', 'Find the shield of Vercingetorix to restore Gaul''s pride.', 'The definitive European release of the Power of the Gods.', 'Asterix and the Power of the Gods is one of the most expansive 16-bit platformers. Explore vast maps and complete quests in this beautifully animated Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atomic-robo-kid-japan', 'Genesis', 'Atomic Robo-Kid (Japan)', '1989', 'Shooter', 'Uplink', '2', 'Arcade', 'Multi-directional shooter featuring a small, customizable robot.', 'Traverse dangerous caverns and defeat giant mechanical bosses.', 'A unique and charming side-scrolling shooter.', 'Pilot the adorable yet deadly Atomic Robo-Kid. Navigate through complex levels and master your weapon systems in this stylish 16-bit arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atomic-robo-kid-usa', 'Genesis', 'Atomic Robo-Kid (USA)', '1989', 'Shooter', 'Uplink', '2', 'Arcade', 'Multi-directional shooter featuring a small, customizable robot.', 'Traverse dangerous caverns and defeat giant mechanical bosses.', 'The North American version of Atomic Robo-Kid.', 'Pilot the adorable yet deadly Atomic Robo-Kid. Navigate through complex levels and master your weapon systems in this stylish 16-bit arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atomic-runner-europe', 'Genesis', 'Atomic Runner (Europe)', '1992', 'Action', 'Data East', '1', 'Run and Gun', 'Fast-paced side-scrolling runner and shooter (Chelnov).', 'Escape your pursuers while shooting through alien hordes.', 'Data East’s unique arcade "runner" for the Genesis.', 'Atomic Runner (Chelnov) offers a unique challenge where the screen never stops. Test your reflexes in this high-intensity 16-bit action classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atomic-runner-usa', 'Genesis', 'Atomic Runner (USA)', '1992', 'Action', 'Data East', '1', 'Run and Gun', 'Fast-paced side-scrolling runner and shooter (Chelnov).', 'Escape your pursuers while shooting through alien hordes.', 'The North American release of the cult classic Chelnov.', 'Atomic Runner (Chelnov) offers a unique challenge where the screen never stops. Test your reflexes in this high-intensity 16-bit action classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atp-tour-europe', 'Genesis', 'ATP Tour (Europe)', '1994', 'Sports', 'Hitmen Productions', '2', 'Tennis Simulation', 'Professional tennis simulation with licensed players.', 'Win the ATP Tour championship to become number one.', 'A highly detailed tennis sim for the European market.', 'Experience pro tennis in ATP Tour. Featuring realistic ball physics and a deep career mode, it’s a premier sports simulation for the 16-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atp-tour-championship-tennis-usa', 'Genesis', 'ATP Tour Championship Tennis (USA)', '1995', 'Sports', 'Hitmen Productions', '2', 'Tennis Simulation', 'Professional tennis simulation with licensed players.', 'Win the ATP Tour championship to become number one.', 'The North American release of the ATP Tennis sim.', 'Experience pro tennis in ATP Tour Championship Tennis. Featuring realistic ball physics and a deep career mode, it’s a premier sports simulation for the 16-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('australian-rugby-league-europe', 'Genesis', 'Australian Rugby League (Europe)', '1990', 'Sports', 'Beaucomm Interactive', '2', 'Rugby Simulation', 'Isometric sports simulation with realistic rugby league rules.', 'Lead your Australian rugby team to the grand final victory.', 'A dedicated rugby league simulation for Sega Genesis.', 'Australian Rugby League brings the intensity of the pitch to your console. Experience authentic 16-bit sports action with deep tactical play and official team rosters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('awesome-possum-usa', 'Genesis', 'Awesome Possum (USA)', '1993', 'Platformer', 'Tengen', '1', 'Action', 'Side-scrolling platformer with an environmental message.', 'Collect recyclables and defeat Dr. Machino''s robots.', 'A fast-paced platformer starring a radical opossum.', 'Awesome Possum Kicks Dr. Machino''s Butt! Explore nature-themed levels and answer environmental trivia in this unique and energetic 16-bit platforming adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('awesome-possum-usa-beta', 'Genesis', 'Awesome Possum (USA) (Beta)', '1993', 'Platformer', 'Tengen', '1', 'Action', 'Side-scrolling platformer with an environmental message.', 'Collect recyclables and defeat Dr. Machino''s robots.', 'A pre-release beta version of Awesome Possum.', 'Preview the environmental heroics in the Awesome Possum Beta. Experience early level designs and mechanics of this eco-friendly 16-bit Sega platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aws-pro-moves-soccer-usa', 'Genesis', 'AWS Pro Moves Soccer (USA)', '1993', 'Sports', 'Teque London', '2', 'Soccer Simulation', 'Side-scrolling soccer simulation with customizable plays.', 'Win the world championship by outscoring international teams.', 'A tactical and fast-paced 16-bit soccer game.', 'AWS Pro Moves Soccer offers deep strategy on the pitch. Master precision passing and power shots to dominate the global standings in this classic Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ayrton-sennas-super-monaco-gp-ii---complete-1991-season', 'Genesis', 'Ayrton Senna''s Super Monaco GP II - Complete 1991 Season', '1992', 'Racing', 'Sega AM2', '1', 'Simulation', 'Formula 1 racing simulation with an updated driver roster.', 'Compete in the full 1991 racing season and win the title.', 'A modified season update for the legendary racing sim.', 'Relive the golden era of F1 with the Complete 1991 Season mod for Super Monaco GP II. Featuring accurate 16-bit racing physics and legendary driver names.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ayrton-sennas-super-monaco-gp-ii-japan-europe-enja', 'Genesis', 'Ayrton Senna''s Super Monaco GP II (Japan, Europe) (En,Ja)', '1992', 'Racing', 'Sega AM2', '1', 'Simulation', 'High-speed F1 racing simulation developed with Ayrton Senna.', 'Master tracks around the world to win the F1 World Championship.', 'The definitive 16-bit racing simulation for Mega Drive.', 'Ayrton Senna''s Super Monaco GP II is a pinnacle of racing on Sega. Experience the thrill of the cockpit with advice from the legendary champion himself.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ayrton-sennas-super-monaco-gp-ii-usa-enja', 'Genesis', 'Ayrton Senna''s Super Monaco GP II (USA) (En,Ja)', '1992', 'Racing', 'Sega AM2', '1', 'Simulation', 'High-speed F1 racing simulation developed with Ayrton Senna.', 'Master tracks around the world to win the F1 World Championship.', 'The North American release of the legendary racing sim.', 'Ayrton Senna''s Super Monaco GP II is a pinnacle of racing on Sega. Experience the thrill of the cockpit with advice from the legendary champion himself.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bob-usa-europe', 'Genesis', 'B.O.B. (USA, Europe)', '1993', 'Action', 'Gray Matter', '1', 'Run and Gun', 'Side-scrolling run-and-gun with a customizable arsenal.', 'Guide the robot B.O.B. through alien levels to find his date.', 'A quirky and mechanical 16-bit action adventure.', 'B.O.B. offers unique platforming with a focus on gadget management. Swap arms and use special tools to navigate dangerous planets in this Sega Genesis classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bob-usa-beta', 'Genesis', 'B.O.B. (USA) (Beta)', '1993', 'Action', 'Gray Matter', '1', 'Run and Gun', 'Side-scrolling run-and-gun with a customizable arsenal.', 'Guide the robot B.O.B. through alien levels to find his date.', 'A beta version of the robot action game B.O.B.', 'Test out B.O.B.''s arsenal in this early development build. A fascinating look at the mechanical platforming and level design of the 16-bit original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('babys-day-out-usa-proto', 'Genesis', 'Baby''s Day Out (USA) (Proto)', '1993', 'Platformer', 'Realtime Associates', '1', 'Action', 'Side-scrolling puzzle platformer based on the 1994 film.', 'Guide a crawling baby safely through hazardous environments.', 'An unreleased prototype based on the Hollywood movie.', 'Baby''s Day Out is a rare piece of Sega history. Protect the baby by manipulating the environment in this unique and creative 16-bit movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('babys-day-out-usa-proto-earlier', 'Genesis', 'Baby''s Day Out (USA) (Proto) (Earlier)', '1993', 'Platformer', 'Realtime Associates', '1', 'Action', 'Side-scrolling puzzle platformer based on the 1994 film.', 'Guide a crawling baby safely through hazardous environments.', 'An early unreleased prototype of Baby''s Day Out.', 'Discover the earliest stages of the Baby''s Day Out project. A rare prototype featuring experimental mechanics based on the classic family film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('back-to-the-future-part-iii-europe', 'Genesis', 'Back to the Future Part III (Europe)', '1991', 'Action', 'Images Software', '1', 'Platformer', 'Variety action game featuring four distinct gameplay styles.', 'Complete stages based on the movie to fix the timeline.', 'The official 16-bit tie-in for the trilogy''s finale.', 'Back to the Future Part III brings the Wild West to the Genesis. Master horse riding, shooting galleries, and train chases in this cinematic 16-bit challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('back-to-the-future-part-iii-usa', 'Genesis', 'Back to the Future Part III (USA)', '1991', 'Action', 'Images Software', '1', 'Platformer', 'Variety action game featuring four distinct gameplay styles.', 'Complete stages based on the movie to fix the timeline.', 'The North American version of the cinematic action game.', 'Back to the Future Part III brings the Wild West to the Genesis. Master horse riding, shooting galleries, and train chases in this cinematic 16-bit challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bad-omen-japan', 'Genesis', 'Bad Omen (Japan)', '1991', 'Shooter', 'Jaleco', '1', 'Horizontal', 'Tile-matching puzzle game with a competitive twist.', 'Arrange falling blocks to clear lines and defeat rivals.', 'The Japanese version of the puzzle game Puyo Puyo.', 'Bad Omen is a high-speed puzzle challenge for the Mega Drive. Master the art of chain reactions to send garbage blocks to your opponent''s side.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bahamut-senki-japan', 'Genesis', 'Bahamut Senki (Japan)', '1991', 'Strategy', 'Sega', '1', 'Tactical RPG', 'Turn-based strategy and tactical fantasy combat.', 'Conquer the map by managing troops and legendary beasts.', 'A deep fantasy strategy title from Sega of Japan.', 'Bahamut Senki offers epic tactical scale on the Mega Drive. Command humans, dragons, and demons in a quest for total continental domination.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ball-jacks-japan-europe', 'Genesis', 'Ball Jacks (Japan, Europe)', '1994', 'Sports', 'Namco', '2', 'Arcade', 'Futuristic sports game involving catching and throwing balls.', 'Outscore your opponent in a high-speed mechanical arena.', 'A unique and quirky Japanese arcade sports port.', 'Ball Jacks delivers fast-paced, competitive action. Use your mechanical robot to intercept and throw balls in this colorful 16-bit sports outlier.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('balloon-boy-china-unl', 'Genesis', 'Balloon Boy (China) (Unl)', '1994', 'Action', 'Unlicensed', '1', 'Arcade', 'Side-scrolling platformer with balloon-based physics.', 'Fly through levels using balloons to reach the goal.', 'An unlicensed Chinese platformer for the Mega Drive.', 'Balloon Boy brings unique flight mechanics to the 16-bit era. Navigate obstacles and enemies in this rare and interesting unlicensed Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ballz-3d---fighting-at-its-ballziest-usa-europe', 'Genesis', 'Ballz 3D - Fighting at Its Ballziest (USA, Europe)', '1994', 'Fighting', 'Critical Mass', '2', 'Competitive', '3D arena fighting game with characters made of spheres.', 'Defeat rivals in a pseudo-3D environment using combos.', 'A unique 16-bit fighter featuring physics-based sprites.', 'Ballz 3D pushes the limits of the Genesis with its spherical character design. Experience a different kind of 16-bit fighter with attitude and 3D movement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-super-model-usa', 'Genesis', 'Barbie Super Model (USA)', '1993', 'Platformer', 'Imagineering', '1', 'Action', 'Interactive simulation and mini-game collection.', 'Complete fashion shoots and travel to famous locations.', 'A Barbie-themed creative and fashion game for Sega.', 'Barbie Super Model combines creativity with casual gameplay. Master the runway and design outfits in this popular 16-bit title for younger gamers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-vacation-adventure-usa', 'Genesis', 'Barbie Vacation Adventure (USA)', '1994', 'Adventure', 'Imagineering', '1', 'Exploration', 'Adventure mini-game collection featuring travel themes.', 'Complete various vacation activities like camping and beach fun.', 'A casual adventure title starring the iconic Barbie.', 'Join Barbie on a cross-country trip in Barbie Vacation Adventure. Enjoy diverse 16-bit mini-games ranging from horse riding to volleyball.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bare-knuckle---ikari-no-tetsuken-~-streets-of-rage-world', 'Genesis', 'Bare Knuckle - Ikari no Tetsuken ~ Streets of Rage (World)', '1991', 'Action', 'Sega', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with multiple playable characters.', 'Fight through the streets to take down Mr. X''s crime syndicate.', 'The Japanese original of the legendary Streets of Rage.', 'Bare Knuckle (Streets of Rage) is a 16-bit combat essential. Master the urban brawl with an incredible soundtrack and gritty street-fighting action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bare-knuckle---ikari-no-tetsuken-~-streets-of-rage-world-rev-a', 'Genesis', 'Bare Knuckle - Ikari no Tetsuken ~ Streets of Rage (World) (Rev A)', '1991', 'Action', 'Sega', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with multiple playable characters.', 'Fight through the streets to take down Mr. X''s crime syndicate.', 'An updated revision (Rev A) of the street brawler.', 'Bare Knuckle (Streets of Rage) is a 16-bit combat essential. Master the urban brawl with an incredible soundtrack and gritty street-fighting action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bare-knuckle-ii---shitou-heno-chingonka-~-streets-of-rage-ii-japan-europe', 'Genesis', 'Bare Knuckle II - Shitou heno Chingonka ~ Streets of Rage II (Japan, Europe)', '1992', 'Action', 'Sega', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with four unique combat styles.', 'Defeat the Neo-Chaos syndicate and rescue Adam Hunter.', 'The definitive 16-bit brawler known as Streets of Rage 2.', 'Bare Knuckle II is a masterclass in game design. Experience the best combat and music on the Mega Drive as you battle through the city''s underbelly.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bare-knuckle-ii-japan-beta', 'Genesis', 'Bare Knuckle II (Japan) (Beta)', '1992', 'Action', 'Sega', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with four unique combat styles.', 'Defeat the Neo-Chaos syndicate and rescue Adam Hunter.', 'A beta development build of the legendary sequel.', 'Peek into the development of a classic with the Bare Knuckle II Beta. Experience the core combat of this 16-bit legend in its early stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bare-knuckle-iii-japan', 'Genesis', 'Bare Knuckle III (Japan)', '1994', 'Action', 'Sega', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with faster combat and dash moves.', 'Stop a nuclear plot and find the missing city officials.', 'The complex and fast-paced third entry in the series.', 'Bare Knuckle III offers more depth and speed than its predecessors. Experience branching paths and secret characters in the ultimate 16-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bare-knuckle-iii-japan-en-by-twilight-v10', 'Genesis', 'Bare Knuckle III (Japan) [En by Twilight v1.0]', '1994', 'Action', 'Sega', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with faster combat and dash moves.', 'Stop a nuclear plot and find the missing city officials.', 'An English fan translation of the original Bare Knuckle III.', 'Play the uncensored version of the third brawler in English. Bare Knuckle III features a different story and difficulty compared to its Western release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barkley-shut-up-and-jam!-usa-europe', 'Genesis', 'Barkley Shut Up and Jam! (USA, Europe)', '1994', 'Sports', 'Accolade', '4', 'Basketball Arcade', 'Street basketball simulation with "no-rules" arcade play.', 'Win streetball games by scoring and physical play.', 'An aggressive urban basketball game starring Charles Barkley.', 'Barkley Shut Up and Jam! brings the street game to your Genesis. Experience 2-on-2 basketball with high-flying dunks and no whistles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barkley-shut-up-and-jam!-2-usa', 'Genesis', 'Barkley Shut Up and Jam! 2 (USA)', '1995', 'Sports', 'Accolade', '4', 'Basketball Arcade', 'Street basketball simulation with expanded rosters and moves.', 'Dominate the street courts across various global locations.', 'The high-energy sequel to Barkley''s basketball hit.', 'Shut Up and Jam! 2 ramps up the 16-bit basketball action. Featuring more players and bigger dunks, it''s a staple of the Sega Genesis sports library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barkley-shut-up-and-jam!-2-usa-beta', 'Genesis', 'Barkley Shut Up and Jam! 2 (USA) (Beta)', '1995', 'Sports', 'Accolade', '4', 'Basketball Arcade', 'Street basketball simulation with expanded rosters and moves.', 'Dominate the street courts across various global locations.', 'A beta version of the basketball sequel.', 'Experience early courts and mechanics in the Barkley Shut Up and Jam! 2 Beta. A great look at the evolution of this 16-bit arcade sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barneys-hide-&-seek-game-usa', 'Genesis', 'Barney''s Hide & Seek Game (USA)', '1993', 'Educational', 'RSP', '1', 'Hide and Seek', 'Educational hide and seek game for younger children.', 'Find Barney''s friends and hidden objects in colorful levels.', 'A gentle educational game based on the popular TV show.', 'Barney''s Hide & Seek Game is a perfect introduction to gaming for kids. Explore safe, colorful 16-bit environments with the world''s most famous purple dinosaur.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bass-masters-classic---pro-edition-usa', 'Genesis', 'Bass Masters Classic - Pro Edition (USA)', '1995', 'Sports', 'Starfish', '1', 'Fishing Simulation', 'Realistic fishing simulation with professional equipment and weather.', 'Win various tournaments to become the ultimate Bass Master.', 'The expanded Pro Edition of the classic fishing sim.', 'Bass Masters Classic - Pro Edition offers enhanced 16-bit fishing. Choose your lures, rods, and boats to dominate the professional bass circuit on Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bass-masters-classic-usa', 'Genesis', 'Bass Masters Classic (USA)', '1994', 'Sports', 'Starfish', '1', 'Fishing Simulation', 'Realistic fishing simulation with focus on technique and location.', 'Catch the heaviest bass across multiple lake environments.', 'A solid professional fishing simulator for the Genesis.', 'Experience the thrill of the catch in Bass Masters Classic. Master lure depth and tension in this detailed 16-bit sport fishing simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman---revenge-of-the-joker-usa', 'Genesis', 'Batman - Revenge of the Joker (USA)', '1992', 'Action', 'Sunsoft', '1', 'Platformer', 'Side-scrolling action platformer with projectile combat.', 'Traverse dangerous levels to stop the Joker''s latest plot.', 'The Genesis version of the NES hit "Return of the Joker."', 'Batman - Revenge of the Joker features high-quality 16-bit sprites and gun-based combat. Fight through metallic stages and defeat the Clown Prince of Crime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-europe', 'Genesis', 'Batman (Europe)', '1990', 'Action', 'Sunsoft', '1', 'Platformer', 'Side-scrolling action beat ''em up based on the 1989 film.', 'Battle through Gotham to face the Joker at the Cathedral.', 'The iconic Sunsoft adaptation of the Batman movie.', 'Batman on the Sega Genesis is a dark, atmospheric action masterpiece. Master your Batarang and grappling hook in this visually stunning 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-japan', 'Genesis', 'Batman (Japan)', '1990', 'Action', 'Sunsoft', '1', 'Platformer', 'Side-scrolling action beat ''em up based on the 1989 film.', 'Battle through Gotham to face the Joker at the Cathedral.', 'The Japanese Mega Drive version of Sunsoft''s Batman.', 'Batman on the Sega Mega Drive is a dark, atmospheric action masterpiece. Master your Batarang and grappling hook in this visually stunning 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-usa', 'Genesis', 'Batman (USA)', '1990', 'Action', 'Sunsoft', '1', 'Platformer', 'Side-scrolling action beat ''em up based on the 1989 film.', 'Battle through Gotham to face the Joker at the Cathedral.', 'The North American release of the Sunsoft Batman hit.', 'Batman on the Sega Genesis is a dark, atmospheric action masterpiece. Master your Batarang and grappling hook in this visually stunning 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-forever-world', 'Genesis', 'Batman Forever (World)', '1995', 'Action', 'Probe Software', '1', 'Beat ''em Up', 'Digitized side-scrolling brawler with multiple gadgets.', 'Navigate the Arkham Asylum and stop Riddler and Two-Face.', 'A digitized action game based on the 1995 film.', 'Batman Forever brings the movie''s stars to life with digitized graphics. Use a massive array of gadgets to solve puzzles and fight through Gotham''s underworld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-returns-world', 'Genesis', 'Batman Returns (World)', '1992', 'Action', 'Aspect', '1', 'Beat ''em Up', 'Side-scrolling action with heavy emphasis on boss fights.', 'Stop the Penguin and Catwoman from taking over Gotham.', 'A cinematic action game based on the movie sequel.', 'Batman Returns on the Genesis offers intense 16-bit combat. Use the grappling hook to swing through snowy Gotham and defeat the Penguin''s circus gang.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-golfer-yui-japan', 'Genesis', 'Battle Golfer Yui (Japan)', '1991', 'Sports', 'Sigma Enterprises', '1', 'Golf Simulation', 'Hybrid of golf simulation and Japanese visual novel/RPG.', 'Win golf matches to uncover a dark corporate conspiracy.', 'A unique "Battle Golf" experience with a story mode.', 'Battle Golfer Yui is one of the strangest and most charming games on the Mega Drive. Combine sports simulation with a sci-fi narrative in this Japanese classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-mania-japan', 'Genesis', 'Battle Mania (Japan)', '1991', 'Shooter', 'VIC Tokai', '2', 'Horizontal', 'Side-scrolling shoot ''em up with two simultaneous characters.', 'Blast through waves of enemies to stop a sinister organization.', 'A stylish and humorous shmup known as Trouble Shooter.', 'Battle Mania (Trouble Shooter) delivers high-energy 16-bit action. Control Madison and Crystal as they fly through vibrant levels with a killer soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-mania-daiginjou-japan-korea-en-by-mijet-v20061029', 'Genesis', 'Battle Mania Daiginjou (Japan, Korea) [En by MIJET v20061029]', '1993', 'Shooter', 'VIC Tokai', '2', 'Horizontal', 'Side-scrolling shoot ''em up with enhanced mechanics and speed.', 'Pursue the villains across beautifully detailed environments.', 'The English-translated sequel to Battle Mania.', 'Experience the legendary Battle Mania Daiginjou in English. Widely considered one of the best shmups on the Mega Drive for its humor, art, and intense gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-mania-daiginjou-japan-korea-en-by-mijet-v20061029-~trouble-shooter-vintage', 'Genesis', 'Battle Mania Daiginjou (Japan, Korea) [En by MIJET v20061029] (~Trouble Shooter Vintage)', '1993', 'Shooter', 'VIC Tokai', '2', 'Horizontal', 'Side-scrolling shoot ''em up with enhanced mechanics and speed.', 'Pursue the villains across beautifully detailed environments.', 'The English-translated sequel to Battle Mania.', 'Experience the legendary Battle Mania Daiginjou in English. Widely considered one of the best shmups on the Mega Drive for its humor, art, and intense gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-mania-daiginjou-japan', 'Genesis', 'Battle Mania Daiginjou (Japan)', '1993', 'Shooter', 'VIC Tokai', '2', 'Horizontal', 'Side-scrolling shoot ''em up with enhanced mechanics and speed.', 'Pursue the villains across beautifully detailed environments.', 'The original Japanese release of the Daiginjou sequel.', 'Battle Mania Daiginjou is a technical showcase for the Mega Drive. Featuring some of the best parallax scrolling and music on the system, it''s a shmup essential.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battlemaster-usa', 'Genesis', 'Battlemaster (USA)', '1991', 'Strategy', 'SSI', '1', 'Turn-Based', 'Isometric squad-based real-time strategy and combat.', 'Command a group of warriors to conquer various territories.', 'A port of the complex PC tactical strategy game.', 'Battlemaster offers deep squad management on the Genesis. Command four different races and master real-time tactics in this ambitious fantasy conquest sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battletech---a-game-of-armored-combat-usa', 'Genesis', 'BattleTech - A Game of Armored Combat (USA)', '1994', 'Strategy', 'Beam Software', '1', 'Tactical', 'Isometric mech combat simulation with tactical customization.', 'Pilot a BattleMech to complete dangerous planetary missions.', 'Based on the famous tabletop wargaming universe.', 'BattleTech brings heavy metal destruction to your Genesis. Customize your mech’s weapons and heat sinks to survive intense 16-bit isometric warfare.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battletoads-world', 'Genesis', 'Battletoads (World)', '1991', 'Action', 'Rare', '2', 'Beat ''em Up', 'High-difficulty side-scrolling brawler and vehicle stages.', 'Rescue Pimple and Princess Angelica from the Dark Queen.', 'One of the most challenging platformers of the 16-bit era.', 'Battletoads is famous for its crushing difficulty and variety. From the Turbo Tunnel to the Clinger-Winger, test your reflexes in this high-octane Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battletoads-&-double-dragon-usa', 'Genesis', 'Battletoads & Double Dragon (USA)', '1993', 'Action', 'Rare', '2', 'Beat ''em Up', 'Crossover side-scrolling beat ''em up with multiple heroes.', 'Team up to defeat the combined forces of the Dark Queen and Abobo.', 'The ultimate 16-bit crossover between two hit franchises.', 'Battletoads & Double Dragon offers fantastic co-op combat. Choose your favorite toad or dragon and punch through space in this action-packed brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beast-warriors-japan', 'Genesis', 'Beast Warriors (Japan)', '1995', 'Action', 'Seibutsu', '1', 'Beat ''em Up', 'One-on-one fighting game featuring giant monsters.', 'Defeat other beasts to become the king of the monsters.', 'A Japanese monster fighting game with RPG elements.', 'Beast Warriors lets you control massive prehistoric creatures. Level up your monster and battle for supremacy in this unique 16-bit fighting title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beast-wrestler-usa', 'Genesis', 'Beast Wrestler (USA)', '1994', 'Fighting', 'Amplified Games', '2', 'Competitive', 'One-on-one fighting game featuring giant monsters.', 'Defeat other beasts to become the king of the monsters.', 'The North American version of the monster fighter.', 'Beast Wrestler brings kaiju-style combat to the Genesis. Evolve your beast and master grappling moves to dominate the arena in this gritty 16-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beauty-and-the-beast---belles-quest-usa', 'Genesis', 'Beauty and the Beast - Belle''s Quest (USA)', '1993', 'Platformer', 'Software Creations', '1', 'Action', 'Side-scrolling adventure focusing on puzzles and exploration.', 'Explore the castle and solve mysteries to break the curse.', 'A story-driven game based on the Disney film.', 'Beauty and the Beast - Belle''s Quest focuses on the film''s narrative. Help Belle navigate the village and castle in this charming 16-bit Disney adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beauty-and-the-beast---roar-of-the-beast-usa', 'Genesis', 'Beauty and the Beast - Roar of the Beast (USA)', '1994', 'Platformer', 'Software Creations', '1', 'Action', 'Side-scrolling action game with combat and survival.', 'Protect the castle from intruders and survive the forest.', 'The action-focused counterpart to Belle''s Quest.', 'Play as the Beast in Roar of the Beast. Fight through dangerous environments and protect your home in this challenging 16-bit Sega Genesis action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beavis-and-butt-head-europe', 'Genesis', 'Beavis and Butt-Head (Europe)', '1994', 'Action', 'Radical Entertainment', '1', 'Platformer', 'Point-and-click adventure with puzzle-solving and mini-games.', 'Complete various zany tasks to get tickets to a GWAR concert.', 'A crude and hilarious adventure based on the MTV show.', 'Beavis and Butt-Head captures the show''s humor perfectly. Explore Highland and solve gross-out puzzles in this unique 16-bit Sega adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beavis-and-butt-head-usa', 'Genesis', 'Beavis and Butt-Head (USA)', '1994', 'Action', 'Radical Entertainment', '1', 'Platformer', 'Point-and-click adventure with puzzle-solving and mini-games.', 'Complete various zany tasks to get tickets to a GWAR concert.', 'The North American release of the MTV cult hit.', 'Beavis and Butt-Head captures the show''s humor perfectly. Explore Highland and solve gross-out puzzles in this unique 16-bit Sega adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beavis-and-butt-head-usa-beta', 'Genesis', 'Beavis and Butt-Head (USA) (Beta)', '1994', 'Action', 'Radical Entertainment', '1', 'Platformer', 'Point-and-click adventure with puzzle-solving and mini-games.', 'Complete various zany tasks to get tickets to a GWAR concert.', 'A pre-release beta version of the Beavis and Butt-Head game.', 'See the development of MTV’s favorite duo with the Beavis and Butt-Head Beta. A fascinating look at the creation of this 16-bit adventure game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beethovens-2nd---the-quest-for-pups-prototype', 'Genesis', 'Beethoven''s 2nd - The Quest for Pups (prototype)', '1994', 'Platformer', 'Unexpected Development', '1', 'Action', 'Side-scrolling platformer based on the family movie.', 'Navigate through levels to rescue your lost puppies.', 'An unreleased prototype featuring the famous St. Bernard.', 'Beethoven''s 2nd brings family-friendly platforming to the Genesis. Rescue the pups and avoid obstacles in this rare 16-bit cinematic prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ben-10-unl', 'Genesis', 'Ben 10 (Unl)', '2018', 'Platformer', 'Unlicensed', '1', 'Action', 'Side-scrolling action platformer based on the animated series.', 'Use the Omnitrix to transform into aliens and defeat enemies.', 'An unlicensed 16-bit take on the Ben 10 franchise.', 'Experience Ben 10 on the Sega Genesis! Use alien transformations to battle through levels in this rare and interesting unlicensed 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('berenstain-bears-camping-adventure-the-usa', 'Genesis', 'Berenstain Bears'' Camping Adventure, The (USA)', '1994', 'Educational', 'Imagineering', '1', 'Adventure', 'Isometric exploration and adventure game for kids.', 'Navigate the wilderness and complete camping tasks.', 'A family-oriented adventure based on the book series.', 'Join the Berenstain Bears on a camping trip. Explore the great outdoors and solve simple puzzles in this educational and charming 16-bit Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('best-of-the-best---championship-karate-europe', 'Genesis', 'Best of the Best - Championship Karate (Europe)', '1992', 'Fighting', 'Loriciel', '2', 'Competitive', 'One-on-one martial arts simulator with deep customization.', 'Train your fighter and win the international karate circuit.', 'A realistic kickboxing simulation for the Sega Genesis.', 'Best of the Best offers technical 16-bit martial arts. Customize your moves and stamina to climb the ranks in this deep karate simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('best-of-the-best---championship-karate-usa', 'Genesis', 'Best of the Best - Championship Karate (USA)', '1992', 'Fighting', 'Loriciel', '2', 'Competitive', 'One-on-one martial arts simulator with deep customization.', 'Train your fighter and win the international karate circuit.', 'The North American release of the karate simulator.', 'Best of the Best offers technical 16-bit martial arts. Customize your moves and stamina to climb the ranks in this deep karate simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beyond-oasis-usa', 'Genesis', 'Beyond Oasis (USA)', '1994', 'Action-Adventure', 'Ancient', '1', 'Hack and Slash', 'Top-down action RPG with real-time combat and summons.', 'Use elemental spirits to stop the resurrection of Agito.', 'One of the most beautiful and fluid action RPGs on Sega.', 'Beyond Oasis (The Story of Thor) is a 16-bit masterpiece. Experience incredible combat, elemental magic, and a vast world in this legendary Sega Genesis title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beyond-zero-tolerance-usa-proto', 'Genesis', 'Beyond Zero Tolerance (USA) (Proto)', '1996', 'Shooter', 'Raster Productions', '1', 'First-Person', 'First-person shooter with pseudo-3D environments and linked-play support.', 'Infiltrate enemy bases and neutralize the bio-technological threat.', 'The unreleased prototype sequel to Zero Tolerance.', 'Beyond Zero Tolerance pushes the 16-bit hardware with impressive FPS action. Experience early 3D exploration and intense combat in this rare Sega Genesis prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bible-adventures-usa-unl', 'Genesis', 'Bible Adventures (USA) (Unl)', '1991', 'Action', 'Wisdom Tree', '1', 'Platformer', 'Side-scrolling platformer based on various biblical stories.', 'Complete tasks like collecting animals for Noah''s Ark or saving baby Moses.', 'An unlicensed collection of three Bible-themed games.', 'Bible Adventures offers a unique take on platforming with puzzle elements. Play through iconic stories in this rare and famous unlicensed 16-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bigs-fishing-derby', 'Genesis', 'Big''s Fishing Derby', '2020', 'Sports', 'Fan Hack', '1', 'Fishing Arcade', 'Fishing simulation focusing on timing and environmental interaction.', 'Catch the biggest fish possible to win the tournament as Big the Cat.', 'A modern rom-hack featuring Big the Cat''s fishing mechanics.', 'Join Big the Cat in Big''s Fishing Derby. A creative modification that brings a dedicated fishing experience to the classic 16-bit Sega engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bill-walsh-college-football-usa-europe', 'Genesis', 'Bill Walsh College Football (USA, Europe)', '1993', 'Sports', 'Sculptured Software', '2', 'Football Simulation', 'American football simulation with college teams and playbooks.', 'Lead your chosen college team to a bowl game victory.', 'The first college football game from the EA Sports engine.', 'Bill Walsh College Football brings the pageantry of NCAA to the Genesis. Execute classic plays and master the 16-bit gridiron in this sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bill-walsh-college-football-95-usa', 'Genesis', 'Bill Walsh College Football 95 (USA)', '1994', 'Sports', 'Sculptured Software', '2', 'Football Simulation', 'American football simulation with expanded teams and 1995 rosters.', 'Achieve a perfect season and win the National Championship.', 'The refined sequel to the original Bill Walsh football game.', 'Bill Walsh College Football 95 features improved AI and smoother passing. Experience the intensity of college rivalries in this deep 16-bit sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bills-tomato-game-usa', 'Genesis', 'Bill''s Tomato Game (USA)', '1991', 'Puzzle', 'Bill Walsh', '1', 'Arcade', 'Puzzle-platformer involving guiding a tomato through Rube Goldberg machines.', 'Use various gadgets to help Bill the Tomato reach the goal safely.', 'A quirky and creative physics-based puzzle game.', 'Bill''s Tomato Game is a hidden gem of logic and timing. Solve intricate environmental puzzles in this colorful and unique 16-bit Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bimini-run-usa', 'Genesis', 'Bimini Run (USA)', '1991', 'Racing', 'Vectordean', '1', 'Arcade', 'Top-down boat racing and combat adventure.', 'Pilot a high-speed boat to infiltrate an island and rescue a girl.', 'A tropical action game with boat-based combat.', 'Bimini Run offers fast-paced aquatic action. Navigate the open seas, dodge mines, and defeat enemy fleets in this unique 16-bit vehicle adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bio-hazard-battle-usa-europe', 'Genesis', 'Bio Hazard Battle (USA, Europe)', '1992', 'Shooter', 'Toaplan', '2', 'Horizontal', 'Side-scrolling shoot ''em up with organic/biological ship designs.', 'Pilot one of four bio-ships to destroy the mutated threat.', 'A visually stunning and atmospheric biological shmup.', 'Bio Hazard Battle features incredible parallax scrolling and eerie music. Master the unique weapon systems to survive the post-apocalyptic world of G-9.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bio-hazard-battle-usa-beta', 'Genesis', 'Bio Hazard Battle (USA) (Beta)', '1992', 'Shooter', 'Toaplan', '2', 'Horizontal', 'Side-scrolling shoot ''em up with organic/biological ship designs.', 'Pilot one of four bio-ships to destroy the mutated threat.', 'A beta development version of Bio Hazard Battle.', 'Get a look at the early bio-organic designs in the Bio Hazard Battle Beta. Experience the core shmup mechanics that made this 16-bit title a cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailor-moon-japan', 'Genesis', 'Bishoujo Senshi Sailor Moon (Japan)', '1993', 'Action', 'Angel', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring the five main Sailor Scouts.', 'Fight through Tokyo''s streets to defeat the Dark Kingdom.', 'The legendary anime brawler for the Mega Drive.', 'Bishoujo Senshi Sailor Moon brings the magic of the anime to life. Use unique special attacks and save the city in this polished 16-bit girl-power brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailor-moon-en-v10', 'Genesis', 'Bishoujo Senshi Sailor Moon EN [v1.0]', '1993', 'Action', 'Angel', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring the five main Sailor Scouts.', 'Fight through Tokyo''s streets to defeat the Dark Kingdom.', 'The English fan translation of the Sailor Moon brawler.', 'Play the iconic Sailor Moon Mega Drive game in English! Experience the full story and brawling action of the Sailor Scouts in this high-quality 16-bit translation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blades-of-vengeance-usa-europe', 'Genesis', 'Blades of Vengeance (USA, Europe)', '1993', 'Action', 'Beam Software', '2', 'Side-Scrolling', 'Side-scrolling action platformer with three playable classes.', 'Choose a Huntress, Barbarian, or Sorcerer to defeat the Dark Lord.', 'A high-fantasy brawler with RPG elements.', 'Blades of Vengeance features massive sprites and cooperative play. Explore detailed fantasy levels and master unique combat styles in this 16-bit Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blaster-master-2-usa', 'Genesis', 'Blaster Master 2 (USA)', '1993', 'Action', 'Sunsoft', '1', 'Action Platformer', 'Hybrid of side-scrolling platforming and top-down exploration.', 'Pilot the Sophia 4th tank to stop the radioactive mutation.', 'The exclusive 16-bit sequel to the NES classic.', 'Blaster Master 2 expands the series with massive bosses and vehicle upgrades. Toggle between tank combat and on-foot action in this intense 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blockbuster-world-video-game-championship-ii-usa', 'Genesis', 'Blockbuster World Video Game Championship II (USA)', '1991', 'Sports', 'Realtime Associates', '2', 'Arcade', 'Multi-game competition featuring various Genesis titles.', 'Achieve the highest possible score across several different games.', 'A rare reproduction of the official 90s tournament cart.', 'Blockbuster World Video Game Championship II is a piece of competitive history. Test your skills in timed challenges from the biggest hits of the 16-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blockout-world', 'Genesis', 'Blockout (World)', '1989', 'Puzzle', 'California Dreams', '2', 'Tetris-Style', '3D block-stacking puzzle game from an isometric perspective.', 'Rotate and place falling blocks to clear complete layers.', 'A three-dimensional evolution of the Tetris formula.', 'Blockout challenges your spatial awareness on the Sega Genesis. Experience the depth of 3D puzzle-solving in this addictive and unique 16-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bloodshot-europe-enfrdees', 'Genesis', 'Bloodshot (Europe) (En,Fr,De,Es)', '1991', 'Action', 'Domark', '1', 'Run and Gun', 'First-person shooter with split-screen multiplayer support.', 'Infiltrate enemy territory and eliminate mechanical threats.', 'A gritty 16-bit FPS known as Battle Frenzy in the US.', 'Bloodshot delivers intense corridor-crawling action. Blast through robotic enemies and escape before the timer runs out in this impressive 16-bit technical feat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blue-almanac-japan', 'Genesis', 'Blue Almanac (Japan)', '1991', 'Strategy', 'Hot-B', '1', 'Turn-Based', 'Turn-based RPG with space exploration and sci-fi themes.', 'Travel between planets to uncover an interstellar mystery.', 'A deep and visually unique Japanese RPG.', 'Blue Almanac offers a classic 16-bit RPG experience with a science fiction twist. Explore alien worlds and master turn-based combat in this rare Mega Drive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blue-knuckles-in-sonic-the-hedgehog', 'Genesis', 'Blue Knuckles in Sonic the Hedgehog', '2022', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with a custom Blue Knuckles character.', 'Conquer Sonic 1 stages using the gliding and climbing of Knuckles.', 'A character-swap rom-hack for the first Sonic game.', 'What if Knuckles was blue? Experience Blue Knuckles in Sonic the Hedgehog, featuring all the abilities of the echidna within the iconic 16-bit levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blue-sphere-plus', 'Genesis', 'Blue Sphere Plus', '2021', 'Arcade', 'Fan Hack', '1', 'Score Attack', 'Puzzle-solving based on the Sonic & Knuckles special stages.', 'Collect all the blue spheres while avoiding red ones.', 'An enhanced version of the classic Sonic special stage game.', 'Blue Sphere Plus offers more levels and refined mechanics. Master the "get blue spheres" gameplay in this expanded 16-bit puzzle-platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('body-count-europe-enfrdeesit', 'Genesis', 'Body Count (Europe) (En,Fr,De,Es,It)', '1994', 'Shooter', 'Gremlin Interactive', '1', 'Run and Gun', 'First-person light-gun rail shooter with a high body count.', 'Blast through waves of alien invaders to save humanity.', 'A fast-paced and chaotic arcade-style shooter.', 'Body Count is all about non-stop action. Support for the Menacer light gun makes this 16-bit alien-blasting experience even more intense on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('body-count-europe-enfrdeesit-beta', 'Genesis', 'Body Count (Europe) (En,Fr,De,Es,It) (Beta)', '1994', 'Shooter', 'Gremlin Interactive', '1', 'Run and Gun', 'First-person light-gun rail shooter with a high body count.', 'Blast through waves of alien invaders to save humanity.', 'A beta version of the high-octane rail shooter.', 'Test your aim in the Body Count Beta. Experience the early development of this chaotic alien shooter and its unique 16-bit perspective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bonanza-bros-usa-europe', 'Genesis', 'Bonanza Bros. (USA, Europe)', '1991', 'Action', 'Sega', '2', 'Stealth', 'Stealth-based puzzle platformer with cooperative play.', 'Infiltrate various locations to steal specific items and escape.', 'A charming and humorous arcade port from Sega.', 'Join Mobo and Robo in Bonanza Bros. Use stealth, cover, and teamwork to pull off the ultimate heist in this stylish and colorful 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bonanza-bros-world', 'Genesis', 'Bonanza Bros. (World)', '1991', 'Action', 'Sega', '2', 'Stealth', 'Stealth-based puzzle platformer with cooperative play.', 'Infiltrate various locations to steal specific items and escape.', 'The international release of the heist classic Bonanza Bros.', 'Join Mobo and Robo in Bonanza Bros. Use stealth, cover, and teamwork to pull off the ultimate heist in this stylish and colorful 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bonanza-bros-world-rev-a', 'Genesis', 'Bonanza Bros. (World) (Rev A)', '1991', 'Action', 'Sega', '2', 'Stealth', 'Stealth-based puzzle platformer with cooperative play.', 'Infiltrate various locations to steal specific items and escape.', 'An updated revision of the arcade-style heist game.', 'Join Mobo and Robo in Bonanza Bros. Use stealth, cover, and teamwork to pull off the ultimate heist in this stylish and colorful 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bonkers-usa-europe', 'Genesis', 'Bonkers (USA, Europe)', '1994', 'Platformer', 'Capcom', '1', 'Action', 'Variety-based platformer with mini-games and puzzles.', 'Help Bonkers the Bobcat solve mysteries in Hollywood.', 'Based on the Disney animated series Bonkers.', 'Bonkers brings the cartoon chaos to your Genesis. Solve crimes and complete wacky challenges in this beautifully animated 16-bit Disney adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boogerman---a-pick-and-flick-adventure-europe', 'Genesis', 'Boogerman - A Pick and Flick Adventure (Europe)', '1994', 'Platformer', 'Interplay', '1', 'Action', 'Side-scrolling platformer featuring gross-out humor.', 'Use boogers and burps to defeat the evil Booger Meister.', 'A cult classic platformer with a disgusting twist.', 'Boogerman - A Pick and Flick Adventure is 16-bit humor at its finest. Master the unique "gross" abilities to save Dimension X-Crement in this colorful Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boogerman---a-pick-and-flick-adventure-usa', 'Genesis', 'Boogerman - A Pick and Flick Adventure (USA)', '1994', 'Platformer', 'Interplay', '1', 'Action', 'Side-scrolling platformer featuring gross-out humor.', 'Use boogers and burps to defeat the evil Booger Meister.', 'The North American release of the gross-out platformer.', 'Boogerman - A Pick and Flick Adventure is 16-bit humor at its finest. Master the unique "gross" abilities to save Dimension X-Crement in this colorful Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boogie-woogie-bowling-japan', 'Genesis', 'Boogie Woogie Bowling (Japan)', '1993', 'Sports', 'Data East', '4', 'Bowling Arcade', 'Sports simulation with anime-style characters and power-ups.', 'Win bowling tournaments using special shots and skills.', 'A quirky and fun Japanese bowling game.', 'Boogie Woogie Bowling adds a rhythmic twist to the lanes. Choose your character and master the power bar to strike out the competition on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boxing-legends-of-the-ring-usa', 'Genesis', 'Boxing Legends of the Ring (USA)', '1993', 'Sports', 'Imagineering', '2', 'Boxing Simulation', 'One-on-one boxing simulation with a pseudo-3D perspective.', 'Rise through the ranks to defeat legendary boxers.', 'A realistic boxing game featuring real-life legends.', 'Boxing Legends of the Ring puts you in the gloves of greats like Roberto Durán. Master timing and stamina in this detailed 16-bit sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bram-stokers-dracula-europe', 'Genesis', 'Bram Stoker''s Dracula (Europe)', '1993', 'Action', 'Psygnosis', '1', 'Action Platformer', 'Side-scrolling action-adventure based on the 1992 film.', 'Battle through various historical and gothic levels to defeat Dracula.', 'A cinematic action game with atmospheric visuals.', 'Bram Stoker''s Dracula brings the horror of the movie to your Genesis. Fight through the night and survive the supernatural in this dark 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bram-stokers-dracula-usa', 'Genesis', 'Bram Stoker''s Dracula (USA)', '1993', 'Action', 'Psygnosis', '1', 'Action Platformer', 'Side-scrolling action-adventure based on the 1992 film.', 'Battle through various historical and gothic levels to defeat Dracula.', 'The North American release of the Dracula movie tie-in.', 'Bram Stoker''s Dracula brings the horror of the movie to your Genesis. Fight through the night and survive the supernatural in this dark 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brazookas-beta-v01-brazil-unl', 'Genesis', 'Brazookas (beta v.0.1) (Brazil) (Unl)', '1994', 'Action', 'Unlicensed', '2', 'Beat ''em Up', 'Soccer simulation with a focus on Brazilian teams and regional leagues.', 'Win the Brazilian championship by outplaying rival clubs.', 'An unlicensed Brazilian soccer hack/mod for Sega.', 'Brazookas brings the passion of Brazilian football to the Genesis. Experience local teams and updated rosters in this rare 16-bit South American sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brett-hull-hockey-95-usa', 'Genesis', 'Brett Hull Hockey ''95 (USA)', '1994', 'Sports', 'Electronic Arts', '2', 'Hockey Simulation', 'Professional ice hockey simulation with real-time stats and plays.', 'Lead your team to the Stanley Cup and win the championship.', 'A realistic hockey sim endorsed by legend Brett Hull.', 'Brett Hull Hockey ''95 offers fast-paced 16-bit action on the ice. Master the "Alumni" mode and legendary shots in this detailed Sega sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brian-lara-cricket-europe-june-1995', 'Genesis', 'Brian Lara Cricket (Europe) (June 1995)', '1995', 'Sports', 'Audiogenic', '2', 'Cricket Simulation', 'Professional cricket simulation featuring various international modes.', 'Score the most runs and bowl out the opposition to win.', 'The premier 16-bit cricket game for Sega Genesis.', 'Brian Lara Cricket (June 1995) delivers authentic batting and bowling mechanics. Play through World Cups and Test matches in this definitive sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brian-lara-cricket-europe-march-1995', 'Genesis', 'Brian Lara Cricket (Europe) (March 1995)', '1995', 'Sports', 'Audiogenic', '2', 'Cricket Simulation', 'Professional cricket simulation featuring various international modes.', 'Score the most runs and bowl out the opposition to win.', 'The earlier March 1995 release of the cricket hit.', 'Brian Lara Cricket (March 1995) delivers authentic batting and bowling mechanics. Play through World Cups and Test matches in this definitive sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brian-lara-cricket-96-europe-april-1996', 'Genesis', 'Brian Lara Cricket 96 (Europe) (April 1996)', '1996', 'Sports', 'Audiogenic', '2', 'Cricket Simulation', 'Professional cricket simulation with updated 1996 rosters.', 'Dominate the international cricket circuit and win the Cup.', 'The 1996 update to the successful Brian Lara series.', 'Brian Lara Cricket 96 features refined gameplay and updated player stats. Experience the most comprehensive cricket simulation available on the 16-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brian-lara-cricket-96-europe-march-1996', 'Genesis', 'Brian Lara Cricket 96 (Europe) (March 1996)', '1996', 'Sports', 'Audiogenic', '2', 'Cricket Simulation', 'Professional cricket simulation with updated 1996 rosters.', 'Dominate the international cricket circuit and win the Cup.', 'The March version of the 1996 cricket update.', 'Brian Lara Cricket 96 features refined gameplay and updated player stats. Experience the most comprehensive cricket simulation available on the 16-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('broken-knuckles', 'Genesis', 'Broken Knuckles', '2023', 'Action', 'Fan Hack', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring a modified Knuckles.', 'Battle through levels using a "glitched" or "broken" moveset.', 'A unique community modification starring Knuckles.', 'Broken Knuckles explores experimental gameplay within the Sonic engine. Test out new physics and combat styles in this creative 16-bit fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brutal---paws-of-fury-europe', 'Genesis', 'Brutal - Paws of Fury (Europe)', '1994', 'Fighting', 'GameTek', '2', 'Competitive', 'One-on-one fighting game featuring anthropomorphic animals.', 'Master your animal''s martial art to defeat the Dali Llama.', 'A colorful and personality-driven 16-bit fighter.', 'Brutal: Paws of Fury combines traditional fighting mechanics with a unique "learning" system. Choose your animal warrior and fight for supremacy on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brutal---paws-of-fury-usa', 'Genesis', 'Brutal - Paws of Fury (USA)', '1994', 'Fighting', 'GameTek', '2', 'Competitive', 'One-on-one fighting game featuring anthropomorphic animals.', 'Master your animal''s martial art to defeat the Dali Llama.', 'The North American version of the animal brawler.', 'Brutal: Paws of Fury combines traditional fighting mechanics with a unique "learning" system. Choose your animal warrior and fight for supremacy on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brutal-sonic', 'Genesis', 'Brutal Sonic', '2021', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with a more aggressive Sonic style.', 'Complete stages with enhanced speed and custom moves.', 'A modern rom-hack emphasizing "brutal" gameplay.', 'Brutal Sonic pushes the 16-bit engine to its limits. Experience faster physics and a more intense take on the classic Sega platforming formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubbanstix---a-strategy-adventure-usa', 'Genesis', 'Bubba''n''Stix - A Strategy Adventure (USA)', '1993', 'Puzzle-Adventure', 'Core Design', '2', 'Strategy', 'Side-scrolling puzzle-platformer using a sentient stick tool.', 'Use your stick to move objects, defeat enemies, and solve puzzles.', 'A highly creative and humorous strategy adventure.', 'Bubba''n''Stix features incredible hand-drawn animations. Use your trusty stick in clever ways to navigate an alien planet in this 16-bit hidden gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubbanstix-europe', 'Genesis', 'Bubba''n''Stix (Europe)', '1993', 'Puzzle-Adventure', 'Core Design', '2', 'Strategy', 'Side-scrolling puzzle-platformer using a sentient stick tool.', 'Use your stick to move objects, defeat enemies, and solve puzzles.', 'The European release of the quirky adventure.', 'Bubba''n''Stix features incredible hand-drawn animations. Use your trusty stick in clever ways to navigate an alien planet in this 16-bit hidden gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubbanstix-europe-beta', 'Genesis', 'Bubba''n''Stix (Europe) (Beta)', '1993', 'Puzzle-Adventure', 'Core Design', '2', 'Strategy', 'Side-scrolling puzzle-platformer using a sentient stick tool.', 'Use your stick to move objects, defeat enemies, and solve puzzles.', 'A beta development build of Bubba''n''Stix.', 'Get a glimpse of the puzzle mechanics in development with the Bubba''n''Stix Beta. A fascinating look at this unique 16-bit strategy-platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-and-squeak-usa', 'Genesis', 'Bubble and Squeak (USA)', '1994', 'Platformer', 'Audiogenic', '1', 'Action', 'Side-scrolling platformer with an "alien and monster" mechanic.', 'Cooperate with your pet Squeak to reach the end of the level.', 'A polished and vibrant 16-bit platforming game.', 'Bubble and Squeak offers fun co-op style mechanics where you must toss and ride your alien companion. Solve puzzles and enjoy high-quality Sega Genesis visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubsy-ii', 'Genesis', 'Bubsy II', '1994', 'Platformer', 'Accolade', '1', 'Action', 'Multi-level side-scrolling platformer with various mini-games.', 'Save the world''s music and artifacts from the Woolies.', 'The sequel to the original Bubsy adventure.', 'Bubsy II adds more variety with three different worlds and a host of new gadgets. Experience the "wit" and platforming of the world''s most talkative bobcat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubsy-in-claws-encounters-of-the-furred-kind', 'Genesis', 'Bubsy in Claws Encounters of the Furred Kind', '1993', 'Platformer', 'Accolade', '1', 'Action', 'High-speed side-scrolling platformer with gliding mechanics.', 'Stop the Woolies from stealing Earth''s supply of yarn.', 'The debut of the famous platforming mascot Bubsy.', 'Bubsy in Claws Encounters of the Furred Kind features huge levels and fast-paced 16-bit action. Use Bubsy''s glide ability to explore and collect yarn balls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buck-rogers---countdown-to-doomsday-usa-europe', 'Genesis', 'Buck Rogers - Countdown to Doomsday (USA, Europe)', '1990', 'Role-Playing', 'Sega', '1', 'Turn-Based RPG', 'Party-based tactical RPG with first-person space combat.', 'Lead a team of heroes to stop the NEO organization''s plot.', 'A deep sci-fi RPG based on the classic property.', 'Buck Rogers: Countdown to Doomsday offers a mix of strategy and role-playing. Explore the solar system and engage in tactical 16-bit ground and space combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('budokan---the-martial-spirit-europe', 'Genesis', 'Budokan - The Martial Spirit (Europe)', '1990', 'Fighting', 'Electronic Arts', '2', 'Competitive', 'Martial arts simulator featuring multiple disciplines.', 'Train in various styles to compete at the Budokan arena.', 'A realistic and respectful take on Japanese martial arts.', 'Budokan: The Martial Spirit focuses on timing and stamina. Master the Bo, Kendo, Karate, and Nunchaku in this technical 16-bit Sega simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('budokan---the-martial-spirit-usa', 'Genesis', 'Budokan - The Martial Spirit (USA)', '1990', 'Fighting', 'Electronic Arts', '2', 'Competitive', 'Martial arts simulator featuring multiple disciplines.', 'Train in various styles to compete at the Budokan arena.', 'The North American release of the martial arts sim.', 'Budokan: The Martial Spirit focuses on timing and stamina. Master the Bo, Kendo, Karate, and Nunchaku in this technical 16-bit Sega simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bugs-bunny-in-double-trouble-usa', 'Genesis', 'Bugs Bunny in Double Trouble (USA)', '1991', 'Platformer', 'Konami', '1', 'Action', 'Multi-layered side-scrolling platformer with cartoon physics.', 'Travel through the "portable" TV world to defeat Yosemite Sam.', 'A Looney Tunes adventure featuring Bugs Bunny.', 'Bugs Bunny in Double Trouble brings the humor of the cartoons to life. Navigate through vibrant 16-bit levels based on classic episodes in this fun Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bulls-versus-blazers-and-the-nba-playoffs-usa-europe', 'Genesis', 'Bulls Versus Blazers and the NBA Playoffs (USA, Europe)', '1992', 'Sports', 'Electronic Arts', '4', 'Basketball Simulation', 'Professional basketball simulation with real NBA playoffs.', 'Win the NBA title by mastering the hardwood and the "star" players.', 'The 1993 entry in EA''s legendary basketball series.', 'Bulls Versus Blazers features the signature moves of NBA greats. Experience the definitive 16-bit basketball experience with real teams and deep playoff modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bulls-vs-lakers-and-the-nba-playoffs-usa-europe', 'Genesis', 'Bulls Vs Lakers and the NBA Playoffs (USA, Europe)', '1991', 'Sports', 'Electronic Arts', '4', 'Basketball Simulation', 'Professional basketball simulation featuring the 1991 playoffs.', 'Lead your team to victory in the NBA finals.', 'The game that started the "versus" NBA series on Sega.', 'Bulls Vs Lakers is a pioneer of 16-bit sports gaming. Experience the legendary rivalry and realistic basketball simulation that defined the early Sega Genesis era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('burning-force-europe', 'Genesis', 'Burning Force (Europe)', '1989', 'Shooter', 'Sega', '1', 'Arcade', 'Pseudo-3D hoverbike shooter with scaling graphics.', 'Blast through waves of enemies and bosses to reach the goal.', 'A high-speed arcade port from Namco.', 'Burning Force delivers fast-paced 16-bit action. Pilot your hoverbike through futuristic landscapes in this visually impressive "Into-the-screen" shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('burning-force-japan', 'Genesis', 'Burning Force (Japan)', '1989', 'Shooter', 'Sega', '1', 'Arcade', 'Pseudo-3D hoverbike shooter with scaling graphics.', 'Blast through waves of enemies and bosses to reach the goal.', 'The Japanese Mega Drive version of Namco''s shooter.', 'Burning Force delivers fast-paced 16-bit action. Pilot your hoverbike through futuristic landscapes in this visually impressive "Into-the-screen" shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('burning-force-usa', 'Genesis', 'Burning Force (USA)', '1989', 'Shooter', 'Sega', '1', 'Arcade', 'Pseudo-3D hoverbike shooter with scaling graphics.', 'Blast through waves of enemies and bosses to reach the goal.', 'The North American release of the hoverbike shooter.', 'Burning Force delivers fast-paced 16-bit action. Pilot your hoverbike through futuristic landscapes in this visually impressive "Into-the-screen" shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('c2-sonic-1', 'Genesis', 'C2 Sonic 1', '2022', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with custom "C2" engine tweaks.', 'Complete Sonic 1 stages with enhanced physics and visuals.', 'A community modification for the first Sonic game.', 'C2 Sonic 1 offers a fresh take on the 16-bit classic. Experience refined movement and subtle gameplay improvements in this high-quality Sega fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('c2-sonic-2', 'Genesis', 'C2 Sonic 2', '2022', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with custom "C2" engine tweaks.', 'Complete Sonic 2 stages with enhanced physics and visuals.', 'A community modification for the iconic Sonic 2.', 'C2 Sonic 2 brings modern polish to the legendary sequel. Enjoy the high-speed loops and zones with optimized 16-bit performance and gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cadash-usa-asia', 'Genesis', 'Cadash (USA, Asia)', '1992', 'Action', 'Taito', '2', 'Arcade', 'Side-scrolling action-RPG with multiple character classes.', 'Explore the world of Cadash to rescue the princess and stop Balrog.', 'A rare and deep arcade-to-home RPG port.', 'Cadash combines platforming with RPG elements like shops and leveling. Choose your class and embark on a 16-bit quest in this unique Taito classic for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('caesar-no-yabou-japan', 'Genesis', 'Caesar no Yabou (Japan)', '1990', 'Strategy', 'Koei', '1', 'Grand Strategy', 'Historical strategy and simulation set in ancient Rome.', 'Manage the empire''s resources and lead armies to glory.', 'A deep Japanese strategy title from Koei.', 'Caesar no Yabou offers a complex simulation of Roman life. Balance politics, economics, and warfare in this massive 16-bit historical epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('caesar-no-yabou-ii-japan', 'Genesis', 'Caesar no Yabou II (Japan)', '1992', 'Strategy', 'Koei', '1', 'Grand Strategy', 'Expanded historical strategy with more depth and features.', 'Expand the borders of Rome and maintain domestic peace.', 'The refined sequel to the Roman strategy sim.', 'Caesar no Yabou II brings even more detail to the ancient world. Master the art of leadership in this comprehensive 16-bit Roman simulation for Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('caesars-palace-usa', 'Genesis', 'Caesars Palace (USA)', '1993', 'Casino', 'Microsmiths', '1', 'Gambling', 'Casino simulation featuring various gambling mini-games.', 'Accumulate wealth by winning at blackjack, slots, and roulette.', 'A realistic casino experience for the Sega Genesis.', 'Step into Caesars Palace and test your luck. Experience the thrill of high-stakes gambling with detailed 16-bit recreations of classic casino floor games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cal-ripken-jr-baseball-usa', 'Genesis', 'Cal Ripken Jr. Baseball (USA)', '1992', 'Sports', 'Mindscape', '2', 'Baseball Simulation', 'Sports simulation with realistic baseball mechanics and stats.', 'Lead your team to victory in a full professional season.', 'A solid baseball title endorsed by the legendary Cal Ripken Jr.', 'Cal Ripken Jr. Baseball offers deep gameplay and strategic management. Master the diamond with precise pitching and batting mechanics in this 16-bit sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('caliber-50-usa', 'Genesis', 'Caliber .50 (USA)', '1991', 'Shooter', 'Infogrames', '1', 'Run and Gun', 'Overhead multi-directional shoot ''em up with scrolling action.', 'Fight through enemy lines to rescue a captured pilot.', 'An intense arcade-to-home port of the vertical shooter.', 'Caliber .50 brings explosive arcade action to the Genesis. Maneuver through hostile territory and upgrade your firepower in this high-octane 16-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('california-games-usa-europe', 'Genesis', 'California Games (USA, Europe)', '1991', 'Sports', 'Epyx', '4', 'Multi-Sport Arcade', 'Multi-event sports simulation featuring summer activities.', 'Earn the highest score in events like surfing and skating.', 'A collection of radical California-themed sports.', 'Experience the ultimate summer in California Games. Master the half-pipe, footbag, and surfing in this iconic 16-bit multi-event sports challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cannon-fodder-europe', 'Genesis', 'Cannon Fodder (Europe)', '1993', 'Action', 'Sensible Software', '2', 'Run and Gun', 'Squad-based tactical action with overhead combat.', 'Lead your soldiers through dangerous missions with minimal casualties.', 'A dark, humorous, and challenging military strategy game.', 'War has never been so much fun! Command your squad in Cannon Fodder, combining fast-paced shooting with strategic unit management on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-america-and-the-avengers-europe', 'Genesis', 'Captain America and the Avengers (Europe)', '1991', 'Action', 'Data East', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring four Marvel heroes.', 'Defeat the Red Skull and his army of supervillains.', 'A classic arcade port starring Captain America and the Avengers.', 'Team up in Captain America and the Avengers. Use unique hero abilities and projectile attacks to stop a global threat in this premier 16-bit Marvel brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-america-and-the-avengers-usa', 'Genesis', 'Captain America and the Avengers (USA)', '1991', 'Action', 'Data East', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring four Marvel heroes.', 'Defeat the Red Skull and his army of supervillains.', 'The North American release of the Marvel arcade hit.', 'Team up in Captain America and the Avengers. Use unique hero abilities and projectile attacks to stop a global threat in this premier 16-bit Marvel brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-america-and-the-avengers-usa-beta', 'Genesis', 'Captain America and the Avengers (USA) (Beta)', '1991', 'Action', 'Data East', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring four Marvel heroes.', 'Defeat the Red Skull and his army of supervillains.', 'A beta development version of the Avengers arcade port.', 'See the development of a superhero classic with the Captain America and the Avengers Beta. Experience the core combat of this 16-bit Marvel title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-planet-and-the-planeteers-europe', 'Genesis', 'Captain Planet and the Planeteers (Europe)', '1991', 'Action', 'Novotrade', '1', 'Platformer', 'Side-scrolling platformer based on the environmental cartoon.', 'Use elemental powers to stop polluters and save the Earth.', 'An eco-friendly action game starring the Planeteers.', 'The power is yours! Join Captain Planet and the Planeteers to clean up the world and defeat eco-villains in this colorful 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-planet-and-the-planeteers-usa', 'Genesis', 'Captain Planet and the Planeteers (USA)', '1991', 'Action', 'Novotrade', '1', 'Platformer', 'Side-scrolling platformer based on the environmental cartoon.', 'Use elemental powers to stop polluters and save the Earth.', 'The North American version of the Captain Planet game.', 'The power is yours! Join Captain Planet and the Planeteers to clean up the world and defeat eco-villains in this colorful 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castle-of-illusion---fushigi-no-oshiro-daibouken-japan', 'Genesis', 'Castle of Illusion - Fushigi no Oshiro Daibouken (Japan)', '1990', 'Platformer', 'Sega', '1', 'Action', 'Side-scrolling platformer with creative level design.', 'Collect the seven gems to rescue Minnie from the witch Mizrabel.', 'The Japanese version of Mickey''s legendary adventure.', 'Castle of Illusion (Fushigi no Oshiro Daibouken) is a 16-bit masterpiece. Experience magical worlds and fluid animation in this quintessential Sega platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castle-of-illusion-starring-mickey-mouse-usa-europe', 'Genesis', 'Castle of Illusion Starring Mickey Mouse (USA, Europe)', '1990', 'Platformer', 'Sega', '1', 'Action', 'Side-scrolling platformer with creative level design.', 'Collect the seven gems to rescue Minnie from the witch Mizrabel.', 'The definitive Disney platformer for the Sega Genesis.', 'Journey through enchanted lands in Castle of Illusion Starring Mickey Mouse. A landmark title featuring incredible 16-bit visuals and timeless gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---bloodlines-usa', 'Genesis', 'Castlevania - Bloodlines (USA)', '1994', 'Action', 'Konami', '1', 'Action Platformer', 'Side-scrolling action with whip combat and multiple heroes.', 'Travel through Europe to prevent the resurrection of Dracula.', 'The exclusive and gritty Castlevania entry for Genesis.', 'Castlevania: Bloodlines (The New Generation) offers intense gothic action. Choose between John Morris or Eric Lecarde in this high-quality 16-bit horror classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---the-new-generation-europe', 'Genesis', 'Castlevania - The New Generation (Europe)', '1994', 'Action', 'Konami', '1', 'Action Platformer', 'Side-scrolling action with whip combat and multiple heroes.', 'Travel through Europe to prevent the resurrection of Dracula.', 'The European localized version of Castlevania: Bloodlines.', 'Castlevania: The New Generation brings the legendary vampire-hunting franchise to the Mega Drive with unique levels and incredible 16-bit music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---the-new-generation-europe-beta', 'Genesis', 'Castlevania - The New Generation (Europe) (Beta)', '1994', 'Action', 'Konami', '1', 'Action Platformer', 'Side-scrolling action with whip combat and multiple heroes.', 'Travel through Europe to prevent the resurrection of Dracula.', 'A beta version of the European Castlevania release.', 'Explore the early stages of a gothic masterpiece with the Castlevania: The New Generation Beta. A rare look at the development of this 16-bit epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania-bloodlines-enhanced-colors', 'Genesis', 'Castlevania Bloodlines Enhanced Colors', '2021', 'Action', 'Fan Hack', '1', 'Action Platformer', 'Side-scrolling action with whip combat and multiple heroes.', 'Travel through Europe to prevent the resurrection of Dracula.', 'A fan-made color enhancement for Castlevania: Bloodlines.', 'Experience the darkness with new depth in Castlevania Bloodlines Enhanced Colors. This mod polishes the 16-bit palette for a more vibrant gothic atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('centurion---defender-of-rome-usa-europe', 'Genesis', 'Centurion - Defender of Rome (USA, Europe)', '1990', 'Strategy', 'Bits Studios', '1', 'Turn-Based', 'Grand strategy and real-time tactical combat in Ancient Rome.', 'Conquer the known world and rise to the rank of Emperor.', 'A deep historical strategy sim with cinematic elements.', 'Defend the empire in Centurion: Defender of Rome. Manage provinces, engage in naval battles, and command legions in this ambitious 16-bit strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chakan-usa-europe', 'Genesis', 'Chakan (USA, Europe)', '1992', 'Action', 'Extended Play', '1', 'Action Platformer', 'Side-scrolling action-platformer with a dark fantasy setting.', 'Defeat the dark gods to find ultimate rest for your soul.', 'A notoriously difficult and atmospheric action game.', 'Chakan: The Forever Man offers a haunting 16-bit experience. Master elemental alchemy and swordplay to survive nightmarish realms in this Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chameleon-kid-japan', 'Genesis', 'Chameleon Kid (Japan)', '1991', 'Platformer', 'Sega', '1', 'Action', 'Side-scrolling platformer featuring character transformation.', 'Use different masks to gain unique powers and solve puzzles.', 'The Japanese version of the classic Kid Chameleon.', 'Chameleon Kid (Kid Chameleon) features over 100 levels of platforming. Transform into a samurai, a knight, or a fly in this massive 16-bit Sega adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('champions-world-class-soccer-world-enfrdees', 'Genesis', 'Champions World Class Soccer (World) (En,Fr,De,Es)', '1994', 'Sports', 'Sensible Software', '4', 'Soccer Simulation', 'Soccer simulation with international teams and tournament modes.', 'Lead your nation to victory in the World Cup.', 'A global soccer title with multiple language options.', 'Champions World Class Soccer offers fast-paced 16-bit football. Master the pitch with international rosters and intuitive controls on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('championship-bowling-usa', 'Genesis', 'Championship Bowling (USA)', '1991', 'Sports', 'Soft Vision', '4', 'Bowling Arcade', 'Ten-pin bowling simulation with multiple lanes and characters.', 'Achieve the perfect score of 300 across various tournaments.', 'A fun and realistic bowling game for the Genesis.', 'Championship Bowling brings the alley home. Master spin and power to earn strikes in this polished and colorful 16-bit sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('championship-pool-usa', 'Genesis', 'Championship Pool (USA)', '1991', 'Sports', 'Bitmasters', '2', 'Pool Simulation', 'Billiards and pool simulation featuring multiple game types.', 'Clear the table in games like 8-ball, 9-ball, and snooker.', 'A comprehensive pool simulation for the 16-bit era.', 'Chalk up and compete in Championship Pool. Featuring realistic physics and tournament modes, it’s the definitive billiards game for the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('championship-pro-am-usa', 'Genesis', 'Championship Pro-Am (USA)', '1992', 'Racing', 'Electronic Arts', '2', 'Off-Road Racing', 'Isometric racing with combat elements and vehicle upgrades.', 'Outrun and outgun opponents to win the racing championship.', 'An isometric racer that influenced the RC Pro-Am series.', 'Championship Pro-Am delivers addictive 16-bit racing action. Collect power-ups and avoid hazards in this fast-paced and competitive Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chaoji-dafuweng-china-unl', 'Genesis', 'Chaoji Dafuweng (China) (Unl)', '1993', 'Board Game', 'Unlicensed', '4', 'Tabletop', 'Digital board game simulation with a focus on property trading.', 'Accumulate the most wealth and bankrupt your opponents.', 'An unlicensed Chinese "Monopoly" style game.', 'Chaoji Dafuweng brings classic board game strategy to the 16-bit era. Compete with friends or AI in this rare and interesting unlicensed Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chaos-engine-2-the-europe-proto', 'Genesis', 'Chaos Engine 2, The (Europe) (Proto)', '1994', 'Action', 'The Bitmap Brothers', '2', 'Run and Gun', 'Split-screen tactical action and puzzle-solving for two players.', 'Outmaneuver your rival to reach the exit first.', 'The unreleased prototype sequel to The Chaos Engine.', 'The Chaos Engine 2 features unique competitive gameplay. Experience early 16-bit tactical racing and combat in this rare steampunk prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chaos-engine-the-europe', 'Genesis', 'Chaos Engine, The (Europe)', '1993', 'Action', 'The Bitmap Brothers', '2', 'Run and Gun', 'Overhead run-and-gun shooter with a steampunk aesthetic.', 'Battle through four worlds to destroy the ultimate machine.', 'A masterpiece of 16-bit action and atmosphere (Soldiers of Fortune).', 'The Chaos Engine offers intense co-op shooting and character upgrades. Master the steampunk environments and defeat the mechanical menace in this Bitmap Brothers classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chase-hq-ii-usa', 'Genesis', 'Chase H.Q. II (USA)', '1992', 'Action', 'Taito', '1', 'Arcade', 'High-speed arcade racing and pursuit simulation.', 'Chase down and ram criminal vehicles within the time limit.', 'The high-octane sequel to the arcade legend Chase H.Q.', 'Chase H.Q. II puts you in the driver''s seat of an elite police unit. Experience blistering 16-bit speed as you bring justice to the streets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chavez-ii-usa', 'Genesis', 'Chavez II (USA)', '1993', 'Fighting', 'Razorsoft', '2', 'Competitive', 'One-on-one boxing simulation with a focus on Mexican fighters.', 'Rise through the ranks to win the world championship belt.', 'The sequel to the localized Prizefighter boxing game.', 'Chavez II offers gritty and realistic 16-bit boxing action. Master the ring and knock out the competition in this detailed sports simulation for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cheese-cat-astrophe-starring-speedy-gonzales-europe', 'Genesis', 'Cheese Cat-Astrophe Starring Speedy Gonzales (Europe)', '1995', 'Platformer', 'Creative Materials', '1', 'Action', 'Side-scrolling platformer featuring the fastest mouse in Mexico.', 'Rescue your friends from the claws of Sylvester the Cat.', 'A vibrant and fast-paced Looney Tunes adventure.', 'Cheese Cat-Astrophe Starring Speedy Gonzales features beautiful 16-bit animation. Use your incredible speed to outrun traps and save the day in this fun Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chelnov-japan', 'Genesis', 'Chelnov (Japan)', '1988', 'Shooter', 'Data East', '2', 'Arcade', 'Side-scrolling runner and shooter with forced-scrolling action.', 'Escape from enemy forces while blasting through alien hordes.', 'The original Japanese release of Atomic Runner.', 'Chelnov is a unique and challenging arcade port for the Mega Drive. Master the constant movement and intense shooting in this cult 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chester-cheetah---too-cool-to-fool-usa', 'Genesis', 'Chester Cheetah - Too Cool to Fool (USA)', '1992', 'Platformer', 'Kaneko', '1', 'Action', 'Side-scrolling platformer starring the Cheetos mascot.', 'Find the hidden map pieces to escape the Four Corners Zoo.', 'A stylish and personality-driven 16-bit platformer.', 'Chester Cheetah: Too Cool to Fool brings the snack-food icon to life. Explore cool environments and use your sunglasses to find secrets in this fun Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chester-cheetah---wild-wild-quest-usa', 'Genesis', 'Chester Cheetah - Wild Wild Quest (USA)', '1993', 'Platformer', 'Kaneko', '1', 'Action', 'Side-scrolling platformer with vehicle stages and exploration.', 'Travel across America to find the stolen snack stash.', 'The adventurous sequel to Too Cool to Fool.', 'Chester Cheetah: Wild Wild Quest offers more variety and faster action. Race across the 16-bit landscape and reclaim the snacks in this colorful Sega adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chi-chis-pro-challenge-golf-usa', 'Genesis', 'Chi Chi''s Pro Challenge Golf (USA)', '1993', 'Sports', 'TOSE', '1', 'Golf Simulation', 'Realistic golf simulation with various clubs and wind mechanics.', 'Win professional tournaments by completing courses with the lowest score.', 'A professional golf simulator endorsed by Chi Chi Rodriguez.', 'Experience precision golfing in Chi Chi''s Pro Challenge Golf. Master 16-bit swing mechanics and terrain strategy in this detailed Sega Genesis sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chibi-maruko-chan---wakuwaku-shopping-japan', 'Genesis', 'Chibi Maruko-chan - Wakuwaku Shopping (Japan)', '1992', 'Adventure', 'Sims', '1', 'Life Simulation', 'Board game simulation featuring mini-games and shopping themes.', 'Navigate the board and collect items to win the shopping challenge.', 'A charming Japanese board game based on the popular anime.', 'Chibi Maruko-chan: Wakuwaku Shopping brings the beloved anime to the Mega Drive. Enjoy fun 16-bit mini-games and colorful graphics in this family-friendly title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chiki-chiki-boys-japan', 'Genesis', 'Chiki Chiki Boys (Japan)', '1990', 'Action', 'Capcom', '2', 'Arcade', 'Side-scrolling action platformer with two-player cooperative play.', 'Journey through a fantasy world to recover the Dragon Blue Eyes.', 'A high-quality arcade port from Capcom.', 'Chiki Chiki Boys (Mega Twins) features vibrant 16-bit art and tight combat. Explore a whimsical fantasy world and defeat massive bosses in this Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chiki-chiki-boys-usa-europe', 'Genesis', 'Chiki Chiki Boys (USA, Europe)', '1990', 'Action', 'Capcom', '2', 'Arcade', 'Side-scrolling action platformer with two-player cooperative play.', 'Journey through a fantasy world to recover the Dragon Blue Eyes.', 'The Western release of the Capcom arcade hit.', 'Chiki Chiki Boys (Mega Twins) features vibrant 16-bit art and tight combat. Explore a whimsical fantasy world and defeat massive bosses in this Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chip-n-dale-rescue-rangers-unl', 'Genesis', 'Chip ''n Dale Rescue Rangers (Unl)', '1990', 'Platformer', 'Unlicensed', '2', 'Action', 'Side-scrolling platformer based on the Disney characters.', 'Help Chip and Dale defeat Fat Cat and save their friends.', 'An unlicensed 16-bit port of the famous Disney game.', 'Experience Chip ''n Dale Rescue Rangers on the Sega Genesis. A rare unlicensed title that brings the 8-bit platforming classic to 16-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chip-n-dale-rescue-rangers-2-unl', 'Genesis', 'Chip ''n Dale Rescue Rangers 2 (Unl)', '1993', 'Platformer', 'Unlicensed', '2', 'Action', 'Side-scrolling platformer based on the Disney characters.', 'Stop Fat Cat''s latest evil scheme across various urban levels.', 'An unlicensed 16-bit port of the sequel.', 'Chip ''n Dale Rescue Rangers 2 brings more 16-bit action to the Genesis. Navigate dangerous levels and use teamwork in this rare unofficial port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-kyuukai-miracle-nine-japan', 'Genesis', 'Chou Kyuukai Miracle Nine (Japan)', '1991', 'Sports', 'Sega', '2', 'Baseball Arcade', 'Professional baseball simulation with an arcade style.', 'Lead your baseball team to the league championship.', 'A polished and energetic Japanese baseball game.', 'Chou Kyuukai Miracle Nine offers fast-paced baseball action on the Mega Drive. Enjoy smooth animations and deep 16-bit sports strategy in this Japanese hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-touryuu-retsuden-dino-land-japan', 'Genesis', 'Chou Touryuu Retsuden Dino Land (Japan)', '1990', 'Action', 'Jaleco', '2', 'Arcade', 'Pinball simulation featuring prehistoric and dinosaur themes.', 'Achieve high scores by hitting targets on various dinosaur tables.', 'A unique dinosaur-themed pinball game for Mega Drive.', 'Chou Touryuu Retsuden Dino Land combines classic pinball physics with prehistoric flair. Battle bosses and clear tables in this creative 16-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrome-metal-sonic-the-hedgehog', 'Genesis', 'Chrome Metal Sonic The Hedgehog', '2022', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with a custom "Chrome" aesthetic.', 'Complete Sonic 1 levels using a metallic, reflective Sonic.', 'A visual modification for the original Sonic game.', 'Chrome Metal Sonic The Hedgehog offers a sleek new look for the Blue Blur. Experience the 16-bit classic with updated chrome-style sprites and effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrome-metal-sonic-the-hedgehog-2', 'Genesis', 'Chrome Metal Sonic The Hedgehog 2', '2023', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with a custom "Chrome" aesthetic.', 'Complete Sonic 2 levels using a metallic, reflective Sonic.', 'A visual modification for the iconic Sonic sequel.', 'Chrome Metal Sonic The Hedgehog 2 brings a futuristic shine to the high-speed loops of Sonic 2. Enjoy the 16-bit legend with a unique metallic polish.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-rock-europe', 'Genesis', 'Chuck Rock (Europe)', '1991', 'Platformer', 'Core Design', '1', 'Action', 'Side-scrolling platformer using "belly-butt" attacks and lifting rocks.', 'Rescue your wife, Ophelia, from the Gary Grasper gang.', 'A pre-historic platforming adventure featuring Chuck.', 'Chuck Rock features unique physics and humor. Use your prehistoric strength to navigate vibrant 16-bit environments and defeat dinosaur enemies on Sega.');
