INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clackers', 'Genesis', 'Clackers', '1990', 'Puzzle', 'Taito', '2', 'Arcade', 'Puzzle-style logic game based on timing and movement.', 'Maneuver pieces to match specific patterns or clear objectives.', 'A rare and simple puzzle title for the Genesis.', 'Clackers offers addictive 16-bit logic challenges. Master the movement of the pieces to clear stages in this unique and minimalist Sega puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clackers---nocombi', 'Genesis', 'Clackers - NoCombi', '1990', 'Puzzle', 'Taito', '2', 'Arcade', 'Puzzle-style logic game based on timing and movement.', 'Maneuver pieces to match specific patterns or clear objectives.', 'A specialized version of the puzzle game Clackers.', 'Clackers - NoCombi features refined puzzle mechanics for fans of the original. Test your 16-bit logic skills in this interesting Sega variant.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('classic-collection-europe', 'Genesis', 'Classic Collection (Europe)', '1995', 'Compilation', 'Sega', '2', 'Arcade', 'Compilation of several classic Sega Genesis titles.', 'Enjoy multiple games across different genres in one place.', 'A multi-game cartridge featuring Sega''s greatest hits.', 'Classic Collection is the perfect way to experience the best of Sega. Featuring titles like Alex Kidd and Altered Beast, it''s a 16-bit gaming essential.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clay-fighter-usa', 'Genesis', 'Clay Fighter (USA)', '1993', 'Fighting', 'Visual Concepts', '2', 'Competitive', 'One-on-one fighting game featuring stop-motion clay characters.', 'Defeat a cast of bizarre clay warriors to become the champion.', 'A humorous and unique fighting game with claymation art.', 'Clay Fighter brings "Cleytality" to the Sega Genesis. Experience quirky characters and funny combat in this visually distinct 16-bit fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cliffhanger-europe', 'Genesis', 'Cliffhanger (Europe)', '1993', 'Action', 'Gray Matter', '1', 'Action Platformer', 'Side-scrolling action based on the survival movie.', 'Climb mountains and fight off criminals to recover stolen money.', 'A cinematic action game based on the Sylvester Stallone film.', 'Cliffhanger features intense platforming and combat. Brave the 16-bit snow and vertical peaks to stop the bad guys in this movie tie-in for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cliffhanger-usa', 'Genesis', 'Cliffhanger (USA)', '1993', 'Action', 'Gray Matter', '1', 'Action Platformer', 'Side-scrolling action based on the survival movie.', 'Climb mountains and fight off criminals to recover stolen money.', 'The North American release of the survival action game.', 'Cliffhanger features intense platforming and combat. Brave the 16-bit snow and vertical peaks to stop the bad guys in this movie tie-in for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clue-usa', 'Genesis', 'Clue (USA)', '1992', 'Board Game', 'Parker Brothers', '4', 'Tabletop', 'Digital board game based on the classic mystery franchise.', 'Use logic and deduction to solve a murder mystery.', 'A faithful 16-bit adaptation of the Clue board game.', 'Solve the mystery in Clue on the Sega Genesis. Use your detective skills to find the killer, the weapon, and the room in this classic digital 16-bit board game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('coach-k-college-basketball-usa', 'Genesis', 'Coach K College Basketball (USA)', '1992', 'Sports', 'Gray Matter', '2', 'Basketball Simulation', 'Professional college basketball simulation with deep tactical plays.', 'Lead your college team to the NCAA championship victory.', 'A highly detailed basketball sim using the EA Sports engine.', 'Coach K College Basketball features the atmosphere of the campus game. Master the 16-bit hardwood with deep playbooks and authentic college strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('college-football-usa-96-usa', 'Genesis', 'College Football USA 96 (USA)', '1995', 'Sports', 'High Voltage', '2', 'Football Simulation', 'American football simulation with 1996 college rosters.', 'Win the national championship bowl by mastering the gridiron.', 'The 1996 update to the popular college football series.', 'College Football USA 96 brings the intensity of the college game to Sega. Experience updated 16-bit rosters and refined gameplay in this sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('college-football-usa-97-usa', 'Genesis', 'College Football USA 97 (USA)', '1996', 'Sports', 'High Voltage', '2', 'Football Simulation', 'American football simulation with 1997 college rosters.', 'Win the national championship bowl by mastering the gridiron.', 'The 1997 update to the popular college football series.', 'College Football USA 97 features even more teams and deeper stats. Lead your favorite university to glory in this definitive 16-bit football sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('college-footballs-national-championship-usa', 'Genesis', 'College Football''s National Championship (USA)', '1994', 'Sports', 'High Voltage', '2', 'Football Simulation', 'American football simulation focusing on top-tier college programs.', 'Compete through a full season to win the National Championship.', 'A dedicated college football game for the Sega Genesis.', 'College Football''s National Championship offers realistic 16-bit football. Master the playbook and dominate the field in this classic Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('college-footballs-national-championship-ii-usa', 'Genesis', 'College Football''s National Championship II (USA)', '1995', 'Sports', 'High Voltage', '2', 'Football Simulation', 'American football simulation with expanded teams and features.', 'Compete through a full season to win the National Championship.', 'The sequel to the successful college football title.', 'College Football''s National Championship II features improved graphics and AI. Experience the peak of 16-bit college football on your Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('college-slam-usa', 'Genesis', 'College Slam (USA)', '1994', 'Sports', 'Iguana Entertainment', '4', 'Basketball Arcade', 'Arcade-style 2-on-2 basketball with power-ups and dunks.', 'Outscore opponents in a high-energy college basketball arena.', 'A college-themed version of the high-flying NBA Jam style.', 'College Slam brings the "boomshakalaka" to the university level. Enjoy fast-paced 16-bit basketball with massive dunks and high-energy gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('columns-world', 'Genesis', 'Columns (World)', '1990', 'Puzzle', 'Sega', '2', 'Arcade', 'Tile-matching puzzle game with falling jewels.', 'Arrange falling columns of jewels to match three or more.', 'Sega''s iconic answer to the falling-block puzzle genre.', 'Columns is a 16-bit puzzle masterpiece. Experience addictive jewel-matching gameplay and a relaxing soundtrack in this quintessential Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('columns-world-v11', 'Genesis', 'Columns (World) (v1.1)', '1990', 'Puzzle', 'Sega', '2', 'Arcade', 'Tile-matching puzzle game with falling jewels.', 'Arrange falling columns of jewels to match three or more.', 'An updated revision (v1.1) of the puzzle classic.', 'Columns is a 16-bit puzzle masterpiece. Experience addictive jewel-matching gameplay and a relaxing soundtrack in this quintessential Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('columns-iii---revenge-of-columns-usa', 'Genesis', 'Columns III - Revenge of Columns (USA)', '1993', 'Puzzle', 'Sega', '2', 'Arcade', 'Tile-matching puzzle with a focus on head-to-head competition.', 'Defeat opponents in a magical pyramid by clearing columns.', 'The competitive third entry in the Columns series.', 'Columns III: Revenge of Columns shifts the focus to intense multiplayer and AI battles. Master the "flash" gems and out-maneuver your rivals in this deep 16-bit puzzle sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('columns-iii---taiketsu!-columns-world-japan', 'Genesis', 'Columns III - Taiketsu! Columns World (Japan)', '1993', 'Puzzle', 'Sega', '2', 'Arcade', 'Tile-matching puzzle with a focus on head-to-head competition.', 'Defeat opponents in a magical pyramid by clearing columns.', 'The original Japanese release of Columns III.', 'Columns III: Taiketsu! Columns World brings competitive jewel-matching to the Mega Drive. Features a whimsical story mode and robust 2-player 16-bit puzzle action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('combat-cars-usa-europe', 'Genesis', 'Combat Cars (USA, Europe)', '1994', 'Racing', 'Psygnosis', '2', 'Arcade', 'Top-down combat racing with various weapon power-ups.', 'Win high-speed races by out-driving and destroying rivals.', 'A gritty, combat-heavy top-down racer.', 'Combat Cars delivers fast-paced 16-bit vehicular warfare. Choose your driver and use unique gadgets to cross the finish line first in this intense Sega Genesis racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('comix-zone-europe', 'Genesis', 'Comix Zone (Europe)', '1995', 'Action', 'Sega Technical Institute', '1', 'Comic-Style Beat ''em Up', 'Side-scrolling beat ''em up inside the panels of a comic book.', 'Defeat the mutant Mortus and escape your own creation.', 'A legendary technical marvel with hand-drawn art.', 'Comix Zone is one of the most stylish games on the Genesis. Fight across comic panels, tear through pages, and enjoy incredible 16-bit animation and sound.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('comix-zone-japan', 'Genesis', 'Comix Zone (Japan)', '1995', 'Action', 'Sega Technical Institute', '1', 'Comic-Style Beat ''em Up', 'Side-scrolling beat ''em up inside the panels of a comic book.', 'Defeat the mutant Mortus and escape your own creation.', 'The Japanese Mega Drive release of the comic brawler.', 'Comix Zone is a visually stunning action masterpiece. Experience the unique "living comic" aesthetic and challenging 16-bit combat on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('comix-zone-usa', 'Genesis', 'Comix Zone (USA)', '1995', 'Action', 'Sega Technical Institute', '1', 'Comic-Style Beat ''em Up', 'Side-scrolling beat ''em up inside the panels of a comic book.', 'Defeat the mutant Mortus and escape your own creation.', 'The North American release of the iconic Comix Zone.', 'Comix Zone is one of the most stylish games on the Genesis. Fight across comic panels, tear through pages, and enjoy incredible 16-bit animation and sound.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('comix-zone-usa-beta', 'Genesis', 'Comix Zone (USA) (Beta)', '1995', 'Action', 'Sega Technical Institute', '1', 'Comic-Style Beat ''em Up', 'Side-scrolling beat ''em up inside the panels of a comic book.', 'Defeat the mutant Mortus and escape your own creation.', 'A beta development build of the action classic.', 'Peek behind the ink with the Comix Zone Beta. Discover early level layouts and gameplay tweaks for this 16-bit Sega technical showcase.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('congo-proto', 'Genesis', 'Congo (Proto)', '1995', 'Action', 'Millennium Interactive', '1', 'Adventure', 'Side-scrolling platformer based on the movie Congo.', 'Navigate the jungle and escape the deadly grey apes.', 'An unreleased prototype movie tie-in.', 'Congo is a rare piece of Sega history. Experience the platforming and action of this unreleased 16-bit cinematic adaptation on the Genesis hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contra---hard-corps-usa-korea-hack-by-mijet-v20080924-enhanced-editon', 'Genesis', 'Contra - Hard Corps (USA, Korea) [Hack by MIJET v20080924] (Enhanced Editon)', '1994', 'Action', 'Konami', '2', 'Run and Gun', 'Run-and-gun action with multiple paths and characters.', 'Stop a terrorist robot uprising and save the world.', 'An enhanced fan-mod with bug fixes and balance.', 'Contra: Hard Corps (Enhanced) provides the ultimate 16-bit shooting experience. Tackle massive bosses and multiple endings with refined gameplay on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contra---hard-corps-usa', 'Genesis', 'Contra - Hard Corps (USA)', '1994', 'Action', 'Konami', '2', 'Run and Gun', 'Run-and-gun action with high-intensity boss battles.', 'Stop a terrorist robot uprising and save the world.', 'The explosive and challenging Contra debut on Genesis.', 'Contra: Hard Corps is a masterpiece of 16-bit action. Choose from four unique characters and blast through some of the most impressive bosses on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contra---the-hard-corps-japan', 'Genesis', 'Contra - The Hard Corps (Japan)', '1994', 'Action', 'Konami', '2', 'Run and Gun', 'Run-and-gun action with high-intensity boss battles.', 'Stop a terrorist robot uprising and save the world.', 'The Japanese version (featuring a life bar).', 'Contra: The Hard Corps is known for its incredible difficulty and scale. Unlike the Western version, this Japanese release includes a life bar for more accessible 16-bit action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contra-hard-corps-hit-points-restoration-hack', 'Genesis', 'Contra Hard Corps Hit Points Restoration Hack', '2021', 'Action', 'Fan Hack', '2', 'Run and Gun', 'Run-and-gun action with high-intensity boss battles.', 'Stop a terrorist robot uprising and save the world.', 'A fan hack adding health points to the USA version.', 'Experience the challenge of Contra: Hard Corps with the fairness of the Japanese version. This hack restores hit points to the North American 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cool-spot-europe', 'Genesis', 'Cool Spot (Europe)', '1993', 'Platformer', 'Virgin Interactive', '1', 'Action', 'Side-scrolling platformer starring the 7-Up mascot.', 'Rescue your un-cool friends from cages across various levels.', 'A highly polished and vibrant corporate platformer.', 'Cool Spot is more than a mascot game; it''s a top-tier 16-bit platformer. Enjoy fluid animation, great music, and challenging levels on the Sega Genesis.');
