INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cooler-sonic-in-sonic-3-&-knuckles', 'Genesis', 'Cooler Sonic in Sonic 3 & Knuckles', '2022', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with a custom "Cooler" Sonic skin.', 'Complete Sonic 3 & Knuckles with a new visual flair.', 'A character modification for the ultimate Sonic game.', 'Cooler Sonic in Sonic 3 & Knuckles gives the blue blur a fresh aesthetic. Play through the 16-bit epic with updated sprites and a "cooler" attitude.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('corporation-europe', 'Genesis', 'Corporation (Europe)', '1992', 'Strategy', 'Core Design', '1', 'Simulation', 'First-person RPG with real-time combat and hacking.', 'Infiltrate a high-security facility and uncover a conspiracy.', 'A groundbreaking early FPS/RPG hybrid.', 'Corporation (Cyber-Cop) brings futuristic espionage to the Genesis. Master 16-bit first-person exploration, combat, and electronic hacking in this deep sci-fi sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cosmic-spacehead-usa-europe-enfrdees', 'Genesis', 'Cosmic Spacehead (USA, Europe) (En,Fr,De,Es)', '1991', 'Platformer', 'Codemasters', '1', 'Action', 'Multi-genre adventure with platforming and logic puzzles.', 'Recover your spaceship pieces to get back to your home planet.', 'A colorful and wacky adventure by Codemasters.', 'Cosmic Spacehead blends point-and-click style adventure with classic 16-bit platforming. Explore a vibrant alien world in this unique and charming Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cotton-candy-in-sonic-the-hedgehog-2', 'Genesis', 'Cotton Candy in Sonic the Hedgehog 2', '2021', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with a custom character swap.', 'Play through Sonic 2 as the fan-favorite Cotton Candy.', 'A vibrant character modification for the Sonic 2 engine.', 'Cotton Candy in Sonic the Hedgehog 2 brings a sweet visual twist to the classic sequel. Enjoy the same legendary 16-bit speed with a fresh character design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crack-down-japan', 'Genesis', 'Crack Down (Japan)', '1990', 'Action', 'Sega', '2', 'Run and Gun', 'Top-down tactical shooter with mission-based objectives.', 'Plant bombs and clear enemy bases within the time limit.', 'A port of the classic Sega arcade tactical shooter.', 'Crack Down offers tense, top-down 16-bit action. Use a variety of weapons and precise movement to sabotage enemy facilities on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crack-down-japan-rev-a', 'Genesis', 'Crack Down (Japan) (Rev A)', '1990', 'Action', 'Sega', '2', 'Run and Gun', 'Top-down tactical shooter with mission-based objectives.', 'Plant bombs and clear enemy bases within the time limit.', 'An updated revision (Rev A) of the tactical shooter.', 'Crack Down offers tense, top-down 16-bit action. Use a variety of weapons and precise movement to sabotage enemy facilities on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crack-down-usa-europe', 'Genesis', 'Crack Down (USA, Europe)', '1990', 'Action', 'Sega', '2', 'Run and Gun', 'Top-down tactical shooter with mission-based objectives.', 'Plant bombs and clear enemy bases within the time limit.', 'The North American release of the tactical arcade port.', 'Crack Down offers tense, top-down 16-bit action. Use a variety of weapons and precise movement to sabotage enemy facilities on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayon-shin-chan---arashi-o-yobu-enji-japan', 'Genesis', 'Crayon Shin-chan - Arashi o Yobu Enji (Japan)', '1993', 'Action', 'Bandai', '1', 'Platformer', 'Side-scrolling platformer with mini-games and humor.', 'Navigate the chaotic world of Shin-chan to help your family.', 'Based on the famous Japanese comedy manga and anime.', 'Crayon Shin-chan brings the series'' signature humor to the Mega Drive. Explore vibrant 16-bit levels and play wacky mini-games as the world''s naughtiest kid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cream-and-cheese-in-sonic-the-hedgehog', 'Genesis', 'Cream and Cheese in Sonic the Hedgehog', '2022', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming featuring the duo from Sonic Advance.', 'Tackle classic stages as Cream the Rabbit and Cheese the Chao.', 'A character-swap mod bringing later Sonic stars to Sonic 1.', 'Play as Cream and Cheese in Sonic the Hedgehog! Use her unique flight abilities to discover new paths in the classic 16-bit Sega masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cross-fire-usa', 'Genesis', 'Cross Fire (USA)', '1990', 'Shooter', 'Kyugo', '2', 'Vertical', 'Pseudo-3D first-person flight and combat simulation.', 'Pilot a helicopter to complete dangerous military missions.', 'An intense first-person combat helicopter sim.', 'Cross Fire (Air Diver: F-119) puts you in the cockpit for high-stakes dogfights. Master 16-bit flight controls and eliminate enemy threats in this cockpit-view action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crude-buster-japan', 'Genesis', 'Crude Buster (Japan)', '1990', 'Action', 'Data East', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up featuring two post-apocalyptic punks.', 'Fight through the city to stop the Big Valley gang.', 'A gritty arcade port known as Two Crude Dudes.', 'Crude Buster is 16-bit brawling at its most destructive. Pick up cars, enemies, and telephone poles to crush your foes in this cult classic Sega brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crue-ball---heavy-metal-pinball-usa-europe', 'Genesis', 'Crue Ball - Heavy Metal Pinball (USA, Europe)', '1992', 'Pinball', 'NuFX', '4', 'Arcade', 'Heavy metal themed pinball with interactive tables.', 'Achieve high scores and clear levels while listening to rock tracks.', 'A fast-paced pinball game featuring Mötley Crüe.', 'Crue Ball combines 16-bit pinball with a heavy metal soundtrack. Battle monsters on the table and rock out in this unique and edgy Sega Genesis title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crue-ball-japan', 'Genesis', 'Crue Ball (Japan)', '1992', 'Pinball', 'NuFX', '4', 'Arcade', 'Heavy metal themed pinball with interactive tables.', 'Achieve high scores and clear levels while listening to rock tracks.', 'The Japanese Mega Drive version of the rock pinball game.', 'Crue Ball combines 16-bit pinball with a heavy metal soundtrack. Battle monsters on the table and rock out in this unique and edgy Mega Drive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crusader-of-centy-usa', 'Genesis', 'Crusader of Centy (USA)', '1994', 'Action-Adventure', 'Nextech', '1', 'Zelda-Like', 'Top-down action-RPG with animal companions and magic.', 'Use the power of animals to save the world from monsters.', 'A beautiful and highly-rated RPG (Soleil/Shin Souseiki Ragnacenty).', 'Crusader of Centy is a masterpiece of the genre. Journey through a vibrant world, solve puzzles, and gain unique powers from your animal friends in this 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crying---aseimei-sensou-japan', 'Genesis', 'Crying - Aseimei Sensou (Japan)', '1989', 'Action', 'NCS', '1', 'Run and Gun', 'Horizontal-scrolling shoot ''em up with organic ship designs.', 'Pilot a bio-ship to destroy a rogue biological AI.', 'A deep and atmospheric biological shmup (Gynoug).', 'Crying (Gynoug) features incredible 16-bit art and grotesque bosses. Unleash magical power-ups and master the intense shmup gameplay on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crystals-pony-tale-usa', 'Genesis', 'Crystal''s Pony Tale (USA)', '1994', 'Platformer', 'Software Creations', '1', 'Action', 'Exploration-based platformer designed for younger players.', 'Rescue the other ponies and collect crystals to defeat the Storm Witch.', 'A colorful and friendly adventure starring Crystal the pony.', 'Crystal''s Pony Tale is a perfect introductory game for children. Explore vibrant 16-bit worlds and solve gentle puzzles in this charming Sega Genesis adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('curse-japan', 'Genesis', 'Curse (Japan)', '1991', 'Action', 'Taito', '1', 'Run and Gun', 'Horizontal-scrolling shoot ''em up with a focus on weapon power-ups.', 'Pilot your ship through alien-infested space to save your planet.', 'A dark and atmospheric 16-bit space shooter.', 'Curse offers intense shmup action for the Mega Drive. Master varied weapon systems and navigate haunting space environments in this visually impressive shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cursed-sonic-3-and-knuckles', 'Genesis', 'Cursed Sonic 3 and Knuckles', '2022', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with glitches and surreal environmental changes.', 'Complete the game while navigating "cursed" or corrupted levels.', 'A spooky and experimental modification of Sonic 3 & Knuckles.', 'Experience a hauntological twist on a classic with Cursed Sonic 3 and Knuckles. This mod introduces eerie visuals and unexpected 16-bit glitches for a unique challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cutie-suzuki-no-ringside-angel-japan', 'Genesis', 'Cutie Suzuki no Ringside Angel (Japan)', '1992', 'Sports', 'Human Entertainment', '1', 'Wrestling Arcade', 'One-on-one female professional wrestling simulation.', 'Win matches to become the top-ranked champion of the ring.', 'An arcade-style wrestling game starring Cutie Suzuki.', 'Cutie Suzuki no Ringside Angel brings the energy of Japanese pro-wrestling to the Mega Drive. Features fast-paced 16-bit grappling and iconic special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cutthroat-island-usa-europe', 'Genesis', 'CutThroat Island (USA, Europe)', '1995', 'Action', 'Software Creations', '1', 'Action Platformer', 'Side-scrolling action beat ''em up based on the pirate film.', 'Fight through enemies to find the hidden treasure of CutThroat Island.', 'A cinematic pirate adventure for the Sega Genesis.', 'Set sail for adventure in CutThroat Island. Master swordplay and navigate dangerous 16-bit landscapes in this movie-based action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyber-police-eswat-japan', 'Genesis', 'Cyber Police ESWAT (Japan)', '1989', 'Action', 'Sega', '1', 'Platformer', 'Side-scrolling action platformer with robotic power-ups.', 'Rise through the ranks of the police force to don the ESWAT armor.', 'A futuristic police action game (ESWAT: City Under Siege).', 'Cyber Police ESWAT delivers gritty 16-bit justice. Upgrade from a standard officer to a mechanical powerhouse in this classic Sega action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyber-cop-usa', 'Genesis', 'Cyber-Cop (USA)', '1990', 'Action', 'Core Design', '1', 'Action Platformer', 'First-person RPG and shooter with cyberpunk themes.', 'Infiltrate a high-security complex and uncover a dark conspiracy.', 'The North American version of the FPS/RPG hybrid Corporation.', 'Step into the future with Cyber-Cop. Navigate complex 3D-style corridors and use high-tech gadgets in this early 16-bit first-person adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyberball-world', 'Genesis', 'CyberBall (World)', '1992', 'Sports', 'Tengen', '4', 'Futuristic Arcade', 'Futuristic American football with robotic players and exploding balls.', 'Score touchdowns while managing your robots'' mechanical heat levels.', 'An arcade-style sports game featuring robotic athletes.', 'CyberBall brings high-tech destruction to the gridiron. Experience explosive 16-bit football where managing your robots is just as important as the score.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyborg-justice-usa-europe', 'Genesis', 'Cyborg Justice (USA, Europe)', '1993', 'Action', 'Novotrade', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with highly customizable robot parts.', 'Defeat a robotic army by tearing off and using their own limbs.', 'A unique brawler focused on mechanical customization.', 'Cyborg Justice offers unparalleled variety. Build your own robot and swap parts on the fly in this gritty and technical 16-bit Sega brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daffy-duck-in-hollywood-europe-beta', 'Genesis', 'Daffy Duck in Hollywood (Europe) (Beta)', '1994', 'Platformer', 'Probe Software', '1', 'Action', 'Side-scrolling platformer with gadget-based combat.', 'Rescue the Golden Movie Awards from the evil Duck-vaders.', 'A beta version of the cinematic Daffy Duck adventure.', 'Explore the early production of a cartoon classic with the Daffy Duck in Hollywood Beta. See early level layouts and 16-bit animation for the WB star.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daffy-duck-in-hollywood-europe-enfrdeesit', 'Genesis', 'Daffy Duck in Hollywood (Europe) (En,Fr,De,Es,It)', '1994', 'Platformer', 'Probe Software', '1', 'Action', 'Side-scrolling platformer with gadget-based combat.', 'Rescue the Golden Movie Awards from the evil Duck-vaders.', 'A vibrant and funny Looney Tunes platformer.', 'Daffy Duck in Hollywood is a technical showcase for the Genesis. Use bubble guns and unique gadgets to battle through movie-themed 16-bit levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dahna-megami-tanjou-japan', 'Genesis', 'Dahna Megami Tanjou (Japan)', '1991', 'Action', 'NCS', '1', 'Action Platformer', 'Side-scrolling action platformer with cinematic sword combat.', 'Save your kingdom from a demonic invasion led by dark gods.', 'A beautifully animated and gritty Japanese action game.', 'Dahna Megami Tanjou features massive sprites and epic 16-bit combat. Guide the warrior Dahna on a dark fantasy quest across the Mega Drive landscape.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dai-makaimura-japan', 'Genesis', 'Dai Makaimura (Japan)', '1988', 'Action', 'Capcom', '1', 'Action Platformer', 'Side-scrolling action platformer with fantasy themes.', 'Battle through the underworld to defeat the demon lord Lucifer.', 'The legendary Capcom arcade port (Ghouls ''n Ghosts).', 'Dai Makaimura is a masterclass in 16-bit challenge. Master the armor and weapon systems to survive this iconic and difficult Sega Mega Drive classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daikoukai-jidai-japan', 'Genesis', 'Daikoukai Jidai (Japan)', '1990', 'Strategy', 'Koei', '1', 'Grand Strategy', 'Naval trade and exploration simulation set in the Age of Discovery.', 'Build a fleet, discover new lands, and amass a fortune through trade.', 'A deep historical strategy sim from Koei (Uncharted Waters).', 'Daikoukai Jidai offers a massive world to explore. Manage crew and cargo as you navigate the high seas in this comprehensive 16-bit maritime simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daikoukai-jidai-ii-japan', 'Genesis', 'Daikoukai Jidai II (Japan)', '1993', 'Strategy', 'Koei', '1', 'Grand Strategy', 'Expanded naval simulation with multiple characters and stories.', 'Choose your path as a pirate, trader, or explorer in a global world.', 'The highly acclaimed sequel known as Uncharted Waters II.', 'Daikoukai Jidai II is the pinnacle of 16-bit naval strategy. Experience deep role-playing and complex economics in this massive Mega Drive epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daisenpuu-~-twin-hawk-japan-europe', 'Genesis', 'Daisenpuu ~ Twin Hawk (Japan, Europe)', '1990', 'Shooter', 'Toaplan', '2', 'Vertical', 'Top-down vertical shoot ''em up with a military theme.', 'Pilot a helicopter and use "bomber" support to clear enemy lines.', 'A classic arcade-to-home port (Twin Hawk).', 'Daisenpuu ~ Twin Hawk delivers pure 16-bit shooting action. Call in a squadron of reinforcements to help you survive this intense Mega Drive shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dangerous-seed-japan', 'Genesis', 'Dangerous Seed (Japan)', '1990', 'Shooter', 'Namco', '1', 'Vertical', 'Multi-stage vertical shooter with a transforming ship.', 'Navigate through space and alien bases to stop a galactic threat.', 'A unique shmup from Namco featuring ship upgrades.', 'Dangerous Seed features tight controls and impressive 16-bit visuals. Evolve your ship through different forms to tackle massive bosses on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('darius-ii-japan', 'Genesis', 'Darius II (Japan)', '1990', 'Shooter', 'Taito', '2', 'Horizontal', 'Side-scrolling shoot ''em up with a focus on multiple paths.', 'Pilot the Silver Hawk to destroy the aquatic robotic fleet.', 'The high-quality home port of the arcade hit (Sagaia).', 'Darius II is a shmup legend on the Mega Drive. Experience unique branching levels and giant robotic sea-creature bosses in this 16-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-castle-usa-europe', 'Genesis', 'Dark Castle (USA, Europe)', '1991', 'Action', 'Silicon & Synapse', '1', 'Action Platformer', 'Side-scrolling platforming and exploration in a gothic castle.', 'Find the shield and keys to escape the deadly Dark Castle.', 'A port of the early cinematic computer game.', 'Brave the perils of the Dark Castle on your Sega Genesis. Navigate traps and defeat the Black Knight in this challenging 16-bit action-platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-sonic-in-sonic-2', 'Genesis', 'Dark Sonic in Sonic 2', '2021', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming starring a "Dark" version of Sonic.', 'Conquer Sonic 2 stages with a new, aggressive aesthetic.', 'A character modification for the iconic Sonic 2.', 'Play as Dark Sonic in Sonic the Hedgehog 2. This mod adds a moody visual style and modified physics to the legendary 16-bit sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-sound-the-hedgehog', 'Genesis', 'Dark Sound The Hedgehog', '2022', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with a custom "Dark Sound" theme.', 'Navigate classic levels with a focus on heavy audio and visuals.', 'A stylized audio and visual overhaul of the Sonic engine.', 'Dark Sound The Hedgehog offers a unique sensory experience. Enjoy the classic 16-bit speed with a darker, more intense atmosphere and custom soundscape.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-super-sonic-in-sonic-3-&-knuckles', 'Genesis', 'Dark Super Sonic in Sonic 3 & Knuckles', '2022', 'Platformer', 'Fan Hack', '1', 'Action', 'High-speed platforming with a powerful dark transformation.', 'Use the power of Dark Super Sonic to blitz through levels.', 'A character power-up mod for Sonic 3 & Knuckles.', 'Experience the ultimate power in Dark Super Sonic for S3&K. Unleash devastating speed and new 16-bit abilities in the definitive Sonic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('darkwing-duck-unl', 'Genesis', 'Darkwing Duck (Unl)', '1992', 'Platformer', 'Capcom', '1', 'Action', 'Side-scrolling action platformer based on the Disney hero.', 'Defeat the villainous F.O.W.L. organization and save St. Canard.', 'An unlicensed 16-bit port of the Capcom NES classic.', 'Darkwing Duck comes to the Genesis! This rare unlicensed port brings the gas-gun wielding hero to 16-bit hardware for some high-flying action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('darwin-4081-japan', 'Genesis', 'Darwin 4081 (Japan)', '1990', 'Shooter', 'Data East', '2', 'Vertical', 'Vertical-scrolling shoot ''em up with an evolution mechanic.', 'Pilot your ship and "evolve" its weapons by collecting DNA.', 'A unique sci-fi shmup with organic themes.', 'Darwin 4081 offers a creative twist on the shooter genre. Change your ship''s form and fire patterns in real-time in this strategic 16-bit Mega Drive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dash-the-rabbit', 'Genesis', 'Dash The Rabbit', '2020', 'Platformer', 'Homebrew', '1', 'Action', 'High-speed platforming starring a new rabbit protagonist.', 'Use high speed and jumping skills to reach the end of the goal.', 'A custom character rom-hack for the Sonic engine.', 'Join Dash The Rabbit in a new 16-bit adventure. This mod replaces Sonic with a nimble rabbit, offering a fresh feel to the classic platforming world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dash-the-rabbit-2', 'Genesis', 'Dash The Rabbit 2', '2021', 'Platformer', 'Homebrew', '1', 'Action', 'Expanded platforming with a custom rabbit hero.', 'Navigate complex new zones with enhanced speed and power.', 'The sequel to the Dash The Rabbit character mod.', 'Dash The Rabbit 2 brings more levels and refined 16-bit physics. Experience the high-speed loops with a unique character twist on the Sega engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dash-the-rabbit-3-&-jabs', 'Genesis', 'Dash The Rabbit 3 & Jabs', '2022', 'Platformer', 'Homebrew', '1', 'Action', 'Collaborative platforming with multiple custom characters.', 'Coordinate between Dash and Jabs to clear difficult stages.', 'A multi-character team-up mod for the Genesis.', 'Dash The Rabbit 3 & Jabs introduces teamwork to the 16-bit platformer. Use unique abilities from both characters to find secret paths and defeat bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dashin-desperadoes-usa', 'Genesis', 'Dashin'' Desperadoes (USA)', '1993', 'Racing', 'Data East', '2', 'Arcade', 'Split-screen competitive platforming and racing.', 'Race through levels to win the heart of a beautiful girl.', 'A unique head-to-head racing platformer.', 'Dashin'' Desperadoes is all about competition. Sabotage your rival and navigate 16-bit hazards in this fast-paced and funny split-screen Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dashin-desperadoes-usa-beta', 'Genesis', 'Dashin'' Desperadoes (USA) (Beta)', '1993', 'Racing', 'Data East', '2', 'Arcade', 'Split-screen competitive platforming and racing.', 'Race through levels to win the heart of a beautiful girl.', 'A beta version of the competitive racer.', 'Get a head start on the race with the Dashin'' Desperadoes Beta. A fascinating look at the development of this 16-bit split-screen Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('david-cranes-amazing-tennis-usa', 'Genesis', 'David Crane''s Amazing Tennis (USA)', '1992', 'Sports', 'Imagineering', '2', 'Tennis Simulation', 'Realistic tennis simulation with a "behind-the-player" view.', 'Win international tournaments and achieve pro status.', 'A technical tennis game using the "Amazing" physics engine.', 'David Crane''s Amazing Tennis offers a unique perspective on the court. Master the 16-bit lob and smash in this realistic sports simulation for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('david-robinson-basketball-japan', 'Genesis', 'David Robinson Basketball (Japan)', '1991', 'Sports', 'Sega', '2', 'Basketball Arcade', 'Professional basketball simulation with an isometric court view.', 'Outscore opponents and win the championship with David Robinson.', 'A solid 16-bit basketball title featuring "The Admiral."', 'David Robinson Basketball delivers smooth hoops action on the Mega Drive. Master the low post and executive fast breaks in this detailed 16-bit sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('david-robinsons-supreme-court-usa-europe', 'Genesis', 'David Robinson''s Supreme Court (USA, Europe)', '1992', 'Sports', 'Sculptured Software', '4', 'Basketball Simulation', 'Professional basketball simulation with an isometric court view.', 'Outscore opponents and win the championship with David Robinson.', 'The North American release of the David Robinson sim.', 'David Robinson''s Supreme Court offers an immersive 16-bit basketball experience. Featuring signature moves and deep season modes, it’s a must-play for Genesis sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('davis-cup-ii-usa-proto', 'Genesis', 'Davis Cup II (USA) (Proto)', '1994', 'Sports', 'Loriciel', '2', 'Tennis Simulation', 'Realistic tennis simulation with various court surfaces.', 'Win the prestigious Davis Cup by defeating international pros.', 'An unreleased prototype of the tennis sequel.', 'Davis Cup II provides a rare look at the evolution of 16-bit tennis. Experience updated mechanics and refined physics in this unreleased Sega prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('davis-cup-world-tour-usa-europe-july-1993', 'Genesis', 'Davis Cup World Tour (USA, Europe) (July 1993)', '1993', 'Sports', 'Loriciel', '2', 'Tennis Simulation', 'Realistic tennis simulation with a deep tournament mode.', 'Lead your nation to victory in the global Davis Cup tour.', 'The July 1993 edition of the acclaimed tennis sim.', 'Davis Cup World Tour features impressive 16-bit character sprites and precise controls. Master the serve-and-volley game in this definitive Sega tennis classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('davis-cup-world-tour-usa-europe-june-1993', 'Genesis', 'Davis Cup World Tour (USA, Europe) (June 1993)', '1993', 'Sports', 'Loriciel', '2', 'Tennis Simulation', 'Realistic tennis simulation with a deep tournament mode.', 'Lead your nation to victory in the global Davis Cup tour.', 'The earlier June 1993 build of the tennis world tour.', 'Davis Cup World Tour features impressive 16-bit character sprites and precise controls. Master the serve-and-volley game in this definitive Sega tennis classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daze-before-christmas-australia', 'Genesis', 'Daze Before Christmas (Australia)', '1994', 'Platformer', 'Funcom', '1', 'Action', 'Side-scrolling platformer with a festive holiday theme.', 'Rescue the elves and save Christmas from an evil snowman.', 'A rare and charming platformer starring Santa Claus.', 'Daze Before Christmas is a hidden gem on the Genesis. Transform into "Anti-Santa" and battle through snowy 16-bit levels in this festive and colorful adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daze-before-christmas-australia-beta', 'Genesis', 'Daze Before Christmas (Australia) (Beta)', '1994', 'Platformer', 'Funcom', '1', 'Action', 'Side-scrolling platformer with a festive holiday theme.', 'Rescue the elves and save Christmas from an evil snowman.', 'A beta development version of the Santa platformer.', 'Explore the holiday spirit early with the Daze Before Christmas Beta. A fascinating look at the development of this rare 16-bit seasonal title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deadly-moves-usa', 'Genesis', 'Deadly Moves (USA)', '1991', 'Fighting', 'Konica', '2', 'Competitive', 'One-on-one fighting game with RPG-style stat progression.', 'Defeat a series of global challengers to become the champion.', 'A unique fighting game with a training/story mode.', 'Deadly Moves (Power Moves) combines 16-bit brawling with character growth. Travel the world and master unique special moves in this technical Genesis fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('death-and-return-of-superman-the-usa', 'Genesis', 'Death and Return of Superman, The (USA)', '1994', 'Action', 'Blizzard Entertainment', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up with multiple playable heroes.', 'Fight through the chaos following Superman''s death to stop Doomsday.', 'An epic superhero brawler based on the DC comics event.', 'The Death and Return of Superman features iconic 16-bit action. Play as the four Supermen to reclaim Metropolis in this dark and cinematic Sega brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('death-caliber', 'Genesis', 'Death Caliber', '2022', 'Action', 'Fan Hack', '1', 'Action', 'Overhead multi-directional shoot ''em up with scrolling action.', 'Survive waves of enemies in a high-stakes military mission.', 'A modified/enhanced version of the shooter Caliber .50.', 'Death Caliber ramps up the 16-bit intensity. Experience refined shooting mechanics and massive bosses in this explosive overhead action title for the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('death-duel-usa', 'Genesis', 'Death Duel (USA)', '1992', 'Action', 'Stormfront Studios', '2', 'Side-Scrolling', 'First-person cockpit-view mech combat with strategic elements.', 'Win a high-stakes futuristic duel against alien pilots.', 'A gritty and unique first-person mechanical combat game.', 'Death Duel offers a different perspective on 16-bit action. Strategically target your opponent''s systems and limbs in this intense cockpit-view fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('decapattack-usa-europe', 'Genesis', 'DecapAttack (USA, Europe)', '1991', 'Platformer', 'Vic Tokai', '1', 'Action', 'Side-scrolling platformer featuring a headless mummy.', 'Use your head as a weapon to stop the evil Max D. Cap.', 'A wacky and creative platformer (Magical Hat).', 'DecapAttack is a 16-bit cult classic. Explore bizarre levels and use power-up potions to survive this surreal and funny Sega Genesis adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('decapattack-sram', 'Genesis', 'DEcapAttack SRAM', '1991', 'Platformer', 'Vic Tokai', '1', 'Action', 'Side-scrolling platformer featuring a headless mummy.', 'Use your head as a weapon to stop the evil Max D. Cap.', 'A modified version of DecapAttack with SRAM save support.', 'Enjoy the classic 16-bit action of DecapAttack with the convenience of modern saving. Conquer the weird world of Max D. Cap without losing your progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('demolition-man-usa-europe', 'Genesis', 'Demolition Man (USA, Europe)', '1994', 'Action', 'Virgin Interactive', '1', 'Action Platformer', 'Side-scrolling run-and-gun based on the sci-fi action movie.', 'Hunt down Simon Phoenix in the futuristic city of San Angeles.', 'A cinematic action game featuring Sylvester Stallone.', 'Demolition Man brings the intensity of the movie to your Genesis. Experience 16-bit shooting and platforming in this high-octane Hollywood tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-demolition-starring-road-runner-and-wile-e-coyote-usa-europe', 'Genesis', 'Desert Demolition Starring Road Runner and Wile E. Coyote (USA, Europe)', '1994', 'Platformer', 'Virgin Interactive', '1', 'Action', 'Side-scrolling platformer with high-speed chase mechanics.', 'Play as either the Road Runner or Wile E. Coyote to win the race.', 'A beautifully animated Looney Tunes action game.', 'Desert Demolition captures the spirit of the cartoon. Experience blistering 16-bit speed and hilarious traps in this visually stunning Sega platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-strike-usa-europe', 'Genesis', 'Desert Strike (USA, Europe)', '1992', 'Simulation', 'Electronic Arts', '1', 'Combat Strategy', 'Multi-directional overhead helicopter combat and rescue.', 'Complete dangerous missions in the desert to stop a mad tyrant.', 'The legendary start of the "Strike" series by EA.', 'Desert Strike: Return to the Gulf is a 16-bit tactical masterpiece. Manage fuel and ammo while executing precise strikes in this iconic Sega Genesis hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('devil-crash-md-japan', 'Genesis', 'Devil Crash MD (Japan)', '1990', 'Pinball', 'Compile', '4', 'Arcade', 'High-octane pinball with gothic and occult themes.', 'Achieve high scores by hitting targets on an evolving table.', 'The legendary Mega Drive port of the TurboGrafx classic.', 'Devil Crash MD (Dragon''s Fury) is widely considered one of the best 16-bit pinball games. Experience incredible art and addictive gameplay on your Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('devilish---the-next-possession-usa', 'Genesis', 'Devilish - The Next Possession (USA)', '1992', 'Action', 'Opera House', '1', 'Action Platformer', 'Hybrid of brick-breaking action and side-scrolling platforming.', 'Guide the ball through levels to defeat a demonic possession.', 'A dark and creative twist on the "Breakout" formula.', 'Devilish: The Next Possession offers unique 16-bit arcade action. Move your paddle through scrolling levels to battle monsters and bosses in this gothic title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dial-q-o-mawase!-japan-unl', 'Genesis', 'Dial Q o Mawase! (Japan) (Unl)', '1993', 'Board Game', 'Unlicensed', '2', 'Tabletop', 'Adult-themed Japanese quiz game with board game elements.', 'Answer questions correctly to progress through various scenarios.', 'An unlicensed and rare Japanese trivia title.', 'Dial Q o Mawase! is a unique piece of 16-bit history. Test your knowledge in this quirky and mature-oriented quiz game for the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dick-tracy-world', 'Genesis', 'Dick Tracy (World)', '1990', 'Action', 'Titus', '1', 'Action Platformer', 'Side-scrolling action-platformer with a focus on projectile combat.', 'Take down iconic mobsters and stop the crime wave in the city.', 'A stylish noir-themed brawler based on the comic/movie.', 'Dick Tracy brings the gritty 16-bit comic world to life. Use your Tommy gun to blast through waves of gangsters in this challenging and atmospheric Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dick-vitales-awesome-baby!-college-hoops-usa', 'Genesis', 'Dick Vitale''s ''Awesome, Baby!'' College Hoops (USA)', '1993', 'Sports', 'Digital Concepts', '2', 'Basketball Simulation', 'Fast-paced college basketball with voice commentary.', 'Win the championship while hearing Vitale''s iconic catchphrases.', 'A high-energy 16-bit college hoops simulation.', 'Dick Vitale''s ''Awesome, Baby!'' College Hoops delivers the excitement of the NCAA. Experience smooth 16-bit hardwood action with "Awesome Baby" flair.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dino-dinis-soccer-europe', 'Genesis', 'Dino Dini''s Soccer (Europe)', '1993', 'Sports', 'Sports Interactive', '2', 'Soccer Simulation', 'Fast-paced side-scrolling soccer with an arcade feel.', 'Lead your team to international glory and win the Cup.', 'A quick and addictive 16-bit soccer game by Dino Dini.', 'Dino Dini''s Soccer focuses on high-speed ball control. Master the pitch and score incredible goals in this fluid and fun Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dino-fighters-beta-v01-brazil-unl', 'Genesis', 'Dino Fighters (beta v.0.1) (Brazil) (Unl)', '1994', 'Action', 'Unlicensed', '2', 'Beat ''em Up', 'Side-scrolling brawler featuring prehistoric warriors.', 'Fight through various levels to protect the dinosaur kingdom.', 'An unlicensed Brazilian prototype brawler.', 'Dino Fighters offers a unique take on the prehistoric brawler genre. Experience early 16-bit character designs and combat in this rare unlicensed prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dino-land-usa', 'Genesis', 'Dino Land (USA)', '1991', 'Action', 'Jaleco', '2', 'Arcade', 'Pinball simulation featuring prehistoric and dinosaur themes.', 'Clear targets and battle bosses across various dinosaur tables.', 'A colorful and creative 16-bit pinball adventure.', 'Dino Land combines traditional pinball mechanics with a fun dinosaur aesthetic. Aim for high scores and defeat prehistoric threats on your Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dinosaurs-tale-a-usa', 'Genesis', 'Dinosaur''s Tale, A (USA)', '1994', 'Platformer', 'Visual Concepts', '1', 'Action', 'Side-scrolling action platformer based on the animated film.', 'Navigate the city as a friendly dinosaur to reach the goal.', 'A family-friendly adventure (We''re Back! A Dinosaur''s Story).', 'A Dinosaur''s Tale features vibrant 16-bit graphics and accessible gameplay. Join the friendly dinos on a quest through the city in this charming Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dinosaurs-for-hire-usa', 'Genesis', 'Dinosaurs for Hire (USA)', '1994', 'Action', 'Malibu Interactive', '1', 'Beat ''em Up', 'Side-scrolling run-and-gun featuring dinosaur mercenaries.', 'Blast through waves of enemies and massive bosses to save Earth.', 'An explosive and stylized 16-bit action shooter.', 'Dinosaurs for Hire is pure Genesis action. Choose your dinosaur and unleash heavy weaponry in this gritty and humorous comic book adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-collection-the-europe', 'Genesis', 'Disney Collection, The (Europe)', '1996', 'Compilation', 'Disney Interactive', '1', 'Platformer', 'Compilation of several Disney-themed Sega Genesis titles.', 'Enjoy multiple Disney classics like Aladdin and Lion King in one.', 'A multi-game cartridge featuring iconic Disney hits.', 'The Disney Collection is a must-have for 16-bit fans. Experience the magic of the best Disney platformers all in one Sega Genesis package.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('divine-sealing-japan-unl', 'Genesis', 'Divine Sealing (Japan) (Unl)', '1993', 'Action', 'Unlicensed', '1', 'Arcade', 'Adult-themed tile-matching puzzle with space themes.', 'Clear the board of tiles to reveal images and progress.', 'An unlicensed Japanese puzzle game for the Mega Drive.', 'Divine Sealing offers classic 16-bit puzzle mechanics with a mature twist. Solve space-themed tile challenges in this rare and unique unlicensed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dj-boy-europe', 'Genesis', 'DJ Boy (Europe)', '1989', 'Action', 'Kaneko', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with a roller-skating theme.', 'Fight through the city as a DJ-hero to defeat the big boss.', 'A vibrant and musically-driven 16-bit brawler.', 'DJ Boy brings urban attitude to the Genesis. Skate through the streets and punch your way to the top in this colorful and rhythmic 16-bit arcade port.');
