INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doctor-robotniks-creature-capture', 'Genesis', 'Doctor Robotnik''s Creature Capture', '2021', 'Puzzle', 'Fan Hack', '1', 'Strategy', 'Puzzle-action featuring gravity-based mechanics and animal rescue.', 'Capture and secure various flickies using Robotnik''s specialized tech.', 'A creative fan-made puzzle game starring the Sonic villain.', 'Doctor Robotnik''s Creature Capture flips the script. Play as the doctor in this clever 16-bit puzzle-action hybrid that challenges your logic and timing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doctor-robotniks-plan-b', 'Genesis', 'Doctor Robotniks Plan B', '2022', 'Puzzle', 'Fan Hack', '1', 'Strategy', 'High-speed platforming with a focus on boss rush and mechanical traps.', 'Execute Robotnik''s ultimate plan by defeating Sonic and his friends.', 'A unique ROM hack focusing on the villain''s perspective.', 'Dr. Robotnik''s Plan B offers a fresh challenge for 16-bit veterans. Navigate through trap-heavy zones and experience a new side of the Sonic universe.');
