INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donald-in-maui-mallard-europe', 'Genesis', 'Donald in Maui Mallard (Europe)', '1993', 'Sports', 'Sega', '2', 'Sports', 'Side-scrolling platformer featuring a transforming protagonist.', 'Recover the stolen idol of Shabuhm Shabuhm to save the island.', 'A visually stunning Disney adventure (Maui Mallard in Cold Shadow).', 'Donald in Maui Mallard features incredible 16-bit animation. Toggle between Donald Duck and a powerful ninja in this atmospheric and high-quality platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dong-gu-ri-te-chi-jak-jeon-korea', 'Genesis', 'Dong Gu Ri Te Chi Jak Jeon (Korea)', '1993', 'Sports', 'Sega', '2', 'Sports', 'Side-scrolling platformer with colorful, child-friendly aesthetics.', 'Navigate cute levels and defeat whimsical enemies to reach the goal.', 'A rare Korean-exclusive 16-bit platformer.', 'Dong Gu Ri Te Chi Jak Jeon is a charming addition to the Mega Drive library. Experience unique Korean game design and vibrant 16-bit graphics in this obscure title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom-troopers---the-mutant-chronicles-usa', 'Genesis', 'Doom Troopers - The Mutant Chronicles (USA)', '1994', 'Platformer', 'Raise', '2', 'Action', 'Gritty side-scrolling run-and-gun with high levels of gore.', 'Eradicate the Dark Legion across various post-apocalyptic zones.', 'A violent and intense 16-bit action shooter.', 'Doom Troopers brings the tabletop RPG to life. Choose your warrior and blast through waves of mutants in one of the most graphic shooters on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon---yume-dorobou-to-7-nin-no-gozans-japan', 'Genesis', 'Doraemon - Yume Dorobou to 7 Nin no Gozans (Japan)', '1994', 'Platformer', 'Raise', '2', 'Action', 'Side-scrolling platformer with gadget-based puzzle elements.', 'Travel through dreams to rescue your friends from the dream thief.', 'A delightful Japanese adventure starring the iconic cat-robot.', 'Doraemon - Yume Dorobou to 7 Nin no Gozans features beautiful 16-bit art. Use Doraemon''s famous gadgets to solve puzzles and defeat bosses on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-clutch-europe', 'Genesis', 'Double Clutch (Europe)', '1994', 'Fighting', 'Kaneko', '2', 'Fighting', 'Top-down racing with a focus on drifting and vehicle control.', 'Win international races across various terrain and weather conditions.', 'A high-speed European top-down racing title.', 'Double Clutch offers tight 16-bit racing mechanics. Master the curves and outpace your rivals in this competitive and smooth-playing Sega racing game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon-usa-europe', 'Genesis', 'Double Dragon (USA, Europe)', '1994', 'Action', 'Blizzard Entertainment', '1', 'Action', 'Side-scrolling beat ''em up featuring the Lee brothers.', 'Rescue Marian from the Black Warriors gang.', 'The definitive 16-bit home version of the arcade classic.', 'Double Dragon on the Genesis is a brawling legend. Master the elbows, kicks, and weapon play to reclaim the streets in this quintessential Sega beat ''em up.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon-3---the-arcade-game-usa-europe', 'Genesis', 'Double Dragon 3 - The Arcade Game (USA, Europe)', '1992', 'Fighting', 'Clayton Software', '2', 'Fighting', 'Side-scrolling beat ''em up with global travel and shop systems.', 'Find the three Rosetta Stones to stop a global conspiracy.', 'The third entry in the legendary Double Dragon series.', 'Double Dragon 3 brings new combatants and weapon shops to the 16-bit era. Journey across the world and sharpen your skills in this challenging Sega sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon-ii---the-revenge-japan', 'Genesis', 'Double Dragon II - The Revenge (Japan)', '1992', 'Fighting', 'Clayton Software', '2', 'Fighting', 'Side-scrolling beat ''em up with updated moves and animations.', 'Avenge Marian and take down the mysterious Shadow Warriors.', 'The Japanese Mega Drive version of the iconic sequel.', 'Double Dragon II - The Revenge is a high-octane 16-bit brawler. Experience the improved "Hyper Knee" and cinematic story sequences in this classic Mega Drive port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon-v---the-shadow-falls-usa', 'Genesis', 'Double Dragon V - The Shadow Falls (USA)', '1991', 'Platformer', 'Vic Tokai', '1', 'Action', 'One-on-one fighting game based on the animated series.', 'Defeat the Shadow Master''s minions to win the tournament.', 'A competitive fighter featuring the Double Dragon cast.', 'Double Dragon V - The Shadow Falls brings the Lee brothers into a traditional 16-bit fighter. Master unique special moves and take down the Shadow Master.');